)}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:binom(n,k)}}","acceptCombinatorialNotation":true}],"statement":"Combien de mots de ${{n}}$ lettres peut-on écrire avec exactement ${{k}}$ lettres $\\mathrm{A}$ et ${{eval:n-k}}$ lettres $\\mathrm{B}$ ?\n\n$?$","variables":[{"name":"n","expression":"6..12"},{"name":"k","expression":"2..{{eval:n-2}}"}],"correction":{"steps":["Un tel mot est déterminé par les positions des ${{k}}$ lettres $\\mathrm{A}$ parmi les ${{n}}$ places : une partie à ${{k}}$ éléments.","$\\binom{ {{n}} }{ {{k}} }=\\textcolor{{{color:primary.0}}}{{{eval:binom(n,k)}}}$."]}}],"shared":null,"test_specs":[{"answers":["35"],"expected":{"status":"correct"},"variables":{"p":"4","q":"3"},"description":"v0 : B(4 ; 3) → 35","variationIndex":0},{"answers":["128"],"expected":{"status":"incorrect"},"variables":{"p":"4","q":"3"},"description":"v0 : 2⁷ = 128","variationIndex":0},{"answers":["5040"],"expected":{"status":"incorrect"},"variables":{"p":"4","q":"3"},"description":"v0 : 7! = 5040","variationIndex":0},{"answers":["12"],"expected":{"status":"incorrect"},"variables":{"p":"4","q":"3"},"description":"v0 : 4 × 3 = 12","variationIndex":0},{"answers":["60"],"expected":{"status":"correct"},"variables":{"a":"2","b":"1","p":"5","q":"4"},"description":"v1 : B(5 ; 4), C(2 ; 1) → 3 × 20 = 60","variationIndex":1},{"answers":["23"],"expected":{"status":"incorrect"},"variables":{"a":"2","b":"1","p":"5","q":"4"},"description":"v1 : somme 3 + 20","variationIndex":1},{"answers":["126"],"expected":{"status":"incorrect"},"variables":{"a":"2","b":"1","p":"5","q":"4"},"description":"v1 : tous les chemins 126","variationIndex":1},{"answers":["56"],"expected":{"status":"correct"},"variables":{"k":"3","n":"8"},"description":"v2 : 8 lettres, 3 A → 56","variationIndex":2},{"answers":["256"],"expected":{"status":"incorrect"},"variables":{"k":"3","n":"8"},"description":"v2 : 2⁸ = 256","variationIndex":2},{"answers":["336"],"expected":{"status":"incorrect"},"variables":{"k":"3","n":"