me":"c3","expression":"{{eval:p1*q2-p2*q1}}"},{"name":"g","expression":"{{eval:gcd(gcd(abs(c1),abs(c2)),abs(c3))}}"},{"name":"n1","expression":"{{eval:c1/g}}"},{"name":"n2","expression":"{{eval:c2/g}}"},{"name":"n3","expression":"{{eval:c3/g}}"}],"conditions":["abs(p2*q3-p3*q2)+abs(p3*q1-p1*q3)+abs(p1*q2-p2*q1) > 0"],"correction":{"steps":["$\\vec{n}$ est normal à $(ABC)$ si et seulement si $\\vec{n}\\cdot\\overrightarrow{AB}=0$ et $\\vec{n}\\cdot\\overrightarrow{AC}=0$, avec $\\overrightarrow{AB}\\begin{pmatrix}{{p1}}\\\\{{p2}}\\\\{{p3}}\\end{pmatrix}$ et $\\overrightarrow{AC}\\begin{pmatrix}{{q1}}\\\\{{q2}}\\\\{{q3}}\\end{pmatrix}$.","En résolvant ce système (on fixe une coordonnée), on trouve par exemple $\\textcolor{{{color:primary.0}}}{ \\vec{n}\\begin{pmatrix}{{n1}}\\\\{{n2}}\\\\{{n3}}\\end{pmatrix} }$. Vérification : $\\vec{n}\\cdot\\overrightarrow{AB}={{n1}}\\times{{p1;()}}+{{n2;()}}\\times{{p2;()}}+{{n3;()}}\\times{{p3;()}}=0$, de même $\\vec{n}\\cdot\\overrightarrow{AC}=0$."]}},{"blanks":[{"expectedAnswer":"({{n1}};{{n2}};{{n3}})"}],"statement":"Dans l'espace muni d'un repère orthonormé, on considère les plans sécants $\\mathcal{P}$ et $\\mathcal{Q}$ d'équations respectives ${{a1}}x+({{a2}})y+({{a3}})z+({{d}})=0$ et ${{b1}}x+({{b2}})y+({{b3}})z+({{q}})=0$.\n\nDonne un vecteur directeur de leur droite d'intersection : $?$","variables":[{"name":"a1","expression":"-3..3"},{"name":"a2","expression":"-3..3"},{"name":"a3","expression":"-3..3"},{"name":"b1","expression":"-3..3"},{"name":"b2","expression":"-3..3"},{"name":"b3","expression":"-3..3"},{"name":"d","expression":"-6..6"},{"name":"q","expression":"-6..6"},{"name":"c1","expression":"{{eval:a2*b3-a3*b2}}"},{"name":"c2","expression":"{{eval:a3*b1-a1*b3}}"},{"name":"c3","expression":"{{eval:a1*b2-a2*b1}}"},{"name":"g","expression":"{{eval:gcd(gcd(abs(c1),abs(c2)),abs(c3))}}"},{"name":"n1","expression":"{{eval:c1/g}}"},{"name":"n2","expression":"{{eval:c2/g}}"},{"name":"n3","expression":"{{eval:c3/g}}"}],"conditions":["abs(a2*b3-a3*b2)+abs(a3*b1-a1*b3)+abs(a1*b2-a2*b1) > 0","abs(a1)+abs(a2)+abs(a3) > 1","abs(b1)+abs(b2)+abs(b3) > 1"],"correction":{"steps":["La droite d'intersection est contenue dans les deux plans : son vecteur directeur $\\vec{u}$ est orthogonal aux deux vecteurs normaux $\\vec{n}_1\\begin{pmatrix}{{a1}}\\\\{{a2}}\\\\{{a3}}\\end{pmatrix}$ et $\\vec{n}_2\\begin{pmatrix}{{b1}}\\\\{{b2}}\\\\{{b3}}\\end{pmatrix}$.","En résolvant $\\vec{u}\\cdot\\vec{n}_1=0$, $\\vec{u}\\cdot\\vec{n}_2=0$, on trouve par exemple $\\textcolor{{{color:primary.0}}}{ \\vec{u}\\begin{pmatrix}{{n1}}\\\\{{n2}}\\\\{{n3}}\\end{pmatrix} }$ (vérification : ${{a1}}\\times{{n1;()}}+{{a2;()}}\\times{{n2;()}}+{{a3;()}}\\times{{n3;()}}=0$, de même avec $\\vec{n}_2$)."]}}],"shared":{"blankDefaults":{"answerKind":"vecteur","vectorMode":"colineaire"},"cleanCoefficients":true},"test_specs":[{"answers":["(2;-3;1)"],"expected":{"status":"correct"},"variables":{"ax":"1","ay":"2","az":"-1","bx":"3","by":"-1","bz":"0"},"description":"v0 : AB(2 ; -3 ; 1)","variationIndex":0},{"answers":["(-2;3;-1)"],"expected":{"status":"correct"},"variables":{"ax":"1","ay":"2","az":"-1","bx":"3","by":"-1","bz":"0"},"description":"v0 : BA","variationIndex":0},{"answers":["(1;2;-1)"],"expected":{"status":"incorrect"},"variables":{"ax":"1","ay":"2","az":"-1","bx":"3","by":"-1","bz":"0"},"description":"v0 : point A donné","variationIndex":0},{"answers":["(4;1;-1)"],"expected":{"status":"incorrect"},"variables":{"ax":"1","ay":"2","az":"-1","bx":"3","by":"-1","bz":"0"},"description":"v0 : A + B","variationIndex":0},{"answers":["(1;-3;2)"],"expected":{"status":"correct"},"variables":{"a":"1","b":"-3","c":"2","d":"4","ax":"2","ay":"-1","az":"0"},"description":"v1 : (1 ; -3 ; 2)","variationIndex":1},{"answers":["(-2;6;-4)"],"expected":{"status":"correct"},"variables":{"a":"1","b":"-3","c":"2","d":"4","ax":"2","ay":"-1","az":"0"},"description":"v1 : multiple","variationIndex":1},{"answers":["(2;-1;0)"],"expected":{"status":"in