a sphère vérifie $R^2={{R2}}$ ; par Pythagore dans le triangle $\\Omega HM$ : $\\rho^2=R^2-\\delta^2={{R2}}-{{eval:delta^2}}={{eval:rho^2}}$, donc $\\textcolor{{{color:primary.0}}}{ \\rho={{rho}} }$."]}}],"shared":{"cleanCoefficients":true},"test_specs":[{"answers":["2"],"expected":{"status":"correct"},"variables":{"a":"1","b":"-2","c":"0","k":"2","p":"2","q":"-1"},"description":"v0 : t = 2","variationIndex":0},{"answers":["-2"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"-2","c":"0","k":"2","p":"2","q":"-1"},"description":"v0 : solution t < c (−2)","variationIndex":0},{"answers":["4"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"-2","c":"0","k":"2","p":"2","q":"-1"},"description":"v0 : (t−c)² donné (4)","variationIndex":0},{"answers":["1","-2","0","4"],"expected":{"status":"correct"},"variables":{"a":"1","b":"-2","c":"3","s":"-3","rho":"4"},"description":"v1 : centre et rayon","variationIndex":1},{"answers":["1","-2","3","4"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"-2","c":"3","s":"-3","rho":"4"},"description":"v1 : centre Ω au lieu de H","variationIndex":1},{"answers":["1","-2","0","16"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"-2","c":"3","s":"-3","rho":"4"},"description":"v1 : ρ² au lieu de ρ","variationIndex":1},{"answers":["1","-2","0","\\sqrt{16}"],"expected":{"status":"unoptimal_form","constraintViolations":["reducedRadicals"]},"variables":{"a":"1","b":"-2","c":"3","s":"-3","rho":"4"},"description":"v1 : ρ = √16 non calculé","variationIndex":1},{"answers":["1","-2","0","5"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"-2","c":"3","s":"-3","rho":"4"},"description":"v1 : R au lieu de ρ","variationIndex":1},{"answers":["2","4"],"expected":{"status":"correct"},"variables":{"a":"1","b":"0","c":"-1","s2":"1","s3":"-1","rho":"4","delta":"2"},"description":"v2 : δ = 2, ρ = 4","variationIndex":2},{"answers":["6","4"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"0","c":