(b,2) + mod(c,2) >= 1"],"correction":{"steps":["${{eval:2^a*3^b*5^c}} = 2^{ {{a}} } \\times 3^{ {{b}} } \\times 5^{ {{c}} }$.","Un carré a tous ses exposants pairs : on complète chaque exposant impair par un facteur.","$k = \\textcolor{{{color:primary.0}}}{{{eval:2^(mod(a,2))*3^(mod(b,2))*5^(mod(c,2))}}}$."]}}],"shared":null,"test_specs":[{"answers":["2^3\\times3^2\\times5"],"expected":{"status":"correct"},"variables":{"a":"3","b":"2","q":"5"},"description":"v0 : 360 = 2³ × 3² × 5","variationIndex":0},{"answers":["5\\times3^2\\times2^3"],"expected":{"status":"correct"},"variables":{"a":"3","b":"2","q":"5"},"description":"v0 : ordre des facteurs libre","variationIndex":0},{"answers":["2^3\\cdot3^2\\cdot5"],"expected":{"status":"correct"},"variables":{"a":"3","b":"2","q":"5"},"description":"v0 : avec \\cdot","variationIndex":0},{"answers":["360"],"expected":{"status":"bad_form","constraintViolations":["form"]},"variables":{"a":"3","b":"2","q":"5"},"description":"v0 : 360 non décomposé","variationIndex":0},{"answers":["8\\times45"],"expected":{"status":"bad_form","constraintViolations":["form"]},"variables":{"a":"3","b":"2","q":"5"},"description":"v0 : 8 × 45","variationIndex":0},{"answers":["2^3\\times9\\times5"],"expected":{"status":"bad_form","constraintViolations":["form"]},"variables":{"a":"3","b":"2","q":"5"},"description":"v0 : 9 n'est pas premier","variationIndex":0},{"answers":["2\\times2\\times2\\times3\\times3\\times5"],"expected":{"status":"bad_form","constraintViolations":["form"]},"variables":{"a":"3","b":"2","q":"5"},"description":"v0 : sans puissances","variationIndex":0},{"answers":["2^3\\times3\\times5"],"expected":{"status":"incorrect"},"variables":{"a":"3","b":"2","q":"5"},"description":"v0 : exposant faux","variationIndex":0},{"answers":["36"],"expected":{"status":"correct"},"variables":{"a":"3","b":"2","c":"2"},"description":"v1 : 2³×3²×5² → 36","variationIndex":1},{"answers":["12"],"expected":{"status":"incorrect"},"variables":{"a":"3","b":"2","c