--   ('68166a11-b481-44cc-b881-07252a6fb98f'::uuid, $plsc${"title":"Valeurs et signe de l'exponentielle","description":"QCM : e⁰ = 1, eˣ > 0 pour tout x, valeur approchée de e","variations":[{"choices":[{"content":"$0$"},{"content":"$1$"},{"content":"$e$"},{"content":"Ce nombre n'existe pas."}],"statement":"Que vaut $e^0$ ?","variables":[],"correction":{"steps":["Par définition, la fonction exponentielle vaut $1$ en $0$ : $\\textcolor{{{color:primary.0}}}{e^0=1 }$."]},"correctChoiceIndex":["1"]},{"choices":[{"content":"Vrai"},{"content":"Faux"}],"statement":"Vrai ou faux ? Pour tout réel $x$, $e^x>0$.","variables":[],"correction":{"steps":["La fonction exponentielle est **strictement positive** sur $\\mathbb{R}$ : pour tout réel $x$, $\\textcolor{{{color:primary.0}}}{e^x>0 }$. C'est **vrai**."]},"correctChoiceIndex":["0"]},{"choices":[{"content":"Vrai"},{"content":"Faux"}],"statement":"Vrai ou faux ? Le nombre $e^{ {{a}} }$ est négatif.","variables":[{"name":"a","expression":"-9..-1"}],"correction":{"steps":["L'exposant ${{a}}$ est négatif, mais une exponentielle est **toujours strictement positive** : $\\textcolor{{{color:primary.0}}}{e^{ {{a}} }>0 }$.","C'est **faux** : $e^{ {{a}} }=\\dfrac{1}{e^{ {{eval:-a}} }}$ est un nombre compris entre $0$ et $1$."]},"correctChoiceIndex":["1"]},{"choices":[{"content":"Vrai"},{"content":"Faux"}],"statement":"Vrai ou faux ? Pour tout réel $x$, $e^x\\geqslant1$.","variables":[],"correction":{"steps":["$e^x\\geqslant1$ seulement pour $x\\geqslant0$. Par exemple $e^{-1}=\\dfrac{1}{e}\\approx0{,}37<1$.","C'est **faux** : on sait seulement que $\\textcolor{{{color:primary.0}}}{e^x>0 }$ pour tout réel $x$."]},"correctChoiceIndex":["1"]},{"choices":[{"content":"$2{,}718$"},{"content":"$3{,}142$"},{"content":"$2{,}178$"},{"content":"$1{,}414$"}],"statement":"Quelle est la valeur approchée de $e=e^1$ au millième près ?","variables":[],"correction":{"steps":["$\\textcolor{{{color:primary.0}}}{e\\approx2{,}718 }$. Attention : $3{,}142$ est une valeur approchée de $\\pi$, et $1{,}414$ de $\\sqrt2$."]},"correctChoiceIndex":["0"]}],"shared":null,"test_specs":[{"expected":{"status":"incorrect"},"variables":{},"description":"variation 0 : choix 0 refusé","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{},"description":"variation 0 : choix 1 accepté","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{},"description":"variation 0 : choix 2 refusé","variationIndex":0,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{},"description":"variation 0 : choix 3 refusé","variationIndex":0,"selectedChoices":[3]},{"expected":{"status":"correct"},"variables":{},"description":"variation 1 : choix 0 accepté","variationIndex":1,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{},"description":"variation 1 : choix 1 refusé","variationIndex":1,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"-3"},"description":"variation 2 : choix 0 refusé","variationIndex":2,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"a":"-3"},"description":"variation 2 : choix 1 accepté","variationIndex":2,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{},"description":"variation 3 : choix 0 refusé","variationIndex":3,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{},"description":"variation 3 : choix 1 accepté","variationIndex":3,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{},"description":"variation 4 : choix 0 accepté","variationIndex":4,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{},"description":"variation 4 : choix 1 refusé","variationIndex":4,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{},"description":"variation 4 : choix 2 refusé","variationIndex":4,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{},"description":"variation 4 : choix 3 