|3|{{if:w==3|4|{{if:w==4|5|{{if:w==5|2|{{if:w==6|4|{{if:w==7|3|6}}}}}}}}}}}}}}"}],"correction":{"steps":["$V(X)=np(1-p)={{n}}\\times{{p}}\\times{{eval:1-pp;d}}={{eval:s^2}}$.","$\\sigma(X)=\\sqrt{V(X)}=\\sqrt{ {{eval:s^2}} }=\\textcolor{{{color:primary.0}}}{{{s}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:c*(q-c)/q^2}}"}],"statement":"La variable aléatoire $X$ suit la loi de Bernoulli de paramètre $p=\\dfrac{ {{c}} }{ {{q}} }$.\n\nCalcule sa variance.\n\n$V(X)=?$","variables":[{"name":"q","expression":"3..8"},{"name":"c","expression":"1..{{eval:q-1}}"}],"conditions":["gcd(c, q) == 1"],"correction":{"steps":["Pour une loi de Bernoulli : $E(X)=p$ et $V(X)=p(1-p)$.","$V(X)=\\dfrac{ {{c}} }{ {{q}} }\\times\\dfrac{ {{eval:q-c}} }{ {{q}} }=\\textcolor{{{color:primary.0}}}{{{eval:c*(q-c)/q^2}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:n/q}}"}],"statement":"Un questionnaire comporte ${{n}}$ questions ; pour chacune, ${{q}}$ réponses sont proposées, dont une seule est juste. Un élève répond au hasard à chaque question, indépendamment.\n\nCombien de bonnes réponses peut-il espérer en moyenne ?\n\n$?$","variables":[{"name":"n","expression":"10|12|15|20|24|30|40"},{"name":"q","expression":"2..5"}],"correction":{"steps":["Le nombre $X$ de bonnes réponses suit la loi $\\mathcal{B}\\left({{n}}\\,;\\dfrac{1}{ {{q}} }\\right)$.","$E(X)=np={{n}}\\times\\dfrac{1}{ {{q}} }=\\textcolor{{{color:primary.0}}}{{{eval:n/q}}}$ bonnes réponses en moyenne."]}}],"shared":{"blankDefaults":{"acceptDecimal":true}},"test_specs":[{"answers":["15"],"expected":{"status":"correct"},"variables":{"n":"50","t":"30"},"description":"v0 : B(50 ; 0,3) → 15","variationIndex":0},{"answers":["10,5"],"expected":{"status":"incorrect"},"variables":{"n":"50","t":"30"},"description":"v0 : variance 10,5 au lieu de E","variationIndex":0},{"answers":["2,8"],"expected":{"status":"correct"},"variables":{"n":"40","t":"7"},"description":"v0 : B(40 ; 0,07) → 2,8","variationIndex":0},{"answers":["8"],"expected":{"status":"correct"},"variables":{"n":"50","t":"2"},"description":"v1 : B(50 ; 0,2) → 8","variationIndex":1},{"answers":["10"],"expected":{"status":"incorrect"},"variables":{"n":"50","t":"2"},"description":"v1 : np = 10 au lieu de np(1 − p)","variationIndex":1},{"answers":["\\sqrt{8}"],"expected":{"status":"incorrect"},"variables":{"n":"50","t":"2"},"description":"v1 : écart type √8","variationIndex":1},{"answers":["2,1"],"expected":{"status":"correct"},"variables":{"n":"10","t":"3"},"description":"v1 : B(10 ; 0,3) → 2,1","variationIndex":1},{"answers":["4"],"expected":{"status":"correct"},"variables":{"w":"6"},"description":"v2 : B(100 ; 0,2) → 4","variationIndex":2},{"answers":["16"],"expected":{"status":"incorrect"},"variables":{"w":"6"},"description":"v2 : variance 16","variationIndex":2},{"answers":["\\sqrt{16}"],"expected":{"status":"unoptimal_form","constraintViolations":["reducedRadicals"]},"variables":{"w":"6"},"description":"v2 : √16 non calculé","variationIndex":2},{"answers":["\\frac{3}{16}"],"expected":{"status":"correct"},"variables":{"c":"1","q":"4"},"description":"v3 : p = 1/4 → 3/16","variationIndex":3},{"answers":["\\frac{1}{4}"],"expected":{"status":"incorrect"},"variables":{"c":"1","q":"4"},"description":"v3 : E = p","variationIndex":3},{"answers":["\\frac{1}{16}"],"expected":{"status":"incorrect"},"variables":{"c":"1","q":"4"},"description":"v3 : p²","variationIndex":3},{"answers":["5"],"expected":{"status":"correct"},"variables":{"n":"20","q":"4"},"description":"v4 : 20 questions, 4 réponses → 5","variationIndex":4},{"answers":["15"],"expected":{"status":"incorrect"},"variables":{"n":"20","q":"4"},"description":"v4 : n(1 − p) = 15","variationIndex":4}]}$plsc$::jsonb),
--   ('dd0ee69a-2203-47a3-b2b8-af70a77281d3'::uuid, $plsc${"title":"Encadrer une intégrale ou une valeur moyenne","description":"m ≤ f ≤ M sur [a ; b] donne m(b − a) ≤ ∫ₐᵇ f ≤ M(b − a) et m ≤ μ ≤ M ; lecture sur une courbe (piège : oubli de la longueur b − a)","variations":[{"blanks":[{"expectedAnswer":"{{eval:m*(b-a)}}"},{"expectedAnswer":"{{eval:M*(b-a)}}"}],"statement":"$f$ est une fonction continue sur $\\left[{{a}}\\,;{{b}}\\right]$ telle que, pour tout $x$ de cet intervalle, ${{m}}\\leqslant f(x)\\leqslant {{M}}$.\n\nComplète l'encadrement le plus précis que l'on peut en déduire :\n\n$?\\leqslant\\displaystyle\\int_{{{a}}}^{{{b}}}f(x)\\,\\mathrm{d}x\\leqslant ?$","variables":[{"name":"a","expression":"-2..1"},{"name":"b","expression":"2..5"},{"name":"m","expression":"-3..3"},{"name":"M","expression":"2..8"}],"conditions":["m < M"],"correction":{"steps":["On intègre l'encadrement sur $\\left[{{a}}\\,;{{b}}\\right]$, intervalle de longueur ${{b}}-{{a;()}}={{eval:b-a}}$ (bornes dans le bon ordre).","$\\displaystyle\\int_{{{a}}}^{{{b}}}{{m}}\\,\\mathrm{d}x\\leqslant\\displaystyle\\int_{{{a}}}^{{{b}}}f(x)\\,\\mathrm{d}x\\leqslant\\displaystyle\\int_{{{a}}}^{{{b}}}{{M}}\\,\\mathrm{d}x$, soit $\\textcolor{{{color:primary.0}}}{{{eval:m*(b-a)}}}\\leqslant\\displaystyle\\int_{{{a}}}^{{{b}}}f(x)\\,\\mathrm{d}x\\leqslant\\textcolor{{{color:primary.0}}}{{{eval:M*(b-a)}}}$."]}},{"blanks":[{"expectedAnswer":"{{p}}"},{"expectedAnswer":"{{q}}"}],"statement":"$f$ est une fonction continue et croissante sur $\\left[{{a}}\\,;{{b}}\\right]$, avec $f({{a}})={{p}}$ et $f({{b}})={{q}}$. On note $\\mu$ sa valeur moyenne sur cet intervalle.\n\nComplète l'encadrement le plus précis que l'on peut en déduire :\n\n$?\\leqslant\\mu\\leqslant ?$","variables":[{"name":"a","expression":"-2..1"},{"name":"b","expression":"3..6"},{"name":"p","expression":"-4..2"},{"name":"q","expression":"3..9"}],"correction":{"steps":["$f$ est croissante : pour tout $x$ de $\\left[{{a}}\\,;{{b}}\\right]$, ${{p}}\\leqslant f(x)\\leqslant {{q}}$.","La valeur moyenne est comprise entre les bornes de $f$ : $\\textcolor{{{color:primary.0}}}{{{p}}}\\leqslant\\mu\\leqslant\\textcolor{{{color:primary.0}}}{{{q}}}$. (C'est l'**intégrale** qui vaut entre ${{eval:p*(b-a)}}$ et ${{eval:q*(b-a)}}$.)"]}},{"blanks":[{"expectedAnswer":"{{eval:3*c/4}}"},{"expectedAnswer":"{{eval:3*c}}"}],"statement":"On a représenté ci-dessous la courbe $\\mathcal{C}_f$ de la fonction $f:x\\mapsto\\dfrac{ {{c}} }{x+1}$, décroissante sur $\\left[0\\,;3\\right]$.\n\n```courbe\nx: -0.5 ; 4\ny: -0.5 ; {{eval:c+1}}\ngrille: 1 ; 1\nf(x) = {{c}}/(x+1) sur [0 ; 3]   bleu   nom=C_f\npoints: A(0 ; {{c}}), B(3 ; {{eval:c/4}})\naire: f ; 0 ; 3\ntaille: moyenne\ndescription: Courbe décroissante d'une fonction inverse décalée sur [0 ; 3], aire sous la courbe coloriée.\n```\n\nComplète l'encadrement le plus précis que l'on peut déduire des valeurs $f(0)$ et $f(3)$ :\n\n$?\\leqslant\\displaystyle\\int_{0}^{3}f(x)\\,\\mathrm{d}x\\leqslant ?$","variables":[{"name":"c","expression":"4|8"}],"correction":{"steps":["$f$ est décroissante sur $\\left[0\\,;3\\right]$ : $f(3)={{eval:c/4}}\\leqslant f(x)\\leqslant f(0)={{c}}$.","L'aire coloriée est entre celles des rectangles de largeur $3$ et de hauteurs ${{eval:c/4}}$ et ${{c}}$ : $\\textcolor{{{color:primary.0}}}{{{eval:3*c/4}}}\\leqslant\\displaystyle\\int_{0}^{3}f(x)\\,\\mathrm{d}x\\leqslant\\textcolor{{{color:primary.0}}}{{{eval:3*c}}}$."]}}],"shared":{"blankDefaults":{"acceptDecimal":true},"cleanCoefficients":true},"test_specs":[{"answers":["3","12"],"expected":{"status":"correct"},"variables":{"M":"4","a":"0","b":"3","m":"1"},"description":"v0 : 1 ≤ f ≤ 4 sur [0;3] → 3 et 12","variationIndex":0},{"answers":["1","4"],"expected":{"status":"incorrect"},"variables":{"M":"4","a":"0","b":"3","m":"1"},"description":"v0 : longueur oubliée","variationIndex":0},{"answers":["3","12"],"expected":{"status":"incorrect"},"variables":{"M":"4","a":"-1","b":"3","m":"1"},"description":"v0 : largeur b au lieu de b−a","variationIndex":0},{"answers":["4","16"],"expected":{"status":"correct"},"variables":{"M":"4","a":"-1","b":"3","m":"1"},"description":"v0 : a=−1 → 4 et 16","variationIndex":0},{"answers":["-6","10"],"expected":{"status":"correct"},"variables":{"M":"5","a":"0","b":"2","m":"-3"},"description":"v0 : m<0","variationIndex":0},{"answers":["2","7"],"expected":{"status":"correct"},"variables":{"a":"0","b":"4","p":"2","q":"7"},"description":"v1 : 2 ≤ μ ≤ 7","variationIndex":1},{"answers":["8","28"],"expected":{"status":"incorrect"},"variables":{"a":"0","b":"4","p":"2","q":"7"},"description":"v1 : bornes de l'intégrale au lieu de μ","variationIndex":1},{"answers":["3","12"],"expected":{"status":"correct"},"variables":{"c":"4"},"description":"v2 : c=4 → 3 et 12","variationIndex":2},{"answers":["12","3"],"expected":{"status":"incorrect"},"variables":{"c":"4"},"description":"v2 : bornes inversées","variationIndex":2},{"answers":["1","4"],"expected":{"status":"incorrect"},"variables":{"c":"4"},"description":"v2 : valeurs de f sans la largeur","variationIndex":2}]}$plsc$::jsonb),
--   ('dfb727cd-c55b-439c-8738-0e20484369c5'::uuid, $plsc${"title":"Nombre de parties d'un ensemble : 2 puissance n","description":"Parties d'un ensemble à n éléments, mots binaires, garnitures (avec ou sans partie vide), issues de n épreuves de Bernoulli (pièges : 2n, n², oubli ou ajout à tort de la partie vide)","variations":[{"blanks":[{"expectedAnswer":"{{eval:2^n}}"}],"statement":"Un ensemble $E$ contient ${{n}}$ éléments.\n\nCombien de parties (sous-ensembles) possède-t-il, en comptant l'ensemble vide et $E$ lui-même ?\n\n$?$","variables":[{"name":"n","expression":"3..12"}],"correction":{"steps":["Former une partie, c'est décider pour chacun des ${{n}}$ éléments s'il est dedans ou non : $2$ choix, ${{n}}$ fois.","$2^{ {{n}} }=\\textcolor{{{color:primary.0}}}{{{eval:2^n}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:2^n}}"}],"statement":"Un mot binaire est une suite de chiffres $0$ ou $1$.\n\nCombien de mots binaires de longueur ${{n}}$ existe-t-il ?\n\n$?$","variables":[{"name":"n","expression":"4..16"}],"correction":{"steps":["Un mot binaire de longueur ${{n}}$ est un ${{n}}$-uplet de $\\{0,1\\}$ (c'est aussi une partie de $\\{1,\\dots,{{n}}\\}$ : les positions des $1$).","$2^{ {{n}} }=\\textcolor{{{color:primary.0}}}{{{eval:2^n}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:2^n}}"}],"statement":"Une pizzeria propose ${{n}}$ garnitures. Le client choisit les garnitures de sa pizza (chacune au plus une fois) ; il peut aussi n'en prendre **aucune** (pizza nature).\n\nCombien de pizzas différentes peut-il commander ?\n\n$?$","variables":[{"name":"n","expression":"5..10"}],"correction":{"steps":["Une pizza correspond à une partie de l'ensemble des ${{n}}$ garnitures, la partie vide (pizza nature) comprise.","$2^{ {{n}} }=\\textcolor{{{color:primary.0}}}{{{eval:2^n}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:2^n-1}}"}],"statement":"Une pizzeria propose ${{n}}$ garnitures. Le client choisit les garnitures de sa pizza (chacune au plus une fois) et en prend **au moins une**.\n\nCombien de pizzas différentes peut-il commander ?\n\n$?$","variables":[{"name":"n","expression":"5..10"}],"correction":{"steps":["Une pizza correspond à une partie **non vide** de l'ensemble des ${{n}}$ garnitures.","Il y a $2^{ {{n}} }$ parties, dont une seule vide : $2^{ {{n}} }-1=\\textcolor{{{color:primary.0}}}{{{eval:2^n-1}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:2^n}}"}],"statement":"On lance ${{n}}$ fois une pièce et on note la suite des résultats (Pile ou Face). On représente l'expérience par un arbre.\n\nCombien de chemins comporte cet arbre ?\n\n$?$","variables":[{"name":"n","expression":"3..10"}],"correction":{"steps":["Chaque lancer double le nombre de branches : chaque chemin est un ${{n}}$-uplet de $\\{P,F\\}$.","$2^{ {{n}} }=\\textcolor{{{color:primary.0}}}{{{eval:2^n}}}$ chemins."]}}],"shared":null,"test_specs":[{"answers":["32"],"expected":{"status":"correct"},"variables":{"n":"5"},"description":"v0 : n = 5 → 32","variationIndex":0},{"answers":["2^5"],"expected":{"status":"bad_form","constraintViolations":["form"]},"variables":{"n":"5"},"description":"v0 : écrit 2^5","variationIndex":0},{"answers":["10"],"expected":{"status":"incorrect"},"variables":{"n":"5"},"description":"v0 : 2n = 10","variationIndex":0},{"answers":["25"],"expected":{"status":"incorrect"},"variables":{"n":"5"},"description":"v0 : n² = 25","variationIndex":0},{"answers":["31"],"expected":{"status":"incorrect"},"variables":{"n":"5"},"description":"v0 : 2⁵ − 1 (partie vide oubliée)","variationIndex":0},{"answers":["256"],"expected":{"status":"correct"},"variables":{"n":"8"},"description":"v1 : n = 8 → 256","variationIndex":1},{"answers":["64"],"expected":{"status":"incorrect"},"variables":{"n":"8"},"description":"v1 : 8² = 64","variationIndex":1},{"answers":["64"],"expected":{"status":"correct"},"variables":{"n":"6"},"description":"v2 : n = 6 → 64","variationIndex":2},{"answers":["63"],"expected":{"status":"incorrect"},"variables":{"n":"6"},"description":"v2 : 63 (pizza nature oubliée)","variationIndex":2},{"answers":["720"],"expected":{"status":"incorrect"},"variables":{"n":"6"},"description":"v2 : 6! = 720","variationIndex":2},{"answers":["63"],"expected":{"status":"correct"},"variables":{"n":"6"},"description":"v3 : n = 6 → 63","variationIndex":3},{"answers":["64"],"expected":{"status":"incorrect"},"variables":{"n":"6"},"description":"v3 : 64 (pizza nature comptée)","variationIndex":3},{"answers":["16"],"expected":{"status":"correct"},"variables":{"n":"4"},"description":"v4 : n = 4 → 16","variationIndex":4},{"answers":["8"],"expected":{"status":"incorrect"},"variables":{"n":"4"},"description":"v4 : 2 × 4 = 8","variationIndex":4}]}$plsc$::jsonb),
--   ('ef3c495c-632b-40ec-840d-fbbf7bfc879a'::uuid, $plsc${"title":"Coefficients binomiaux : chemins, symétrie, triangle de Pascal","description":"Sans formule factorielle : nombre de chemins à k succès, C(n, 0), C(n, 1), C(n, n), symétrie C(n, n − k) = C(n, k), relation et triangle de Pascal","variations":[{"blanks":[{"expectedAnswer":"{{c}}","acceptCombinatorialNotation":true}],"statement":"On représente par un arbre un schéma de Bernoulli de ${{n}}$ épreuves (succès $S$, échec $\\overline{S}$).\n\nCombien de chemins de cet arbre comportent exactement ${{k}}$ succès ?\n\n$?$","variables":[{"name":"n","expression":"3..5"},{"name":"k","expression":"1..{{eval:n-1}}"},{"name":"c","expression":"{{eval:binom(n,k)}}"}],"correction":{"steps":["Le nombre de chemins à ${{k}}$ succès parmi ${{n}}$ épreuves est, par définition, le coefficient binomial $\\binom{ {{n}} }{ {{k}} }$.","On peut les lister (un chemin = une position des ${{k}}$ succès parmi les ${{n}}$ épreuves) : $\\binom{ {{n}} }{ {{k}} }=\\textcolor{{{color:primary.0}}}{{{c}}}$."]}},{"blanks":[{"expectedAnswer":"{{c}}"}],"statement":"On donne $\\binom{ {{n}} }{ {{k}} }={{c}}$.\n\nSans calcul, donne $\\binom{ {{n}} }{ {{eval:n-k}} }$.\n\n$\\binom{ {{n}} }{ {{eval:n-k}} }=?$","variables":[{"name":"n","expression":"8..20"},{"name":"k","expression":"2..4"},{"name":"c","expression":"{{eval:binom(n,k)}}"}],"correction":{"steps":["Symétrie : $\\binom{n}{n-k}=\\binom{n}{k}$ (choisir les ${{k}}$ succès revient à choisir les ${{eval:n-k}}$ échecs).","$\\binom{ {{n}} }{ {{eval:n-k}} }=\\binom{ {{n}} }{ {{k}} }=\\textcolor{{{color:primary.0}}}{{{c}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:A+B}}"}],"statement":"On donne $\\binom{ {{n}} }{ {{k}} }={{A}}$ et $\\binom{ {{n}} }{ {{eval:k+1}} }={{B}}$.\n\nSans autre calcul, donne $\\binom{ {{eval:n+1}} }{ {{eval:k+1}} }$.\n\n$\\binom{ {{eval:n+1}} }{ {{eval:k+1}} }=?$","variables":[{"name":"n","expression":"6..15"},{"name":"k","expression":"1..2"},{"name":"A","expression":"{{eval:binom(n,k)}}"},{"name":"B","expression":"{{eval:binom(n,k+1)}}"}],"correction":{"steps":["Relation de Pascal : $\\binom{n}{k}+\\binom{n}{k+1}=\\binom{n+1}{k+1}$.","$\\binom{ {{eval:n+1}} }{ {{eval:k+1}} }={{A}}+{{B}}=\\textcolor{{{color:primary.0}}}{{{eval:A+B}}}$."]}},{"blanks":[{"expectedAnswer":"1"},{"expectedAnswer":"{{n}}"},{"expectedAnswer":"1"}],"statement":"Donne les coefficients binomiaux suivants.\n\n$\\binom{ {{n}} }{0}=?$ ; $\\binom{ {{n}} }{1}=?$ ; $\\binom{ {{n}} }{ {{n}} }=?$","variables":[{"name":"n","expression":"5..40"}],"correction":{"steps":["$\\binom{ {{n}} }{0}=\\textcolor{{{color:primary.0}}}{1}$ : un seul chemin sans succès (que des échecs).","$\\binom{ {{n}} }{1}=\\textcolor{{{color:primary.0}}}{{{n}}}$ : le succès unique peut être à l'une des ${{n}}$ épreuves.","$\\binom{ {{n}} }{ {{n}} }=\\textcolor{{{color:primary.0}}}{1}$ : un seul chemin où tout est succès."]}},{"blanks":[{"expectedAnswer":"{{if:k==2|{{eval:(n+1)*n/2}}|{{eval:(n+1)*n*(n-1)/6}}}}"}],"statement":"La ligne $n={{n}}$ du triangle de Pascal donne, dans l'ordre, les coefficients $\\binom{ {{n}} }{0}$, $\\binom{ {{n}} }{1}$, …, $\\binom{ {{n}} }{ {{n}} }$ :\n\n$1$ ; ${{c1}}$ ; ${{c2}}$ ; ${{c3}}$ ; ${{c4}}$ ; ${{c5}}${{if:n>=6| ; ${{c6}}$|}}{{if:n>=7| ; ${{c7}}$|}}\n\nDéduis-en $\\binom{ {{eval:n+1}} }{ {{k}} }$.\n\n$\\binom{ {{eval:n+1}} }{ {{k}} }=?$","variables":[{"name":"n","expression":"5..7"},{"name":"c0","expression":"1"},{"name":"c1","expression":"{{n}}"},{"name":"c2","expression":"{{eval:n*(n-1)/2}}"},{"name":"c3","expression":"{{eval:n*(n-1)*(n-2)/6}}"},{"name":"m4","expression":"{{eval:n-4}}"},{"name":"c4","expression":"{{eval:binom(n,m4)}}"},{"name":"m5","expression":"{{eval:n-5}}"},{"name":"c5","expression":"{{eval:binom(n,m5)}}"},{"name":"m6","expression":"{{eval:n-6}}"},{"name":"c6","expression":"{{eval:binom(n,m6)}}"},{"name":"m7","expression":"{{eval:n-7}}"},{"name":"c7","expression":"{{eval:binom(n,m7)}}"},{"name":"k","expression":"2..3"}],"correction":{"steps":["Dans le triangle de Pascal, chaque coefficient est la somme des deux coefficients placés au-dessus : $\\binom{ {{eval:n+1}} }{ {{k}} }=\\binom{ {{n}} }{ {{eval:k-1}} }+\\binom{ {{n}} }{ {{k}} }$.","$\\binom{ {{eval:n+1}} }{ {{k}} }={{if:k==2|{{c1}}+{{c2}}|{{c2}}+{{c3}}}}=\\textcolor{{{color:primary.0}}}{{{if:k==2|{{eval:(n+1)*n/2}}|{{eval:(n+1)*n*(n-1)/6}}}}}$."]}}],"shared":null,"test_specs":[{"answers":["6"],"expected":{"status":"correct"},"variables":{"k":"2","n":"4"},"description":"v0 : n = 4, k = 2 → 6","variationIndex":0},{"answers":["8"],"expected":{"status":"incorrect"},"variables":{"k":"2","n":"4"},"description":"v0 : n × k = 8","variationIndex":0},{"answers":["16"],"expected":{"status":"incorrect"},"variables":{"k":"2","n":"4"},"description":"v0 : 2ⁿ = 16 (tous les chemins)","variationIndex":0},{"answers":["220"],"expected":{"status":"correct"},"variables":{"k":"3","n":"12"},"description":"v1 : C(12, 3) = 220 → C(12, 9)","variationIndex":1},{"answers":["9"],"expected":{"status":"incorrect"},"variables":{"k":"3","n":"12"},"description":"v1 : 9","variationIndex":1},{"answers":["165"],"expected":{"status":"correct"},"variables":{"k":"2","n":"10"},"description":"v2 : C(10,2) + C(10,3) = 45 + 120","variationIndex":2},{"answers":["5400"],"expected":{"status":"incorrect"},"variables":{"k":"2","n":"10"},"description":"v2 : produit","variationIndex":2},{"answers":["1","12","1"],"expected":{"status":"correct"},"variables":{"n":"12"},"description":"v3 : n = 12 → 1 ; 12 ; 1","variationIndex":3},{"answers":["0","12","1"],"expected":{"status":"incorrect"},"variables":{"n":"12"},"description":"v3 : C(n, 0) = 0","variationIndex":3},{"answers":["1","12","12"],"expected":{"status":"incorrect"},"variables":{"n":"12"},"description":"v3 : C(n, n) = n","variationIndex":3},{"answers":["15"],"expected":{"status":"correct"},"variables":{"k":"2","n":"5"},"description":"v4 : ligne 5, C(6, 2) = 15","variationIndex":4},{"answers":["35"],"expected":{"status":"correct"},"variables":{"k":"3","n":"6"},"description":"v4 : ligne 6, C(7, 3) = 35","variationIndex":4},{"answers":["20"],"expected":{"status":"incorrect"},"variables":{"k":"3","n":"6"},"description":"v4 : ligne 6, C(6, 3) lu au lieu de C(7, 3)","variationIndex":4},{"answers":["\\binom{4}{2}"],"expected":{"status":"correct"},"variables":{"k":"2","n":"4"},"description":"v0 : \\binom{4}{2} (notation acceptée)","variationIndex":0}]}$plsc$::jsonb),
--   ('f01270c2-3c63-45c5-bfbb-8233154fadc6'::uuid, $plsc${"title":"Coefficient d'une primitive de la forme u′eᵘ, 2uu′ ou u′/u","description":"Trouver k pour que k·eᵘ, k·u² ou k·ln(u) soit une primitive de f : diviser par le facteur manquant de u′ (piège : multiplier)","variations":[{"blanks":[{"expectedAnswer":"{{eval:1/a}}"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)=e^{{{if:a==1|x}}{{if:a==-1|-x}}{{if:a!=1 && a!=-1|{{eval:a}}x}}{{if:b>0|+{{eval:b}}}}{{if:b<0|{{eval:b}}}}}$.\n\nDétermine le réel $k$ tel que la fonction $F$ définie par $F(x)=k\\,e^{{{if:a==1|x}}{{if:a==-1|-x}}{{if:a!=1 && a!=-1|{{eval:a}}x}}{{if:b>0|+{{eval:b}}}}{{if:b<0|{{eval:b}}}}}$ soit une primitive de $f$ sur $\\mathbb{R}$.\n\n$k=?$","variables":[{"name":"a","expression":"2..6;±"},{"name":"b","expression":"-5..5"}],"correction":{"steps":["Avec $u(x)={{if:a==1|x}}{{if:a==-1|-x}}{{if:a!=1 && a!=-1|{{eval:a}}x}}{{if:b>0|+{{eval:b}}}}{{if:b<0|{{eval:b}}}}$, on a $u'(x)={{eval:a}}$ et $(e^{u})'=u'e^{u}$.","$F'(x)=k\\times{{eval:a;()}}e^{{{if:a==1|x}}{{if:a==-1|-x}}{{if:a!=1 && a!=-1|{{eval:a}}x}}{{if:b>0|+{{eval:b}}}}{{if:b<0|{{eval:b}}}}}$. Pour que $F'=f$, il faut ${{eval:a}}k=1$, soit $k=\\textcolor{{{color:primary.0}}}{{{eval:1/a}}}$.","On divise par $u'$ : on ne multiplie pas."]}},{"blanks":[{"expectedAnswer":"{{eval:c/2}}"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)={{if:c==1|x}}{{if:c==-1|-x}}{{if:c!=1 && c!=-1|{{eval:c}}x}}e^{x^2}$.\n\nDétermine le réel $k$ tel que la fonction $F$ définie par $F(x)=k\\,e^{x^2}$ soit une primitive de $f$ sur $\\mathbb{R}$.\n\n$k=?$","variables":[{"name":"c","expression":"1..6;±"}],"correction":{"steps":["Avec $u(x)=x^2$, $u'(x)=2x$ et $(e^{u})'=u'e^{u}$ : $F'(x)=k\\times 2x\\,e^{x^2}=2k\\,x\\,e^{x^2}$.","Il faut $2k={{eval:c}}$, soit $k=\\textcolor{{{color:primary.0}}}{{{eval:c/2}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:c/4}}"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)