insert into _plsc_modeles values ('13e2d419-770b-4e97-a2f8-972d467cf2fc', $plsc$Probabilités$plsc$, $plsc$Autres lois$plsc$, $plsc$loi géométrique$plsc$, array['T_SPE', 'T_COMP'],
  $plsc${"title":"Loi géométrique : P(X = k), P(X ⩽ k), espérance, absence de mémoire","description":"X ~ G(p) : P(X = k) = (1 − p)ᵏ⁻¹p, P(X > k) = (1 − p)ᵏ, P(X ⩽ k) = 1 − (1 − p)ᵏ, E(X) = 1/p, P(X > m + n | X > m) = P(X > n) (pièges : exposant k au lieu de k − 1, E = p, mémoire non utilisée)","variations":[{"blanks":[{"expectedAnswer":"{{eval:(1-1/q)^h/q}}"}],"statement":"La variable aléatoire $X$ suit la loi géométrique $\\mathcal{G}\\left(\\dfrac{1}{ {{q}} }\\right)$.\n\nCalcule $P(X={{k}})$.\n\n$P(X={{k}})=?$","variables":[{"name":"q","expression":"2..6"},{"name":"k","expression":"2..4"},{"name":"h","expression":"{{eval:k-1}}"}],"correction":{"steps":["$P(X=k)=(1-p)^{k-1}p$ : ${{eval:k-1}}$ échec{{if:k>2|s|}}, puis le premier succès.","$P(X={{k}})=\\left(\\dfrac{ {{eval:q-1}} }{ {{q}} }\\right)^{ {{eval:k-1}} }\\times\\dfrac{1}{ {{q}} }=\\textcolor{{{color:primary.0}}}{{{eval:(1-1/q)^h/q}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:1-(1-1/q)^k}}"}],"statement":"La variable aléatoire $X$ suit la loi géométrique $\\mathcal{G}\\left(\\dfrac{1}{ {{q}} }\\right)$.\n\nCalcule $P(X\\leqslant {{k}})$.\n\n$P(X\\leqslant {{k}})=?$","variables":[{"name":"q","expression":"2..6"},{"name":"k","expression":"2..4"}],"correction":{"steps":["$X>{{k}}$ signifie que les ${{k}}$ premières épreuves sont des échecs : $P(X>{{k}})=\\left(\\dfrac{ {{eval:q-1}} }{ {{q}} }\\right)^{ {{k}} }$.","$P(X\\leqslant {{k}})=1-P(X>{{k}})=1-{{eval:(1-1/q)^k}}=\\textcolor{{{color:primary.0}}}{{{eval:1-(1-1/q)^k}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:(1-t/10)^k;d}}"}],"statement":"La variable aléatoire $X$ suit la loi géométrique de paramètre $p={{eval:t/10;d}}$.\n\nCalcule $P(X>{{k}})$ (nombre décimal).\n\n$P(X>{{k}})=?$","variables":[{"name":"t","expression":"1..9"},{"name":"k","expression":"2..3"}],"correction":{"steps":["$X>{{k}}$ : les ${{k}}$ premières épreuves sont des échecs.","$P(X>{{k}})=(1-p)^{ {{k}} }={{eval:1-t/10;d}}^{ {{k}} }=\\textcolor{{{color:primary.0}}}{{{eval:(1-t/10)^k;d}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:100/t}}"}],"statement":"À chaque tentative, un joueur réussit un exercice d'adresse avec la probabilité ${{eval:t/100;d}}$, indépendamment des autres tentatives. Il recommence jusqu'à la première réussite.\n\nCombien de tentatives lui faut-il en moyenne ?\n\n$?$","variables":[{"name":"t","expression":"2|4|5|8|10|20|25|40|50"}],"correction":{"steps":["Le rang $X$ de la première réussite suit la loi géométrique de paramètre $p={{eval:t/100;d}}$, d'espérance $E(X)=\\dfrac{1}{p}$.","$E(X)=\\dfrac{1}{ {{eval:t/100;d}} }=\\textcolor{{{color:primary.0}}}{{{eval:100/t;d}}}$ tentatives en moyenne."]}},{"blanks":[{"expectedAnswer":"{{eval:(1-1/q)^j}}"}],"statement":"La durée de vie $X$, en jours entiers, d'un composant suit la loi géométrique $\\mathcal{G}\\left(\\dfrac{1}{ {{q}} }\\right)$. Le composant fonctionne encore après ${{m}}$ jours.\n\nQuelle est la probabilité qu'il fonctionne encore après ${{eval:m+j}}$ jours ?\n\n$P_{(X>{{m}})}(X>{{eval:m+j}})=?$","variables":[{"name":"q","expression":"2..6"},{"name":"m","expression":"3..9"},{"name":"j","expression":"1..3"}],"correction":{"steps":["La loi géométrique est **sans mémoire** : $P_{(X>m)}(X>m+n)=P(X>n)$.","$P_{(X>{{m}})}(X>{{eval:m+j}})=P(X>{{j}})=\\left(\\dfrac{ {{eval:q-1}} }{ {{q}} }\\right)^{ {{j}} }=\\textcolor{{{color:primary.0}}}{{{eval:(1-1/q)^j}}}$."]}}],"shared":{"blankDefaults":{"acceptDecimal":true}},"test_specs":[{"answers":["\\frac{9}{64}"],"expected":{"status":"correct"},"variables":{"k":"3","q":"4"},"description":"v0 : G(1/4), P(X = 3) = 9/64","variationIndex":0},{"answers":["\\frac{27}{256}"],"expected":{"status":"incorrect"},"variables":{"k":"3","q":"4"},"description":"v0 : exposant k : 27/256","variationIndex":0},{"answers":["\\frac{3}{64}"],"expected":{"status":"incorrect"},"variables":{"k":"3","q":"4"},"description":"v0 : p et 1 − p échangés : 3/64","variationIndex":0},{"answers":["\\frac{5}{9}"],"expected":{"status":"correct"},"variables":{"k":"2","q":"3"},"description":"v1 : G(1/3), P(X ⩽ 2) = 5/9","variationIndex":1},{"answers":["\\frac{4}{9}"],"expected":{"status":"incorrect"},"variables":{"k":"2","q":"3"},"description":"v1 : P(X > 2) = 4/9","variationIndex":1},{"answers":["\\frac{2}{9}"],"expected":{"status":"incorrect"},"variables":{"k":"2","q":"3"},"description":"v1 : P(X = 2) = 2/9","variationIndex":1},{"answers":["0,512"],"expected":{"status":"correct"},"variables":{"k":"3","t":"2"},"description":"v2 : p = 0,2, P(X > 3) = 0,512","variationIndex":2},{"answers":["0,488"],"expected":{"status":"incorrect"},"variables":{"k":"3","t":"2"},"description":"v2 : 1 − 0,512","variationIndex":2},{"answers":["0,64"],"expected":{"status":"incorrect"},"variables":{"k":"3","t":"2"},"description":"v2 : P(X ⩾ 3) = 0,64","variationIndex":2},{"answers":["20"],"expected":{"status":"correct"},"variables":{"t":"5"},"description":"v3 : p = 0,05 → 20","variationIndex":3},{"answers":["0,05"],"expected":{"status":"incorrect"},"variables":{"t":"5"},"description":"v3 : E = p","variationIndex":3},{"answers":["12,5"],"expected":{"status":"correct"},"variables":{"t":"8"},"description":"v3 : p = 0,08 → 12,5","variationIndex":3},{"answers":["\\frac{9}{16}"],"expected":{"status":"correct"},"variables":{"j":"2","m":"5","q":"4"},"description":"v4 : G(1/4), m = 5, j = 2 → 9/16","variationIndex":4},{"answers":["\\frac{2187}{16384}"],"expected":{"status":"incorrect"},"variables":{"j":"2","m":"5","q":"4"},"description":"v4 : sans mémoire oubliée (3/4)⁷","variationIndex":4},{"answers":["\\frac{7}{16}"],"expected":{"status":"incorrect"},"variables":{"j":"2","m":"5","q":"4"},"description":"v4 : 1 − (3/4)²","variationIndex":4}]}$plsc$::jsonb,
