insert into _plsc_modeles values ('2b240d8c-bdc2-4a55-a8db-a028f02ec889', $plsc$Géométrie$plsc$, $plsc$Orthogonalité et distances dans l'espace$plsc$, $plsc$vecteur normal et équation cartésienne$plsc$, array['T_SPE'],
  $plsc${"title":"Espace : trouver un vecteur directeur ou un vecteur normal","description":"Vecteur directeur de (AB), d'une droite orthogonale à un plan, de l'intersection de deux plans ; vecteur normal au plan (ABC) — tout vecteur colinéaire non nul est juste (pièges : point pris pour vecteur, vecteur directeur pris pour normal)","variations":[{"blanks":[{"expectedAnswer":"({{eval:bx-ax}};{{eval:by-ay}};{{eval:bz-az}})"}],"statement":"Dans l'espace muni d'un repère orthonormé, on considère les points $A({{ax}}\\,;\\,{{ay}}\\,;\\,{{az}})$ et $B({{bx}}\\,;\\,{{by}}\\,;\\,{{bz}})$.\n\nUne représentation paramétrique de la droite $(AB)$ est $x=x_A+at$, $y=y_A+bt$, $z=z_A+ct$ ($t\\in\\mathbb{R}$), où $\\vec{u}\\begin{pmatrix}a\\\\b\\\\c\\end{pmatrix}$ est un vecteur directeur de $(AB)$. Donne un tel vecteur $\\vec{u}$ : $?$","variables":[{"name":"ax","expression":"-5..5"},{"name":"ay","expression":"-5..5"},{"name":"az","expression":"-5..5"},{"name":"bx","expression":"-5..5"},{"name":"by","expression":"-5..5"},{"name":"bz","expression":"-5..5"},{"name":"w1","expression":"{{eval:bx-ax}}"},{"name":"w2","expression":"{{eval:by-ay}}"},{"name":"w3","expression":"{{eval:bz-az}}"}],"conditions":["bx != ax","abs(by-ay)+abs(bz-az) > 0"],"correction":{"steps":["$\\overrightarrow{AB}$ dirige la droite $(AB)$ : $\\textcolor{{{color:primary.0}}}{ \\overrightarrow{AB}\\begin{pmatrix}{{eval:bx-ax}}\\\\{{eval:by-ay}}\\\\{{eval:bz-az}}\\end{pmatrix} }$.","D'où la représentation $x={{if:ax!=0|{{ax}}}}{{if:w1==1|{{if:ax!=0|+}}t}}{{if:w1==-1|-t}}{{if:w1>1|{{if:ax!=0|+}}{{w1}}t}}{{if:w1< -1|{{w1}}t}}{{if:w1==0|{{if:ax==0|0}}}}$, $y={{if:ay!=0|{{ay}}}}{{if:w2==1|{{if:ay!=0|+}}t}}{{if:w2==-1|-t}}{{if:w2>1|{{if:ay!=0|+}}{{w2}}t}}{{if:w2< -1|{{w2}}t}}{{if:w2==0|{{if:ay==0|0}}}}$, $z={{if:az!=0|{{az}}}}{{if:w3==1|{{if:az!=0|+}}t}}{{if:w3==-1|-t}}{{if:w3>1|{{if:az!=0|+}}{{w3}}t}}{{if:w3< -1|{{w3}}t}}{{if:w3==0|{{if:az==0|0}}}}$ ($t\\in\\mathbb{R}$) ; tout vecteur colinéaire non nul convient."]}},{"blanks":[{"expectedAnswer":"({{a}};{{b}};{{c}})"}],"statement":"Dans l'espace muni d'un repère orthonormé, on considère le point $A({{ax}}\\,;\\,{{ay}}\\,;\\,{{az}})$ et le plan $\\mathcal{P}$ d'équation ${{a}}x+({{b}})y+({{c}})z+({{d}})=0$.\n\nDonne un vecteur directeur de la droite $\\Delta$ passant par $A$ et orthogonale à $\\mathcal{P}$ : $?$","variables":[{"name":"ax","expression":"-5..5"},{"name":"ay","expression":"-5..5"},{"name":"az","expression":"-5..5"},{"name":"a","expression":"1..5;±"},{"name":"b","expression":"-5..5"},{"name":"c","expression":"1..5;±"},{"name":"d","expression":"1..9;±"}],"correction":{"steps":["Une droite orthogonale à $\\mathcal{P}$ est dirigée par un vecteur normal à $\\mathcal{P}$, lu sur l'équation.","$\\textcolor{{{color:primary.0}}}{ \\vec{n}\\begin{pmatrix}{{a}}\\\\{{b}}\\\\{{c}}\\end{pmatrix} }$ est un vecteur directeur de $\\Delta$ (le point $A$ ne sert qu'à placer la droite)."]}},{"blanks":[{"expectedAnswer":"({{n1}};{{n2}};{{n3}})"}],"statement":"Dans l'espace muni d'un repère orthonormé, on considère les points $A({{ax}}\\,;\\,{{ay}}\\,;\\,{{az}})$, $B({{bx}}\\,;\\,{{by}}\\,;\\,{{bz}})$ et $C({{cx}}\\,;\\,{{cy}}\\,;\\,{{cz}})$, non alignés.\n\nDonne un vecteur normal au plan $(ABC)$ : $?$","variables":[{"name":"ax","expression":"-3..3"},{"name":"ay","expression":"-3..3"},{"name":"az","expression":"-3..3"},{"name":"p1","expression":"-3..3"},{"name":"p2","expression":"-3..3"},{"name":"p3","expression":"-3..3"},{"name":"q1","expression":"-3..3"},{"name":"q2","expression":"-3..3"},{"name":"q3","expression":"-3..3"},{"name":"bx","expression":"{{eval:ax+p1}}"},{"name":"by","expression":"{{eval:ay+p2}}"},{"name":"bz","expression":"{{eval:az+p3}}"},{"name":"cx","expression":"{{eval:ax+q1}}"},{"name":"cy","expression":"{{eval:ay+q2}}"},{"name":"cz","expression":"{{eval:az+q3}}"},{"name":"c1","expression":"{{eval:p2*q3-p3*q2}}"},{"name":"c2","expression":"{{eval:p3*q1-p1*q3}}"},{"name":"c3","expression":"{{eval:p1*q2-p2*q1}}"},{"name":"g","expression":"{{eval:gcd(gcd(abs(c1),abs(c2)),abs(c3))}}"},{"name":"n1","expression":"{{eval:c1/g}}"},{"name":"n2","expression":"{{eval:c2/g}}"},{"name":"n3","expression":"{{eval:c3/g}}"}],"conditions":["abs(p2*q3-p3*q2)+abs(p3*q1-p1*q3)+abs(p1*q2-p2*q1) > 0"],"correction":{"steps":["$\\vec{n}$ est normal à $(ABC)$ si et seulement si $\\vec{n}\\cdot\\overrightarrow{AB}=0$ et $\\vec{n}\\cdot\\overrightarrow{AC}=0$, avec $\\overrightarrow{AB}\\begin{pmatrix}{{p1}}\\\\{{p2}}\\\\{{p3}}\\end{pmatrix}$ et $\\overrightarrow{AC}\\begin{pmatrix}{{q1}}\\\\{{q2}}\\\\{{q3}}\\end{pmatrix}$.","En résolvant ce système (on fixe une coordonnée), on trouve par exemple $\\textcolor{{{color:primary.0}}}{ \\vec{n}\\begin{pmatrix}{{n1}}\\\\{{n2}}\\\\{{n3}}\\end{pmatrix} }$. Vérification : $\\vec{n}\\cdot\\overrightarrow{AB}={{n1}}\\times{{p1;()}}+{{n2;()}}\\times{{p2;()}}+{{n3;()}}\\times{{p3;()}}=0$, de même $\\vec{n}\\cdot\\overrightarrow{AC}=0$."]}},{"blanks":[{"expectedAnswer":"({{n1}};{{n2}};{{n3}})"}],"statement":"Dans l'espace muni d'un repère orthonormé, on considère les plans sécants $\\mathcal{P}$ et $\\mathcal{Q}$ d'équations respectives ${{a1}}x+({{a2}})y+({{a3}})z+({{d}})=0$ et ${{b1}}x+({{b2}})y+({{b3}})z+({{q}})=0$.\n\nDonne un vecteur directeur de leur droite d'intersection : $?$","variables":[{"name":"a1","expression":"-3..3"},{"name":"a2","expression":"-3..3"},{"name":"a3","expression":"-3..3"},{"name":"b1","expression":"-3..3"},{"name":"b2","expression":"-3..3"},{"name":"b3","expression":"-3..3"},{"name":"d","expression":"-6..6"},{"name":"q","expression":"-6..6"},{"name":"c1","expression":"{{eval:a2*b3-a3*b2}}"},{"name":"c2","expression":"{{eval:a3*b1-a1*b3}}"},{"name":"c3","expression":"{{eval:a1*b2-a2*b1}}"},{"name":"g","expression":"{{eval:gcd(gcd(abs(c1),abs(c2)),abs(c3))}}"},{"name":"n1","expression":"{{eval:c1/g}}"},{"name":"n2","expression":"{{eval:c2/g}}"},{"name":"n3","expression":"{{eval:c3/g}}"}],"conditions":["abs(a2*b3-a3*b2)+abs(a3*b1-a1*b3)+abs(a1*b2-a2*b1) > 0","abs(a1)+abs(a2)+abs(a3) > 1","abs(b1)+abs(b2)+abs(b3) > 1"],"correction":{"steps":["La droite d'intersection est contenue dans les deux plans : son vecteur directeur $\\vec{u}$ est orthogonal aux deux vecteurs normaux $\\vec{n}_1\\begin{pmatrix}{{a1}}\\\\{{a2}}\\\\{{a3}}\\end{pmatrix}$ et $\\vec{n}_2\\begin{pmatrix}{{b1}}\\\\{{b2}}\\\\{{b3}}\\end{pmatrix}$.","En résolvant $\\vec{u}\\cdot\\vec{n}_1=0$, $\\vec{u}\\cdot\\vec{n}_2=0$, on trouve par exemple $\\textcolor{{{color:primary.0}}}{ \\vec{u}\\begin{pmatrix}{{n1}}\\\\{{n2}}\\\\{{n3}}\\end{pmatrix} }$ (vérification : ${{a1}}\\times{{n1;()}}+{{a2;()}}\\times{{n2;()}}+{{a3;()}}\\times{{n3;()}}=0$, de même avec $\\vec{n}_2$)."]}}],"shared":{"blankDefaults":{"answerKind":"vecteur","vectorMode":"colineaire"},"cleanCoefficients":true},"test_specs":[{"answers":["(2;-3;1)"],"expected":{"status":"correct"},"variables":{"ax":"1","ay":"2","az":"-1","bx":"3","by":"-1","bz":"0"},"description":"v0 : AB(2 ; -3 ; 1)","variationIndex":0},{"answers":["(-2;3;-1)"],"expected":{"status":"correct"},"variables":{"ax":"1","ay":"2","az":"-1","bx":"3","by":"-1","bz":"0"},"description":"v0 : BA","variationIndex":0},{"answers":["(1;2;-1)"],"expected":{"status":"incorrect"},"variables":{"ax":"1","ay":"2","az":"-1","bx":"3","by":"-1","bz":"0"},"description":"v0 : point A donné","variationIndex":0},{"answers":["(4;1;-1)"],"expected":{"status":"incorrect"},"variables":{"ax":"1","ay":"2","az":"-1","bx":"3","by":"-1","bz":"0"},"description":"v0 : A + B","variationIndex":0},{"answers":["(1;-3;2)"],"expected":{"status":"correct"},"variables":{"a":"1","b":"-3","c":"2","d":"4","ax":"2","ay":"-1","az":"0"},"description":"v1 : (1 ; -3 ; 2)","variationIndex":1},{"answers":["(-2;6;-4)"],"expected":{"status":"correct"},"variables":{"a":"1","b":"-3","c":"2","d":"4","ax":"2","ay":"-1","az":"0"},"description":"v1 : multiple","variationIndex":1},{"answers":["(2;-1;0)"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"-3","c":"2","d