insert into _plsc_modeles values ('34b03dee-865d-405c-a284-abfac4248997', $plsc$Géométrie$plsc$, $plsc$Orthogonalité et distances dans l'espace$plsc$, $plsc$sphère$plsc$, array['T_SPE'],
  $plsc${"title":"Espace : point d'une sphère, intersection d'une sphère et d'un plan","description":"Sphère donnée par une équation centre-rayon : coordonnée manquante d'un point de la sphère ; cercle d'intersection avec un plan (centre et rayon, Pythagore avec la distance du centre au plan) — pièges : solution négative, ρ² au lieu de ρ, centre Ω au lieu de H","variations":[{"blanks":[{"expectedAnswer":"{{t}}"}],"statement":"Dans l'espace muni d'un repère orthonormé, on considère la sphère $\\mathcal{S}$ d'équation $(x-({{a}}))^2+(y-({{b}}))^2+(z-({{c}}))^2={{R2}}$.\n\nLe point $M({{xm}}\\,;\\,{{ym}}\\,;\\,t)$ appartient à $\\mathcal{S}$, avec $t>{{c}}$. Détermine $t$.\n\n$t=?$","variables":[{"name":"a","expression":"-4..4"},{"name":"b","expression":"-4..4"},{"name":"c","expression":"-4..4"},{"name":"p","expression":"1..3;±"},{"name":"q","expression":"1..3;±"},{"name":"k","expression":"1..5"},{"name":"R2","expression":"{{eval:p^2+q^2+k^2}}"},{"name":"xm","expression":"{{eval:a+p}}"},{"name":"ym","expression":"{{eval:b+q}}"},{"name":"t","expression":"{{eval:c+k}}"}],"correction":{"steps":["$M\\in\\mathcal{S}$ : $({{xm}}-{{a;()}})^2+({{ym}}-{{b;()}})^2+(t-{{c;()}})^2={{R2}}$, soit ${{eval:p^2+q^2}}+(t-{{c;()}})^2={{R2}}$.","Donc $(t-{{c;()}})^2={{eval:k^2}}$ : $t-{{c;()}}={{k}}$ ou $t-{{c;()}}=-{{k}}$.","Comme $t>{{c}}$ : $\\textcolor{{{color:primary.0}}}{ t={{t}} }$."]}},{"blanks":[{"expectedAnswer":"{{a}}"},{"expectedAnswer":"{{b}}"},{"expectedAnswer":"{{h}}"},{"expectedAnswer":"{{rho}}"}],"statement":"Dans l'espace muni d'un repère orthonormé, on considère la sphère $\\mathcal{S}$ d'équation $(x-({{a}}))^2+(y-({{b}}))^2+(z-({{c}}))^2={{R2}}$ et le plan $\\mathcal{P}$ d'équation $z={{h}}$.\n\nL'intersection de $\\mathcal{S}$ et de $\\mathcal{P}$ est un cercle. Détermine son centre $H$ et son rayon $\\rho$.\n\n$H(?\\,;\\,?\\,;\\,?)$ et $\\rho=?$","variables":[{"name":"a","expression":"-4..4"},{"name":"b","expression":"-4..4"},{"name":"c","expression":"-4..4"},{"name":"s","expression":"1..4;±"},{"name":"rho","expression":"1..6"},{"name":"h","expression":"{{eval:c+s}}"},{"name":"R2","expression":"{{eval:s^2+rho^2}}"}],"correction":{"steps":["Le centre du cercle est le projeté orthogonal $H$ de $\\Omega({{a}}\\,;\\,{{b}}\\,;\\,{{c}})$ sur $\\mathcal{P}$ : $H({{a}}\\,;\\,{{b}}\\,;\\,{{h}})$.","Les points de l'intersection vérifient $z={{h}}$ et ${{R2}}-({{h}}-{{c;()}})^2={{eval:rho^2}}$, donc $(x-({{a}}))^2+(y-({{b}}))^2={{eval:rho^2}}$.","C'est le cercle de centre $H$ et de rayon $\\textcolor{{{color:primary.0}}}{ \\rho=\\sqrt{ {{eval:rho^2}} }={{rho}} }$."]}},{"blanks":[{"expectedAnswer":"{{delta}}"},{"expectedAnswer":"{{rho}}"}],"statement":"Dans l'espace muni d'un repère orthonormé, on considère la sphère $\\mathcal{S}$ d'équation $(x-({{a}}))^2+(y-({{b}}))^2+(z-({{c}}))^2={{R2}}$ et le plan $\\mathcal{P}$ d'équation $x+({{n2}})y+({{n3}})z+({{d}})=0$.\n\nCalcule la distance $\\delta$ du centre $\\Omega$ de $\\mathcal{S}$ au plan $\\mathcal{P}$, puis le rayon $\\rho$ du cercle d'intersection de $\\mathcal{S}$ et de $\\mathcal{P}$.\n\n$\\delta=?$ et $\\rho=?$","variables":[{"name":"a","expression":"-4..4"},{"name":"b","expression":"-4..4"},{"name":"c","expression":"-4..4"},{"name":"s2","expression":"1..1;±"},{"name":"s3","expression":"1..1;±"},{"name":"n2","expression":"{{eval:2*s2}}"},{"name":"n3","expression":"{{eval:2*s3}}"},{"name":"delta","expression":"1..2"},{"name":"rho","expression":"1..5"},{"name":"R2","expression":"{{eval:delta^2+rho^2}}"},{"name":"d","expression":"{{eval:3*delta-(a+n2*b+n3*c)}}"}],"correction":{"steps":["$\\Omega({{a}}\\,;\\,{{b}}\\,;\\,{{c}})$ et $\\vec{n}\\begin{pmatrix}1\\\\{{n2}}\\\\{{n3}}\\end{pmatrix}$ normal à $\\mathcal{P}$, avec $\\|\\vec{n}\\|=\\sqrt{1+4+4}=3$.","$\\delta=\\dfrac{|{{a}}+{{n2;()}}\\times{{b;()}}+{{n3;()}}\\times{{c;()}}+{{d;()}}|}{3}=\\dfrac{ {{eval:3*delta}} }{3}=\\textcolor{{{color:primary.0}}}{ {{delta}} }$.","Le rayon de la sphère vérifie $R^2={{R2}}$ ; par Pythagore dans le triangle $\\Omega HM$ : $\\rho^2=R^2-\\delta^2={{R2}}-{{eval:delta^2}}={{eval:rho^2}}$, donc $\\textcolor{{{color:primary.0}}}{ \\rho={{rho}} }$."]}}],"shared":{"cleanCoefficients":true},"test_specs":[{"answers":["2"],"expected":{"status":"correct"},"variables":{"a":"1","b":"-2","c":"0","k":"2","p":"2","q":"-1"},"description":"v0 : t = 2","variationIndex":0},{"answers":["-2"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"-2","c":"0","k":"2","p":"2","q":"-1"},"description":"v0 : solution t < c (−2)","variationIndex":0},{"answers":["4"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"-2","c":"0","k":"2","p":"2","q":"-1"},"description":"v0 : (t−c)² donné (4)","variationIndex":0},{"answers":["1","-2","0","4"],"expected":{"status":"correct"},"variables":{"a":"1","b":"-2","c":"3","s":"-3","rho":"4"},"description":"v1 : centre et rayon","variationIndex":1},{"answers":["1","-2","3","4"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"-2","c":"3","s":"-3","rho":"4"},"description":"v1 : centre Ω au lieu de H","variationIndex":1},{"answers":["1","-2","0","16"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"-2","c":"3","s":"-3","rho":"4"},"description":"v1 : ρ² au lieu de ρ","variationIndex":1},{"answers":["1","-2","0","\\sqrt{16}"],"expected":{"status":"unoptimal_form","constraintViolations":["reducedRadicals"]},"variables":{"a":"1","b":"-2","c":"3","s":"-3","rho":"4"},"description":"v1 : ρ = √16 non calculé","variationIndex":1},{"answers":["1","-2","0","5"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"-2","c":"3","s":"-3","rho":"4"},"description":"v1 : R au lieu de ρ","variationIndex":1},{"answers":["2","4"],"expected":{"status":"correct"},"variables":{"a":"1","b":"0","c":"-1","s2":"1","s3":"-1","rho":"4","delta":"2"},"description":"v2 : δ = 2, ρ = 4","variationIndex":2},{"answers":["6","4"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"0","c":"-1","s2":"1","s3":"-1","rho":"4","delta":"2"},"description":"v2 : division par ‖n‖ oubliée","variationIndex":2},{"answers":["2","16"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"0","c":"-1","s2":"1","s3":"-1","rho":"4","delta":"2"},"description":"v2 : ρ² au lieu de ρ","variationIndex":2},{"answers":["2","\\sqrt{24}"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"0","c":"-1","s2":"1","s3":"-1","rho":"4","delta":"2"},"description":"v2 : R² + δ² au lieu de R² − δ²","variationIndex":2}]}$plsc$::jsonb,
