insert into _plsc_modeles values ('37ce7759-c2fa-4353-a726-f0c942284053', $plsc$Fonctions$plsc$, $plsc$Convexité$plsc$, null, array['T_SPE', 'T_COMP'],
  $plsc${"title":"Convexité et inflexion : lecture graphique sur f, f′ ou f″","description":"Lire l'intervalle de convexité sur la courbe de f (courbure), de f′ (f′ croissante) ou de f″ (f″ ≥ 0), et l'abscisse d'un point d'inflexion","variations":[{"choices":[{"content":"{{if:s>0|$\\left[{{h}}\\,;+\\infty\\right[$|$\\left]-\\infty\\,;{{h}}\\right]$}}"},{"content":"{{if:s>0|$\\left]-\\infty\\,;{{h}}\\right]$|$\\left[{{h}}\\,;+\\infty\\right[$}}"},{"content":"$\\left[{{eval:h-1}}\\,;{{eval:h+1}}\\right]$"},{"content":"$\\mathbb{R}$"}],"statement":"On a représenté ci-dessous la courbe $\\mathcal{C}_f$ d'une fonction $f$ deux fois dérivable sur $\\mathbb{R}$.\n\n```courbe\nx: {{eval:h-3.5}} ; {{eval:h+3.5}}\ny: {{eval:k-4}} ; {{eval:k+4}}\ngrille: 1 ; 1\nf(x) = {{s}}*0.5*((x-{{h}})^3-3*(x-{{h}}))+{{k}}   bleu   nom=C_f\ntaille: moyenne\ndescription: Courbe d'une fonction polynôme de degré 3 avec un maximum et un minimum locaux.\n```\n\nSur quel intervalle la fonction $f$ est-elle **convexe** ?","variables":[{"name":"s","expression":"-1|1"},{"name":"h","expression":"-2..2"},{"name":"k","expression":"-1..1"}],"correction":{"steps":["$f$ est convexe là où sa courbe est « tournée vers le haut » (au-dessus de ses tangentes), concave là où elle est « tournée vers le bas ».","La courbure change au point d'abscisse ${{h}}$ (point d'inflexion) : $f$ est convexe sur $\\textcolor{{{color:primary.0}}}{{{if:s>0|\\left[{{h}}\\,;+\\infty\\right[|\\left]-\\infty\\,;{{h}}\\right]}}}$.","Attention : l'intervalle $\\left[{{eval:h-1}}\\,;{{eval:h+1}}\\right]$ est celui où $f$ est {{if:s>0|décroissante|croissante}}, ce n'est pas une question de convexité."]},"correctChoiceIndex":["0"]},{"choices":[{"content":"{{if:s>0|$\\left[{{h}}\\,;+\\infty\\right[$|$\\left]-\\infty\\,;{{h}}\\right]$}}"},{"content":"{{if:s>0|$\\left]-\\infty\\,;{{h}}\\right]$|$\\left[{{h}}\\,;+\\infty\\right[$}}"},{"content":"$\\left[{{eval:h-2}}\\,;{{eval:h+2}}\\right]$"},{"content":"$\\mathbb{R}$"}],"statement":"On a représenté ci-dessous la courbe de la fonction **dérivée** $f'$ d'une fonction $f$ deux fois dérivable sur $\\mathbb{R}$.\n\n```courbe\nx: {{eval:h-4}} ; {{eval:h+4}}\ny: -5 ; 5\ngrille: 1 ; 1\ng(x) = {{s}}*(0.5*(x-{{h}})^2-2)   rouge\ntaille: moyenne\ndescription: Courbe de la dérivée f′ : une parabole qui coupe l'axe des abscisses en deux points.\n```\n\nSur quel intervalle la fonction $f$ est-elle **convexe** ?","variables":[{"name":"s","expression":"-1|1"},{"name":"h","expression":"-2..2"}],"correction":{"steps":["$f$ est convexe là où $f'$ est **croissante** (on ne regarde pas le signe de $f'$, qui donne les variations de $f$).","Sur le graphique, $f'$ est {{if:s>0|décroissante puis croissante|croissante puis décroissante}}, avec un changement en $x={{h}}$.","$f$ est convexe sur $\\textcolor{{{color:primary.0}}}{{{if:s>0|\\left[{{h}}\\,;+\\infty\\right[|\\left]-\\infty\\,;{{h}}\\right]}}}$."]},"correctChoiceIndex":["0"]},{"choices":[{"content":"{{if:s>0|$\\left[{{h}}\\,;+\\infty\\right[$|$\\left]-\\infty\\,;{{h}}\\right]$}}"},{"content":"{{if:s>0|$\\left]-\\infty\\,;{{h}}\\right]$|$\\left[{{h}}\\,;+\\infty\\right[$}}"},{"content":"$\\mathbb{R}$"},{"content":"$\\left[0\\,;+\\infty\\right[$"}],"statement":"On a représenté ci-dessous la courbe de la fonction **dérivée seconde** $f''$ d'une fonction $f$ deux fois dérivable sur $\\mathbb{R}$.\n\n```courbe\nx: -5 ; 5\ny: -5 ; 5\ngrille: 1 ; 1\ng(x) = {{s}}*(x-{{h}})   violet\ntaille: moyenne\ndescription: Courbe de la dérivée seconde f″ : une droite qui coupe l'axe des abscisses.\n```\n\nSur quel intervalle la fonction $f$ est-elle **convexe** ?","variables":[{"name":"s","expression":"-1|1"},{"name":"h","expression":"-3..3"}],"conditions":["h != 0"],"correction":{"steps":["$f$ est convexe là où $f''(x)\\geqslant 0$, c'est-à-dire là où la courbe de $f''$ est **au-dessus** de l'axe des abscisses.","$f''$ s'annule en ${{h}}$ et est positive {{if:s>0|à droite|à gauche}} : $f$ est convexe sur $\\textcolor{{{color:primary.0}}}{{{if:s>0|\\left[{{h}}\\,;+\\infty\\right[|\\left]-\\infty\\,;{{h}}\\right]}}}$. (Que $f''$ soit {{if:s>0|croissante|décroissante}} ne dit rien de la convexité de $f$.)"]},"correctChoiceIndex":["0"]},{"choices":[{"content":"${{h}}$"},{"content":"${{eval:h+1}}$"},{"content":"${{eval:h-1}}$"},{"content":"${{k}}$"}],"statement":"On a représenté ci-dessous la courbe $\\mathcal{C}_f$ d'une fonction $f$ deux fois dérivable sur $\\mathbb{R}$.\n\n```courbe\nx: {{eval:h-3.5}} ; {{eval:h+3.5}}\ny: {{eval:k-4}} ; {{eval:k+4}}\ngrille: 1 ; 1\nf(x) = {{s}}*0.5*((x-{{h}})^3-3*(x-{{h}}))+{{k}}   bleu   nom=C_f\ntaille: moyenne\ndescription: Courbe d'une fonction polynôme de degré 3 avec un maximum et un minimum locaux.\n```\n\nQuelle est l'abscisse du point d'inflexion de $\\mathcal{C}_f$ ?","variables":[{"name":"s","expression":"-1|1"},{"name":"h","expression":"-2..2"},{"name":"k","expression":"-2..2"}],"conditions":["k != h","k != h+1","k != h-1"],"correction":{"steps":["Au point d'inflexion, la courbe **traverse sa tangente** : elle passe de « tournée vers le {{if:s>0|bas|haut}} » à « tournée vers le {{if:s>0|haut|bas}} ».","C'est le point de coordonnées $({{h}}\\,;{{k}})$ : son abscisse est $\\textcolor{{{color:primary.0}}}{{{h}}}$. Les abscisses ${{eval:h-1}}$ et ${{eval:h+1}}$ sont celles des extremums locaux, pas de l'inflexion."]},"correctChoiceIndex":["0"]}],"shared":{"cleanCoefficients":true},"test_specs":[{"expected":{"status":"correct"},"variables":{"h":"1","k":"0","s":"1"},"description":"v0 : s=1, bonne réponse","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"h":"1","k":"0","s":"1"},"description":"v0 : intervalle de concavité","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"h":"1","k":"0","s":"1"},"description":"v0 : intervalle de décroissance","variationIndex":0,"selectedChoices":[2]},{"expected":{"status":"correct"},"variables":{"h":"-1","k":"1","s":"-1"},"description":"v0 : s=−1","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"h":"0","s":"1"},"description":"v1 : f′ décroissante puis croissante","variationIndex":1,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"h":"0","s":"1"},"description":"v1 : là où f′ ≤ 0 (variations de f)","variationIndex":1,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{"h":"1","s":"-1"},"description":"v1 : s=−1, opposé","variationIndex":1,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"h":"2","s":"1"},"description":"v2 : f″ ≥ 0 à droite","variationIndex":2,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"h":"2","s":"1"},"description":"v2 : f″ croissante ≠ f convexe","variationIndex":2,"selectedChoices":[2]},{"expected":{"status":"correct"},"variables":{"h":"-2","s":"-1"},"description":"v2 : s=−1","variationIndex":2,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"h":"0","k":"2","s":"1"},"description":"v3 : inflexion","variationIndex":3,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"h":"0","k":"2","s":"1"},"description":"v3 : extremum","variationIndex":3,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"h":"0","k":"2","s":"1"},"description":"v3 : ordonnée","variationIndex":3,"selectedChoices":[3]}]}$plsc$::jsonb,
  $plsc${"title":"Convexité : lecture sur la courbe de f","description":"Lire l'intervalle où f est convexe sur sa courbe (courbe au-dessus de ses tangentes)","variations":[{"choices":[{"content":"{{if:s>0|$\\left[{{h}}\\,;+\\infty\\right[$|$\\left]-\\infty\\,;{{h}}\\right]$}}"},{"content":"{{if:s>0|$\\left]-\\infty\\,;{{h}}\\right]$|$\\left[{{h}}\\,;+\\infty\\right[$}}"},{"content":"$\\left[{{eval:h-1}}\\,;{{eval:h+1}}\\right]$"},{"content":"$\\mathbb{R}$"}],"statement":"On a représenté ci-dessous la courbe $\\mathcal{C}_f$ d'une fonction $f$ deux fois dérivable sur $\\mathbb{R}$.\n\n```courbe\nx: {{eval:h-3.5}} ; {{eval:h+3.5}}\ny: {{eval:k-4}} ; {{eval:k+4}}\ngrille: 1 ; 1\nf(x) = {{s}}*0.5*((x-{{h}})^3-3*(x-{{h}}))+{{k}}   bleu   nom=C_f\ntaille: moyenne\ndescription: Courbe d'une fonction polynôme de degré 3 avec un maximum et un minimum locaux.\n```\n\nSur quel intervalle la fonction $f$ est-elle **convexe** ?","variables":[{"name":"s","expression":"-1|1"},{"name":"h","expression":"-2..2"},{"name":"k","expression":"-1..1"}],"correction":{"steps":["$f$ est convexe là où sa courbe est « tournée vers le haut » (au-dessus de ses tangentes), concave là où elle est « tournée vers le bas ».","La courbure change au point d'abscisse ${{h}}$ (point d'inflexion) : $f$ est convexe sur $\\textcolor{{{color:primary.0}}}{{{if:s>0|\\left[{{h}}\\,;+\\infty\\right[|\\left]-\\infty\\,;{{h}}\\right]}}}$.","Attention : l'intervalle $\\left[{{eval:h-1}}\\,;{{eval:h+1}}\\right]$ est celui où $f$ est {{if:s>0|décroissante|croissante}}, ce n'est pas une question de convexité."]},"correctChoiceIndex":["0"]}],"shared":{"cleanCoefficients":true},"test_specs":[{"expected":{"status":"correct"},"variables":{"h":"1","k":"0","s":"1"},"description":"v0 : s=1, bonne réponse","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"h":"1","k":"0","s":"1"},"description":"v0 : intervalle de concavité","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"h":"1","k":"0","s":"1"},"description":"v0 : intervalle de décroissance","variationIndex":0,"selectedChoices":[2]},{"expected":{"status":"correct"},"variables":{"h":"-1","k":"1","s":"-1"},"description":"v0 : s=−1","variationIndex":0,"selectedChoices":[0]}]}$plsc$::jsonb,
  null, null, null);
insert into _plsc_modeles values ('3cb90b97-2ec4-4050-973e-4b194aa65fb3', $plsc$Probabilités$plsc$, $plsc$Autres lois$plsc$, $plsc$loi uniforme discrète$plsc$, array['T_COMP'],
  $plsc${"title":"Loi uniforme sur {1, …, n} : probabilités et espérance","description":"X uniforme sur {1, …, n} : P(X = k) = 1/n, P(X ⩽ k) = k/n, P(a ⩽ X ⩽ b) = (b − a + 1)/n, E(X) = (n + 1)/2 (pièges : n/2, b − a au lieu de b − a + 1)","variations":[{"blanks":[{"expectedAnswer":"{{eval:(n+1)/2}}"}],"statement":"La variable aléatoire $X$ suit la loi uniforme sur $\\{1, 2, \\ldots, {{n}}\\}$.\n\nCalcule son espérance.\n\n$E(X)=?$","variables":[{"name":"n","expression":"5..30"}],"correction":{"steps":["Pour la loi uniforme sur $\\{1, \\ldots, n\\}$ : $E(X)=\\dfrac{n+1}{2}$.","$E(X)=\\dfrac{ {{n}}+1}{2}=\\textcolor{{{color:primary.0}}}{{{eval:(n+1)/2}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:k/n}}"}],"statement":"La variable aléatoire $X$ suit la loi uniforme sur $\\{1, 2, \\ldots, {{n}}\\}$.\n\nCalcule $P(X\\leqslant {{k}})$.\n\n$P(X\\leqslant {{k}})=?$","variables":[{"name":"n","expression":"6..20"},{"name":"k","expression":"2..{{eval:n-1}}"}],"correction":{"steps":["Chaque valeur a la probabilité $\\dfrac{1}{ {{n}} }$, et $X\\leqslant {{k}}$ regroupe les ${{k}}$ valeurs $1, \\ldots, {{k}}$.","$P(X\\leqslant {{k}})=\\dfrac{ {{k}} }{ {{n}} }=\\textcolor{{{color:primary.0}}}{{{eval:k/n}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:(b-a+1)/n}}"}],"statement":"La variable aléatoire $X$ suit la loi uniforme sur $\\{1, 2, \\ldots, {{n}}\\}$.\n\nCalcule $P({{a}}\\leqslant X\\leqslant {{b}})$.\n\n$P({{a}}\\leqslant X\\leqslant {{b}})=?$","variables":[{"name":"n","expression":"10..20"},{"name":"a","expression":"2..5"},{"name":"b","expression":"{{eval:a+2}}..{{eval:n-1}}"}],"correction":{"steps":["De ${{a}}$ à ${{b}}$ inclus, il y a ${{b}}-{{a}}+1={{eval:b-a+1}}$ valeurs, chacune de probabilité $\\dfrac{1}{ {{n}} }$.","$P({{a}}\\leqslant X\\leqslant {{b}})=\\dfrac{ {{eval:b-a+1}} }{ {{n}} }=\\textcolor{{{color:primary.0}}}{{{eval:(b-a+1)/n}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:n+1}}"}],"statement":"On lance un dé équilibré à ${{n}}$ faces numérotées de $1$ à ${{n}}$ et on gagne, en euros, le double du numéro obtenu.\n\nQuel est le gain moyen, en euros ?\n\n$?$","variables":[{"name":"n","expression":"4|6|8|10|12|20"}],"correction":{"steps":["Le numéro $X$ suit la loi uniforme sur $\\{1, \\ldots, {{n}}\\}$ : $E(X)=\\dfrac{ {{n}}+1}{2}={{eval:(n+1)/2;d}}$.","Le gain est $2X$, donc $E(2X)=2E(X)=\\textcolor{{{color:primary.0}}}{{{eval:n+1}}}$ euros."]}}],"shared":{"blankDefaults":{"acceptDecimal":true}},"test_specs":[{"answers":["\\frac{11}{2}"],"expected":{"status":"correct"},"variables":{"n":"10"},"description":"v0 : n = 10 → 11/2","variationIndex":0},{"answers":["5,5"],"expected":{"status":"correct"},"variables":{"n":"10"},"description":"v0 : 5,5 accepté","variationIndex":0},{"answers":["5"],"expected":{"status":"incorrect"},"variables":{"n":"10"},"description":"v0 : n/2 = 5","variationIndex":0},{"answers":["\\frac{2}{5}"],"expected":{"status":"correct"},"variables":{"k":"4","n":"10"},"description":"v1 : n = 10, k = 4 → 2/5","variationIndex":1},{"answers":["\\frac{3}{10}"],"expected":{"status":"incorrect"},"variables":{"k":"4","n":"10"},"description":"v1 : (k − 1)/n","variationIndex":1},{"answers":["\\frac{5}{12}"],"expected":{"status":"correct"},"variables":{"a":"3","b":"7","n":"12"},"description":"v2 : n = 12, de 3 à 7 → 5/12","variationIndex":2},{"answers":["\\frac{1}{3}"],"expected":{"status":"incorrect"},"variables":{"a":"3","b":"7","n":"12"},"description":"v2 : (b − a)/n = 1/3","variationIndex":2},{"answers":["7"],"expected":{"status":"correct"},"variables":{"n":"6"},"description":"v3 : dé à 6 faces → 7","variationIndex":3},{"answers":["3,5"],"expected":{"status":"incorrect"},"variables":{"n":"6"},"description":"v3 : E(X) seulement 3,5","variationIndex":3}]}$plsc$::jsonb,
  $plsc${"title":"Loi uniforme sur {1, …, n} : probabilités","description":"X uniforme sur {1, …, n} : P(X ⩽ k) = k/n, P(a ⩽ X ⩽ b) = (b − a + 1)/n (piège : b − a au lieu de b − a + 1)","variations":[{"blanks":[{"expectedAnswer":"{{eval:k/n}}"}],"statement":"La variable aléatoire $X$ suit la loi uniforme sur $\\{1, 2, \\ldots, {{n}}\\}$.\n\nCalcule $P(X\\leqslant {{k}})$.\n\n$P(X\\leqslant {{k}})=?$","variables":[{"name":"n","expression":"6..20"},{"name":"k","expression":"2..{{eval:n-1}}"}],"correction":{"steps":["Chaque valeur a la probabilité $\\dfrac{1}{ {{n}} }$, et $X\\leqslant {{k}}$ regroupe les ${{k}}$ valeurs $1, \\ldots, {{k}}$.","$P(X\\leqslant {{k}})=\\dfrac{ {{k}} }{ {{n}} }=\\textcolor{{{color:primary.0}}}{{{eval:k/n}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:(b-a+1)/n}}"}],"statement":"La variable aléatoire $X$ suit la loi uniforme sur $\\{1, 2, \\ldots, {{n}}\\}$.\n\nCalcule $P({{a}}\\leqslant X\\leqslant {{b}})$.\n\n$P({{a}}\\leqslant X\\leqslant {{b}})=?$","variables":[{"name":"n","expression":"10..20"},{"name":"a","expression":"2..5"},{"name":"b","expression":"{{eval:a+2}}..{{eval:n-1}}"}],"correction":{"steps":["De ${{a}}$ à ${{b}}$ inclus, il y a ${{b}}-{{a}}+1={{eval:b-a+1}}$ valeurs, chacune de probabilité $\\dfrac{1}{ {{n}} }$.","$P({{a}}\\leqslant X\\leqslant {{b}})=\\dfrac{ {{eval:b-a+1}} }{ {{n}} }=\\textcolor{{{color:primary.0}}}{{{eval:(b-a+1)/n}}}$."]}}],"shared":{"blankDefaults":{"acceptDecimal":true}},"test_specs":[{"answers":["\\frac{2}{5}"],"expected":{"status":"correct"},"variables":{"k":"4","n":"10"},"description":"v0 : n = 10, k = 4 → 2/5","variationIndex":0},{"answers":["\\frac{3}{10}"],"expected":{"status":"incorrect"},"variables":{"k":"4","n":"10"},"description":"v0 : (k − 1)/n","variationIndex":0},{"answers":["\\frac{5}{12}"],"expected":{"status":"correct"},"variables":{"a":"3","b":"7","n":"12"},"description":"v1 : n = 12, de 3 à 7 → 5/12","variationIndex":1},{"answers":["\\frac{1}{3}"],"expected":{"status":"incorrect"},"variables":{"a":"3","b":"7","n":"12"},"description":"v1 : (b − a)/n = 1/3","variationIndex":1}]}$plsc$::jsonb,
  null, null, null);
insert into _plsc_modeles values ('3cfcc718-445a-42f5-8d5e-fe4d8339f4bf', $plsc$Probabilités$plsc$, $plsc$Autres lois$plsc$, $plsc$densité et aire$plsc$, array['T_COMP'],
  $plsc${"title":"Loi à densité : probabilité = aire sous la courbe, constante de normalisation","description":"Lire une probabilité comme une aire sous la densité (figure), fonction de répartition F(x) = P(X ⩽ x), constante k pour que f soit une densité (aire totale 1) (pièges : t/a au lieu de t²/a², b − a au lieu de 1/(b − a))","variations":[{"blanks":[{"expectedAnswer":"{{eval:t^2/a^2}}"}],"statement":"La variable aléatoire $X$ a pour densité la fonction $f$ définie sur $\\left[0\\,;{{a}}\\right]$ par $f(x)={{eval:2/a^2}}x$, représentée ci-dessous.\n\n```courbe\nx: -0.5 ; {{eval:a+1}}\ny: -0.1 ; {{eval:2/a+0.2;d}}\ngrille: 1 ; {{eval:1/(2*a);d}}\nf(x) = 2*x/{{eval:a^2}} sur [0 ; {{a}}]   bleu   nom=C_f\naire: f ; 0 ; {{t}}\ntaille: moyenne\ndescription: Densité triangulaire croissante sur [0 ; {{a}}], aire coloriée entre 0 et {{t}}.\n```\n\nCalcule $P(X\\leqslant {{t}})$, aire du domaine colorié.\n\n$P(X\\leqslant {{t}})=?$","variables":[{"name":"a","expression":"2..6"},{"name":"t","expression":"1..{{eval:a-1}}"}],"correction":{"steps":["$P(X\\leqslant {{t}})$ est l'aire du triangle de base ${{t}}$ et de hauteur $f({{t}})={{eval:2*t/a^2}}$.","$P(X\\leqslant {{t}})=\\dfrac{1}{2}\\times {{t}}\\times{{eval:2*t/a^2}}=\\textcolor{{{color:primary.0}}}{{{eval:t^2/a^2}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:c/b}}"}],"statement":"La variable aléatoire $X$ suit la loi uniforme sur $\\left[0\\,;{{b}}\\right]$, de densité représentée ci-dessous. On note $F$ sa fonction de répartition : $F(x)=P(X\\leqslant x)$.\n\n```courbe\nx: -0.5 ; {{eval:b+1}}\ny: -0.05 ; {{eval:1/b+0.1;d}}\ngrille: 1 ; {{eval:1/b;d}}\nf(x) = 1/{{b}} sur [0 ; {{b}}]   bleu   nom=C_f\naire: f ; 0 ; {{c}}\ntaille: moyenne\ndescription: Densité constante sur [0 ; {{b}}], rectangle colorié entre 0 et {{c}}.\n```\n\nCalcule $F({{c}})$.\n\n$F({{c}})=?$","variables":[{"name":"b","expression":"4..10"},{"name":"c","expression":"1..{{eval:b-1}}"}],"correction":{"steps":["$F({{c}})=P(X\\leqslant {{c}})$ est l'aire du rectangle colorié, de largeur ${{c}}$ et de hauteur $\\dfrac{1}{ {{b}} }$.","$F({{c}})=\\dfrac{ {{c}} }{ {{b}} }=\\textcolor{{{color:primary.0}}}{{{eval:c/b}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:1/(b-a)}}"}],"statement":"On définit sur $\\left[{{a}}\\,;{{b}}\\right]$ la fonction constante $f(x)=k$, avec $k$ réel.\n\nPour quelle valeur de $k$ la fonction $f$ est-elle une densité de probabilité sur $\\left[{{a}}\\,;{{b}}\\right]$ ?\n\n$k=?$","variables":[{"name":"a","expression":"0..5"},{"name":"b","expression":"{{eval:a+2}}..{{eval:a+12}}"}],"correction":{"steps":["Une densité est positive et l'aire sous sa courbe vaut $1$ : $\\displaystyle\\int_{ {{a}} }^{ {{b}} }k\\,\\mathrm{d}x=k\\times({{b}}-{{a}})=1$.","$k=\\textcolor{{{color:primary.0}}}{{{eval:1/(b-a)}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:2/a^2}}"}],"statement":"On définit sur $\\left[0\\,;{{a}}\\right]$ la fonction $f(x)=kx$, avec $k$ réel strictement positif.\n\nPour quelle valeur de $k$ la fonction $f$ est-elle une densité de probabilité sur $\\left[0\\,;{{a}}\\right]$ ?\n\n$k=?$","variables":[{"name":"a","expression":"2..10"}],"correction":{"steps":["$f$ est positive ; il faut $\\displaystyle\\int_{0}^{ {{a}} }kx\\,\\mathrm{d}x=\\left[\\dfrac{kx^{2}}{2}\\right]_{0}^{ {{a}} }=\\dfrac{ {{eval:a^2}}k}{2}=1$.","$k=\\dfrac{2}{ {{eval:a^2}} }=\\textcolor{{{color:primary.0}}}{{{eval:2/a^2}}}$."]}}],"shared":{"blankDefaults":{"acceptDecimal":true}},"test_specs":[{"answers":["\\frac{1}{4}"],"expected":{"status":"correct"},"variables":{"a":"4","t":"2"},"description":"v0 : a = 4, t = 2 → 1/4","variationIndex":0},{"answers":["\\frac{1}{2}"],"expected":{"status":"incorrect"},"variables":{"a":"4","t":"2"},"description":"v0 : t/a = 1/2","variationIndex":0},{"answers":["\\frac{4}{25}"],"expected":{"status":"correct"},"variables":{"a":"5","t":"2"},"description":"v0 : a = 5, t = 2 → 4/25","variationIndex":0},{"answers":["\\frac{2}{5}"],"expected":{"status":"incorrect"},"variables":{"a":"5","t":"2"},"description":"v0 : a = 5, t = 2, t/a = 2/5","variationIndex":0},{"answers":["\\frac{3}{8}"],"expected":{"status":"correct"},"variables":{"b":"8","c":"3"},"description":"v1 : b = 8, c = 3 → 3/8","variationIndex":1},{"answers":["\\frac{1}{8}"],"expected":{"status":"incorrect"},"variables":{"b":"8","c":"3"},"description":"v1 : hauteur 1/8","variationIndex":1},{"answers":["\\frac{1}{5}"],"expected":{"status":"correct"},"variables":{"a":"2","b":"7"},"description":"v2 : [2 ; 7] → 1/5","variationIndex":2},{"answers":["5"],"expected":{"status":"incorrect"},"variables":{"a":"2","b":"7"},"description":"v2 : b − a = 5","variationIndex":2},{"answers":["\\frac{1}{8}"],"expected":{"status":"correct"},"variables":{"a":"4"},"description":"v3 : a = 4 → 1/8","variationIndex":3},{"answers":["\\frac{1}{16}"],"expected":{"status":"incorrect"},"variables":{"a":"4"},"description":"v3 : 1/a² = 1/16","variationIndex":3}]}$plsc$::jsonb,
