insert into _plsc_modeles values ('44a4236b-be18-4835-a6e0-c50f0b36833f', $plsc$Arithmétique$plsc$, $plsc$PGCD, Bézout et Gauss$plsc$, $plsc$théorèmes de Bézout et de Gauss$plsc$, array['T_EXP'],
  $plsc${"title":"Gauss, Bézout, premiers entre eux : quelle conclusion ?","description":"Choisir la conclusion correcte du théorème de Gauss ou de Bézout (pièges : conclure sur le mauvais facteur, oublier l'hypothèse « premiers entre eux », croire que au + bv = d donne PGCD(a, b) = d)","variations":[{"choices":[{"content":"${{b}}$ divise $x$"},{"content":"${{a}}$ divise $x$"},{"content":"$x = {{b}}$ et $y = {{a}}$"},{"content":"${{b}}$ divise $y$"}],"statement":"$x$ et $y$ sont des entiers tels que ${{a}}x = {{b}}y$.\n\nQue peut-on en déduire ?","variables":[{"name":"a","expression":"3..15"},{"name":"b","expression":"4..16"}],"conditions":["gcd(a,b) == 1","a != b"],"correction":{"steps":["${{b}}$ divise ${{a}}x$ et $\\mathrm{PGCD}({{a}} \\,;\\, {{b}}) = 1$.","D'après le théorème de Gauss, $\\textcolor{{{color:primary.0}}}{{{b}} \\text{ divise } x}$ (et de même ${{a}}$ divise $y$). $x = {{b}}$ n'est qu'une solution parmi d'autres : $x = {{eval:2*b}}$, $y = {{eval:2*a}}$ convient aussi."]},"correctChoiceIndex":["0"]},{"choices":[{"content":"${{a}}$ divise $n$"},{"content":"${{a}}$ divise ${{c}}$"},{"content":"${{c}}$ divise $n$"},{"content":"$n = {{a}}$"}],"statement":"$n$ est un entier tel que ${{a}}$ divise ${{c}}n$.\n\nQue peut-on en déduire ?","variables":[{"name":"a","expression":"5..13"},{"name":"c","expression":"4..30"}],"conditions":["gcd(a,c) == 1"],"correction":{"steps":["$\\mathrm{PGCD}({{a}} \\,;\\, {{c}}) = 1$ : ${{a}}$ et ${{c}}$ sont premiers entre eux.","D'après le théorème de Gauss, $\\textcolor{{{color:primary.0}}}{{{a}} \\text{ divise } n}$."]},"correctChoiceIndex":["0"]},{"choices":[{"content":"$\\mathrm{PGCD}(a \\,;\\, b)$ divise ${{d}}$"},{"content":"$\\mathrm{PGCD}(a \\,;\\, b) = {{d}}$"},{"content":"$a$ et $b$ sont premiers entre eux"},{"content":"${{d}}$ divise $a$ et $b$"}],"statement":"$a$ et $b$ sont des entiers tels que ${{s}}a + {{t}}b = {{d}}$.\n\nQue peut-on en déduire ?","variables":[{"name":"s","expression":"2..9"},{"name":"t","expression":"2..9"},{"name":"d","expression":"2..6"}],"conditions":["s != t"],"correction":{"steps":["Tout diviseur commun de $a$ et $b$ divise ${{s}}a + {{t}}b = {{d}}$ : $\\textcolor{{{color:primary.0}}}{\\mathrm{PGCD}(a \\,;\\, b) \\text{ divise } {{d}}}$.","Seule l'égalité $au + bv = 1$ permet de conclure (Bézout). Ici le PGCD divise ${{d}}$ sans être forcément égal à ${{d}}$ : par exemple $2 \\times 3 + 1 \\times (-4) = 2$, alors que $\\mathrm{PGCD}(3 \\,;\\, -4) = 1$."]},"correctChoiceIndex":["0"]},{"choices":[{"content":"$a$ et $b$ sont premiers entre eux"},{"content":"$\\mathrm{PGCD}(a \\,;\\, b) = {{s}}$"},{"content":"$a$ divise $b$"},{"content":"$a = {{t}}$ et $b = {{s}}$"}],"statement":"$a$ et $b$ sont des entiers tels que ${{s}}a - {{t}}b = 1$.\n\nQue peut-on en déduire ?","variables":[{"name":"s","expression":"2..9"},{"name":"t","expression":"2..9"}],"conditions":["s != t"],"correction":{"steps":["$au + bv = 1$ avec $u = {{s}}$ et $v = {{eval:-t}}$ entiers.","D'après le théorème de Bézout, $\\textcolor{{{color:primary.0}}}{a \\text{ et } b \\text{ sont premiers entre eux}}$."]},"correctChoiceIndex":["0"]}],"shared":null,"test_specs":[{"expected":{"status":"correct"},"variables":{"a":"4","b":"9"},"description":"v0 : b divise x","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"a":"4","b":"9"},"description":"v0 : a divise x (facteur inversé)","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"4","b":"9"},"description":"v0 : x = b seulement","variationIndex":0,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{"a":"4","b":"9"},"description":"v0 : b divise y","variationIndex":0,"selectedChoices":[3]},{"expected":{"status":"correct"},"variables":{"a":"7","c":"12"},"description":"v1 : a divise n","variationIndex":1,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"a":"7","c":"12"},"description":"v1 : a divise c","variationIndex":1,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"d":"4","s":"3","t":"5"},"description":"v2 : PGCD divise d","variationIndex":2,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"d":"4","s":"3","t":"5"},"description":"v2 : PGCD = d (piège)","variationIndex":2,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"s":"3","t":"2"},"description":"v3 : premiers entre eux","variationIndex":3,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"s":"3","t":"2"},"description":"v3 : PGCD = s","variationIndex":3,"selectedChoices":[1]}]}$plsc$::jsonb,
  $plsc${"title":"Théorème de Gauss : quelle conclusion ?","description":"Choisir la conclusion correcte du théorème de Gauss (pièges : conclure sur le mauvais facteur, oublier l'hypothèse « premiers entre eux »)","variations":[{"choices":[{"content":"${{b}}$ divise $x$"},{"content":"${{a}}$ divise $x$"},{"content":"$x = {{b}}$ et $y = {{a}}$"},{"content":"${{b}}$ divise $y$"}],"statement":"$x$ et $y$ sont des entiers tels que ${{a}}x = {{b}}y$.\n\nQue peut-on en déduire ?","variables":[{"name":"a","expression":"3..15"},{"name":"b","expression":"4..16"}],"conditions":["gcd(a,b) == 1","a != b"],"correction":{"steps":["${{b}}$ divise ${{a}}x$ et $\\mathrm{PGCD}({{a}} \\,;\\, {{b}}) = 1$.","D'après le théorème de Gauss, $\\textcolor{{{color:primary.0}}}{{{b}} \\text{ divise } x}$ (et de même ${{a}}$ divise $y$). $x = {{b}}$ n'est qu'une solution parmi d'autres : $x = {{eval:2*b}}$, $y = {{eval:2*a}}$ convient aussi."]},"correctChoiceIndex":["0"]},{"choices":[{"content":"${{a}}$ divise $n$"},{"content":"${{a}}$ divise ${{c}}$"},{"content":"${{c}}$ divise $n$"},{"content":"$n = {{a}}$"}],"statement":"$n$ est un entier tel que ${{a}}$ divise ${{c}}n$.\n\nQue peut-on en déduire ?","variables":[{"name":"a","expression":"5..13"},{"name":"c","expression":"4..30"}],"conditions":["gcd(a,c) == 1"],"correction":{"steps":["$\\mathrm{PGCD}({{a}} \\,;\\, {{c}}) = 1$ : ${{a}}$ et ${{c}}$ sont premiers entre eux.","D'après le théorème de Gauss, $\\textcolor{{{color:primary.0}}}{{{a}} \\text{ divise } n}$."]},"correctChoiceIndex":["0"]}],"shared":null,"test_specs":[{"expected":{"status":"correct"},"variables":{"a":"4","b":"9"},"description":"v0 : b divise x","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"a":"4","b":"9"},"description":"v0 : a divise x (facteur inversé)","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"4","b":"9"},"description":"v0 : x = b seulement","variationIndex":0,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{"a":"4","b":"9"},"description":"v0 : b divise y","variationIndex":0,"selectedChoices":[3]},{"expected":{"status":"correct"},"variables":{"a":"7","c":"12"},"description":"v1 : a divise n","variationIndex":1,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"a":"7","c":"12"},"description":"v1 : a divise c","variationIndex":1,"selectedChoices":[1]}]}$plsc$::jsonb,
