insert into _plsc_modeles values ('536db399-2e04-45fc-9f0b-a37a7678d8e8', $plsc$Géométrie$plsc$, $plsc$Orthogonalité et distances dans l'espace$plsc$, $plsc$orthogonalité de droites et plans$plsc$, array['T_SPE'],
