insert into _plsc_modeles values ('629c231b-50d4-459f-9361-fa8098f4d079', $plsc$Arithmétique$plsc$, $plsc$Nombres premiers$plsc$, $plsc$décomposition en facteurs premiers$plsc$, array['T_EXP'],
  $plsc${"title":"Décomposition en facteurs premiers et nombre de diviseurs","description":"Décomposer un entier en produit de facteurs premiers (écriture avec puissances), en déduire le nombre de diviseurs, le plus petit facteur qui rend un carré parfait (pièges : facteur non premier comme 9 ou 4, produit non décomposé, (a+1)(b+1)(c+1) confondu avec abc)","variations":[{"blanks":[{"expectedAnswer":"2^{ {{a}} }\\times3^{ {{b}} }\\times{{q}}"}],"statement":"Décompose ${{eval:2^a*3^b*q}}$ en produit de facteurs premiers (écris les facteurs répétés avec des puissances).\n\n$?$","variables":[{"name":"a","expression":"2..4"},{"name":"b","expression":"2..3"},{"name":"q","expression":"5|7|11"}],"correction":{"steps":["On divise par $2$ tant que c'est possible (${{a}}$ fois), puis par $3$ (${{b}}$ fois) : il reste ${{q}}$, premier.","${{eval:2^a*3^b*q}} = \\textcolor{{{color:primary.0}}}{2^{ {{a}} } \\times 3^{ {{b}} } \\times {{q}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:(a+1)*(b+1)*(c+1)}}"}],"statement":"$n = 2^{ {{a}} } \\times 3^{ {{b}} } \\times 5^{ {{c}} }$. Combien $n$ a-t-il de diviseurs positifs ?\n\n$?$","variables":[{"name":"a","expression":"2..6"},{"name":"b","expression":"2..5"},{"name":"c","expression":"2..4"}],"correction":{"steps":["Un diviseur positif de $n$ s'écrit $2^{\\alpha} \\times 3^{\\beta} \\times 5^{\\gamma}$ avec $0 \\leqslant \\alpha \\leqslant {{a}}$, $0 \\leqslant \\beta \\leqslant {{b}}$, $0 \\leqslant \\gamma \\leqslant {{c}}$.","Il y en a $({{a}} + 1)({{b}} + 1)({{c}} + 1) = \\textcolor{{{color:primary.0}}}{{{eval:(a+1)*(b+1)*(c+1)}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:2^(mod(a,2))*3^(mod(b,2))*5^(mod(c,2))}}"}],"statement":"Quel est le plus petit entier $k \\geqslant 1$ tel que ${{eval:2^a*3^b*5^c}}k$ soit le carré d'un entier ?\n\n$k=?$","variables":[{"name":"a","expression":"1..4"},{"name":"b","expression":"1..3"},{"name":"c","expression":"0..2"}],"conditions":["mod(a,2) + mod(b,2) + mod(c,2) >= 1"],"correction":{"steps":["${{eval:2^a*3^b*5^c}} = 2^{ {{a}} } \\times 3^{ {{b}} } \\times 5^{ {{c}} }$.","Un carré a tous ses exposants pairs : on complète chaque exposant impair par un facteur.","$k = \\textcolor{{{color:primary.0}}}{{{eval:2^(mod(a,2))*3^(mod(b,2))*5^(mod(c,2))}}}$."]}}],"shared":null,"test_specs":[{"answers":["2^3\\times3^2\\times5"],"expected":{"status":"correct"},"variables":{"a":"3","b":"2","q":"5"},"description":"v0 : 360 = 2³ × 3² × 5","variationIndex":0},{"answers":["5\\times3^2\\times2^3"],"expected":{"status":"correct"},"variables":{"a":"3","b":"2","q":"5"},"description":"v0 : ordre des facteurs libre","variationIndex":0},{"answers":["2^3\\cdot3^2\\cdot5"],"expected":{"status":"correct"},"variables":{"a":"3","b":"2","q":"5"},"description":"v0 : avec \\cdot","variationIndex":0},{"answers":["360"],"expected":{"status":"bad_form","constraintViolations":["form"]},"variables":{"a":"3","b":"2","q":"5"},"description":"v0 : 360 non décomposé","variationIndex":0},{"answers":["8\\times45"],"expected":{"status":"bad_form","constraintViolations":["form"]},"variables":{"a":"3","b":"2","q":"5"},"description":"v0 : 8 × 45","variationIndex":0},{"answers":["2^3\\times9\\times5"],"expected":{"status":"bad_form","constraintViolations":["form"]},"variables":{"a":"3","b":"2","q":"5"},"description":"v0 : 9 n'est pas premier","variationIndex":0},{"answers":["2\\times2\\times2\\times3\\times3\\times5"],"expected":{"status":"bad_form","constraintViolations":["form"]},"variables":{"a":"3","b":"2","q":"5"},"description":"v0 : sans puissances","variationIndex":0},{"answers":["2^3\\times3\\times5"],"expected":{"status":"incorrect"},"variables":{"a":"3","b":"2","q":"5"},"description":"v0 : exposant faux","variationIndex":0},{"answers":["36"],"expected":{"status":"correct"},"variables":{"a":"3","b":"2","c":"2"},"description":"v1 : 2³×3²×5² → 36","variationIndex":1},{"answers":["12"],"expected":{"status":"incorrect"},"variables":{"a":"3","b":"2","c":"2"},"description":"v1 : 12 (produit des exposan