insert into _plsc_modeles values ('71cb8ab7-664a-45f6-83b0-6b0739ebb5a1', $plsc$Probabilités$plsc$, $plsc$Sommes et concentration$plsc$, $plsc$espérance et variance d'une somme$plsc$, array['T_SPE'],
  $plsc${"title":"Somme de variables aléatoires : espérance et variance","description":"E(aX + bY) = aE(X) + bE(Y) ; si X et Y indépendantes : V(X + Y) = V(X) + V(Y), V(X − Y) = V(X) + V(Y), V(aX + bY) = a²V(X) + b²V(Y), écart type de la somme (pièges : V(X) − V(Y), aV(X), σ(X) + σ(Y))","variations":[{"blanks":[{"expectedAnswer":"{{eval:a*u+b*w}}"}],"statement":"Deux variables aléatoires $X$ et $Y$ vérifient $E(X)={{u}}$ et $E(Y)={{w}}$.\n\nCalcule $E({{a}}X+{{b}}Y)$.\n\n$E({{a}}X+{{b}}Y)=?$","variables":[{"name":"u","expression":"1..9;±"},{"name":"w","expression":"1..9;±"},{"name":"a","expression":"2..5"},{"name":"b","expression":"2..5"}],"correction":{"steps":["Linéarité de l'espérance (vraie même si $X$ et $Y$ ne sont pas indépendantes) : $E(aX+bY)=aE(X)+bE(Y)$.","$E({{a}}X+{{b}}Y)={{a}}\\times{{u;()}}+{{b}}\\times{{w;()}}=\\textcolor{{{color:primary.0}}}{{{eval:a*u+b*w}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:(u+w)/10}}"}],"statement":"Deux variables aléatoires **indépendantes** $X$ et $Y$ vérifient $V(X)={{eval:u/10;d}}$ et $V(Y)={{eval:w/10;d}}$.\n\nCalcule $V(X+Y)$.\n\n$V(X+Y)=?$","variables":[{"name":"u","expression":"5..60"},{"name":"w","expression":"5..60"}],"correction":{"steps":["$X$ et $Y$ sont indépendantes, donc $V(X+Y)=V(X)+V(Y)$.","$V(X+Y)={{eval:u/10;d}}+{{eval:w/10;d}}=\\textcolor{{{color:primary.0}}}{{{eval:(u+w)/10;d}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:u+w}}"}],"statement":"Deux variables aléatoires **indépendantes** $X$ et $Y$ vérifient $V(X)={{u}}$ et $V(Y)={{w}}$.\n\nCalcule $V(X-Y)$.\n\n$V(X-Y)=?$","variables":[{"name":"u","expression":"5..20"},{"name":"w","expression":"1..4"}],"correction":{"steps":["$V(X-Y)=V(X)+V(-Y)$ par indépendance, et $V(-Y)=(-1)^{2}V(Y)=V(Y)$ : une variance ne diminue jamais quand on ajoute une variable indépendante.","$V(X-Y)={{u}}+{{w}}=\\textcolor{{{color:primary.0}}}{{{eval:u+w}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:a^2*u+b^2*w}}"}],"statement":"Deux variables aléatoires **indépendantes** $X$ et $Y$ vérifient $V(X)={{u}}$ et $V(Y)={{w}}$.\n\nCalcule $V({{a}}X+{{b}}Y)$.\n\n$V({{a}}X+{{b}}Y)=?$","variables":[{"name":"u","expression":"1..9"},{"name":"w","expression":"1..9"},{"name":"a","expression":"2..4"},{"name":"b","expression":"2..3"}],"correction":{"steps":["Par indépendance, $V(aX+bY)=V(aX)+V(bY)=a^{2}V(X)+b^{2}V(Y)$.","$V({{a}}X+{{b}}Y)={{eval:a^2}}\\times{{u}}+{{eval:b^2}}\\times{{w}}=\\textcolor{{{color:primary.0}}}{{{eval:a^2*u+b^2*w}}}$."]}},{"blanks":[{"expectedAnswer":"{{sz}}"}],"statement":"Deux variables aléatoires **indépendantes** $X$ et $Y$ ont pour écarts types $\\sigma(X)={{sx}}$ et $\\sigma(Y)={{sy}}$.\n\nCalcule $\\sigma(X+Y)$.\n\n$\\sigma(X+Y)=?$","variables":[{"name":"w","expression":"1..5"},{"name":"sx","expression":"{{if:w==1|3|{{if:w==2|6|{{if:w==3|5|{{if:w==4|8|9}}}}}}}}"},{"name":"sy","expression":"{{if:w==1|4|{{if:w==2|8|{{if:w==3|12|{{if:w==4|15|12}}}}}}}}"},{"name":"sz","expression":"{{if:w==1|5|{{if:w==2|10|{{if:w==3|13|{{if:w==4|17|15}}}}}}}}"}],"correction":{"steps":["Ce sont les **variances** qui s'ajoutent : $V(X+Y)={{sx}}^{2}+{{sy}}^{2}={{eval:sz^2}}$.","$\\sigma(X+Y)=\\sqrt{ {{eval:sz^2}} }=\\textcolor{{{color:primary.0}}}{{{sz}}}$ (et non ${{sx}}+{{sy}}={{eval:sx+sy}}$)."]}}],"shared":{"blankDefaults":{"acceptDecimal":true}},"test_specs":[{"answers":["5"],"expected":{"status":"correct"},"variables":{"a":"2","b":"3","u":"4","w":"-1"},"description":"v0 : E(2X + 3Y), 4 et −1 → 5","variationIndex":0},{"answers":["3"],"expected":{"status":"incorrect"},"variables":{"a":"2","b":"3","u":"4","w":"-1"},"description":"v0 : a + b oubliés : 3","variationIndex":0},{"answers":["4,7"],"expected":{"status":"correct"},"variables":{"u":"12","w":"35"},"description":"v1 : 1,2 + 3,5 = 4,7","variationIndex":1},{"answers":["4,2"],"expected":{"status":"incorrect"},"variables":{"u":"12","w":"35"},"description":"v1 : produit","variationIndex":1},{"answers":["15"],"expected":{"status":"correct"},"variables":{"u":"12","w":"3"},"description":"v2 : V(X − Y) = 12 + 3 = 15","variationIndex":2},{"answers":["9"],"expected":{"status":"incorrect"},"variables":{"u":"12","w":"3"},"description":"v2 : V(X) − V(Y) = 9","variationIndex":2},{"answers":["61"],"expected":{"status":"correct"},"variables":{"a":"3","b":"2","u":"5","w":"4"},"description":"v3 : V(3X + 2Y), 5 et 4 → 61","variationIndex":3},{"answers":["23"],"expected":{"status":"incorrect"},"variables":{"a":"3","b":"2","u":"5","w":"4"},"description":"v3 : aV(X) + bV(Y) = 23","variationIndex":3},{"answers":["5"],"expected":{"status":"correct"},"variables":{"w":"1"},"description":"v4 : 3 et 4 → 5","variationIndex":4},{"answers":["7"],"expected":{"status":"incorrect"},"variables":{"w":"1"},"description":"v4 : σ(X) + σ(Y) = 7","variationIndex":4},{"answers":["25"],"expected":{"status":"incorrect"},"variables":{"w":"1"},"description":"v4 : variance 25","variationIndex":4}]}$plsc$::jsonb,
  $plsc${"title":"Somme de variables aléatoires indépendantes : variance","description":"X et Y indépendantes : V(X + Y) = V(X − Y) = V(X) + V(Y), V(aX + bY) = a²V(X) + b²V(Y), écart type de la somme (pièges : V(X) − V(Y), aV(X), σ(X) + σ(Y))","variations":[{"blanks":[{"expectedAnswer":"{{eval:(u+w)/10}}"}],"statement":"Deux variables aléatoires **indépendantes** $X$ et $Y$ vérifient $V(X)={{eval:u/10;d}}$ et $V(Y)={{eval:w/10;d}}$.\n\nCalcule $V(X+Y)$.\n\n$V(X+Y)=?$","variables":[{"name":"u","expression":"5..60"},{"name":"w","expression":"5..60"}],"correction":{"steps":["$X$ et $Y$ sont indépendantes, donc $V(X+Y)=V(X)+V(Y)$.","$V(X+Y)={{eval:u/10;d}}+{{eval:w/10;d}}=\\textcolor{{{color:primary.0}}}{{{eval:(u+w)/10;d}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:u+w}}"}],"statement":"Deux variables aléatoires **indépendantes** $X$ et $Y$ vérifient $V(X)={{u}}$ et $V(Y)={{w}}$.\n\nCalcule $V(X-Y)$.\n\n$V(X-Y)=?$","variables":[{"name":"u","expression":"5..20"},{"name":"w","expression":"1..4"}],"correction":{"steps":["$V(X-Y)=V(X)+V(-Y)$ par indépendance, et $V(-Y)=(-1)^{2}V(Y)=V(Y)$ : une variance ne diminue jamais quand on ajoute une variable indépendante.","$V(X-Y)={{u}}+{{w}}=\\textcolor{{{color:primary.0}}}{{{eval:u+w}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:a^2*u+b^2*w}}"}],"statement":"Deux variables aléatoires **indépendantes** $X$ et $Y$ vérifient $V(X)={{u}}$ et $V(Y)={{w}}$.\n\nCalcule $V({{a}}X+{{b}}Y)$.\n\n$V({{a}}X+{{b}}Y)=?$","variables":[{"name":"u","expression":"1..9"},{"name":"w","expression":"1..9"},{"name":"a","expression":"2..4"},{"name":"b","expression":"2..3"}],"correction":{"steps":["Par indépendance, $V(aX+bY)=V(aX)+V(bY)=a^{2}V(X)+b^{2}V(Y)$.","$V({{a}}X+{{b}}Y)={{eval:a^2}}\\times{{u}}+{{eval:b^2}}\\times{{w}}=\\textcolor{{{color:primary.0}}}{{{eval:a^2*u+b^2*w}}}$."]}},{"blanks":[{"expectedAnswer":"{{sz}}"}],"statement":"Deux variables aléatoires **indépendantes** $X$ et $Y$ ont pour écarts types $\\sigma(X)={{sx}}$ et $\\sigma(Y)={{sy}}$.\n\nCalcule $\\sigma(X+Y)$.\n\n$\\sigma(X+Y)=?$","variables":[{"name":"w","expression":"1..5"},{"name":"sx","expression":"{{if:w==1|3|{{if:w==2|6|{{if:w==3|5|{{if:w==4|8|9}}}}}}}}"},{"name":"sy","expression":"{{if:w==1|4|{{if:w==2|8|{{if:w==3|12|{{if:w==4|15|12}}}}}}}}"},{"name":"sz","expression":"{{if:w==1|5|{{if:w==2|10|{{if:w==3|13|{{if:w==4|17|15}}}}}}}}"}],"correction":{"steps":["Ce sont les **variances** qui s'ajoutent : $V(X+Y)={{sx}}^{2}+{{sy}}^{2}={{eval:sz^2}}$.","$\\sigma(X+Y)=\\sqrt{ {{eval:sz^2}} }=\\textcolor{{{color:primary.0}}}{{{sz}}}$ (et non ${{sx}}+{{sy}}={{eval:sx+sy}}$)."]}}],"shared":{"blankDefaults":{"acceptDecimal":true}},"test_specs":[{"answers":["4,7"],"expected":{"status":"correct"},"variables":{"u":"12","w":"35"},"description":"v0 : 1,2 + 3,5 = 4,7","variationIndex":0},{"answers":["4,2"],"expected":{"status":"incorrect"},"variables":{"u":"12","w":"35"},"description":"v0 : produit","variationIndex":0},{"answers":["15"],"expected":{"status":"correct"},"variables":{"u":"12","w":"3"},"description":"v1 : V(X − Y) = 12 + 3 = 15","variationIndex":1},{"answers":["9"],"expected":{"status":"incorrect"},"variables":{"u":"12","w":"3"},"description":"v1 : V(X) − V(Y) = 9","variationIndex":1},{"answers":["61"],"expected":{"status":"correct"},"variables":{"a":"3","b":"2","u":"5","w":"4"},"description":"v2 : V(3X + 2Y), 5 et 4 → 61","variationIndex":2},{"answers":["23"],"expected":{"status":"incorrect"},"variables":{"a":"3","b":"2","u":"5","w":"4"},"description":"v2 : aV(X) + bV(Y) = 23","variationIndex":2},{"answers":["5"],"expected":{"status":"correct"},"variables":{"w":"1"},"description":"v3 : 3 et 4 → 5","variationIndex":3},{"answers":["7"],"expected":{"status":"incorrect"},"variables":{"w":"1"},"description":"v3 : σ(X) + σ(Y) = 7","variationIndex":3},{"answers":["25"],"expected":{"status":"incorrect"},"variables":{"w":"1"},"description":"v3 : variance 25","variationIndex":3}]}$plsc$::jsonb,
