,"variables":{"a":"1","b":"2","c":"4","d":"-1"},"description":"v0 z_A + z_B → 5+i","variationIndex":0},{"answers":["2+4i"],"expected":{"status":"correct"},"variables":{"a":"1","b":"1","c":"3","d":"2","g":"4","h2":"5"},"description":"v1 A(1+i), B(3+2i), C(4+5i) : D = 2+4i","variationIndex":1},{"answers":["6+6i"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"1","c":"3","d":"2","g":"4","h2":"5"},"description":"v1 z_B + z_C − z_A → 6+6i","variationIndex":1},{"answers":["-2i"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"1","c":"3","d":"2","g":"4","h2":"5"},"description":"v1 z_A + z_B − z_C → −2i","variationIndex":1}]}$plsc$::jsonb,
