insert into _plsc_modeles values ('7d552757-61db-493a-a846-7d2cdc0ec631', $plsc$Fonctions$plsc$, $plsc$Fonctions trigonométriques$plsc$, $plsc$équations$plsc$, array['T_SPE'],
  $plsc${"title":"Reconnaître une équation ou une inéquation sur le cercle trigonométrique","description":"Arc ou points du cercle (mesures principales) : retrouver cos x ⩾ a, sin x ⩾ a ou sin x = a (pièges : cosinus = abscisse et sinus = ordonnée confondus, sens, signe)","variations":[{"choices":[{"content":"$\\cos x\\geqslant{{eval:cos(n*\\pi/12)}}$"},{"content":"$\\cos x\\leqslant{{eval:cos(n*\\pi/12)}}$"},{"content":"$\\sin x\\geqslant{{eval:cos(n*\\pi/12)}}$"},{"content":"$\\sin x\\leqslant{{eval:cos(n*\\pi/12)}}$"}],"statement":"Sur le cercle trigonométrique ci-dessous, l'arc coloré représente l'ensemble des solutions dans $\\left]-\\pi\\,;\\pi\\right]$ d'une inéquation.\n\n```trig\npreset: custom\nangles: -{{n}}*pi/12, {{n}}*pi/12\nequation: cos(x) >= cos({{n}}*pi/12)\nmode: arc\nmesures: principales\n```\n\nDe quelle inéquation s'agit-il ?","variables":[{"name":"a","expression":"\\frac{\\pi}{6}|\\frac{\\pi}{4}|\\frac{\\pi}{3}"},{"name":"n","expression":"eval:12*a/\\pi"}],"correction":{"steps":["L'arc est symétrique par rapport à l'axe des abscisses et va de $-{{a}}$ à ${{a}}$ : ce sont les points d'**abscisse** (cosinus) supérieure ou égale à $\\cos{{a}}={{eval:cos(n*\\pi/12)}}$.","Il s'agit de $\\textcolor{{{color:primary.0}}}{\\cos x\\geqslant{{eval:cos(n*\\pi/12)}}}$."]},"correctChoiceIndex":["0"]},{"choices":[{"content":"$\\sin x\\geqslant{{eval:sin(n*\\pi/12)}}$"},{"content":"$\\sin x\\leqslant{{eval:sin(n*\\pi/12)}}$"},{"content":"$\\cos x\\geqslant{{eval:sin(n*\\pi/12)}}$"},{"content":"$\\cos x\\leqslant{{eval:sin(n*\\pi/12)}}$"}],"statement":"Sur le cercle trigonométrique ci-dessous, l'arc coloré représente l'ensemble des solutions dans $\\left]-\\pi\\,;\\pi\\right]$ d'une inéquation.\n\n```trig\npreset: custom\nangles: {{n}}*pi/12, {{eval:12-n}}*pi/12\nequation: sin(x) >= sin({{n}}*pi/12)\nmode: arc\nmesures: principales\n```\n\nDe quelle inéquation s'agit-il ?","variables":[{"name":"a","expression":"\\frac{\\pi}{6}|\\frac{\\pi}{4}|\\frac{\\pi}{3}"}