insert into _plsc_modeles values ('7d9d9b81-e11f-4572-8221-21e95107112d', $plsc$Dénombrement$plsc$, $plsc$Combinaisons$plsc$, $plsc$coefficients binomiaux$plsc$, array['T_SPE'],
  $plsc${"title":"Factorielle, arrangements et formule des coefficients binomiaux","description":"n!, nombre de k-uplets d'éléments distincts, C(n, 2) = n(n − 1)/2 et C(n, 3) par la formule (pièges : n(n − 1) sans diviser par 2, C(n, 3) pour un podium ordonné)","variations":[{"blanks":[{"expectedAnswer":"{{eval:n*(n-1)/2}}"}],"statement":"Calcule $\\binom{ {{n}} }{2}$.\n\n$\\binom{ {{n}} }{2}=?$","variables":[{"name":"n","expression":"6..30"}],"correction":{"steps":["$\\binom{n}{2}=\\dfrac{n(n-1)}{2}$.","$\\binom{ {{n}} }{2}=\\dfrac{ {{n}}\\times{{eval:n-1}} }{2}=\\textcolor{{{color:primary.0}}}{{{eval:n*(n-1)/2}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:n*(n-1)*(n-2)/6}}"}],"statement":"Calcule $\\binom{ {{n}} }{3}$.\n\n$\\binom{ {{n}} }{3}=?$","variables":[{"name":"n","expression":"6..12"}],"correction":{"steps":["$\\binom{n}{3}=\\dfrac{n!}{3!\\,(n-3)!}=\\dfrac{n(n-1)(n-2)}{3!}$, avec $3!=6$.","$\\binom{ {{n}} }{3}=\\dfrac{ {{n}}\\times{{eval:n-1}}\\times{{eval:n-2}} }{6}=\\textcolor{{{color:primary.0}}}{{{eval:n*(n-1)*(n-2)/6}}}$."]}},{"blanks":[{"expectedAnswer":"{{f}}","acceptCombinatorialNotation":true}],"statement":"De combien de façons peut-on ranger ${{n}}$ livres différents sur une étagère ?\n\n$?$","variables":[{"name":"n","expression":"4..7"},{"name":"f","expression":"{{eval:factorial(n)}}"}],"correction":{"steps":["Un rangement est une permutation des ${{n}}$ livres : il y en a $n!$.","${{n}}!=\\textcolor{{{color:primary.0}}}{{{f}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:n*(n-1)*(n-2)}}","acceptCombinatorialNotation":true}],"statement":"${{n}}$ coureurs participent à une course. Combien de podiums (premier, deuxième, troisième) sont possibles ?\n\n$?$","variables":[{"name":"n","expression":"5..12"}],"correction":{"steps":["Un podium est un triplet **ordonné** de coureurs distincts : ${{n}}$ choix pour le premier, ${{eval:n-1}}$ pour le deuxième, ${{eval:n-2}}$ pour le troisième.","${{n}}\\times{{eval:n-1}}\\times{{eval:n-2}}=\\textcolor{{{color:primary.0}}}{{{eval:n*(n-1)*(n-2)}}}$ (et non $\\binom{ {{n}} }{3}$, qui compte les groupes de trois sans ordre)."]}}],"shared":null,"test_specs":[{"answers":["45"],"expected":{"status":"correct"},"variables":{"n":"10"},"description":"v0 : C(10, 2) = 45","variationIndex":0},{"answers":["90"],"expected":{"status":"incorrect"},"variables":{"n":"10"},"description":"v0 : n(n − 1) = 90","variationIndex":0},{"answers":["50"],"expected":{"status":"incorrect"},"variables":{"n":"10"},"description":"v0 : n²/2 = 50","variationIndex":0},{"answers":["56"],"expected":{"status":"correct"},"variables":{"n":"8"},"description":"v1 : C(8, 3) = 56","variationIndex":1},{"answers":["336"],"expected":{"status":"incorrect"},"variables":{"n":"8"},"description":"v1 : arrangements 336","variationIndex":1},{"answers":["120"],"expected":{"status":"correct"},"variables":{"n":"5"},"description":"v2 : 5! = 120","variationIndex":2},{"answers":["3125"],"expected":{"status":"incorrect"},"variables":{"n":"5"},"description":"v2 : 5⁵","variationIndex":2},{"answers":["336"],"expected":{"status":"correct"},"variables":{"n":"8"},"description":"v3 : 8 coureurs → 336","variationIndex":3},{"answers":["56"],"expected":{"status":"incorrect"},"variables":{"n":"8"},"description":"v3 : C(8, 3) = 56 (ordre oublié)","variationIndex":3},{"answers":["512"],"expected":{"status":"incorrect"},"variables":{"n":"8"},"description":"v3 : 8³ (répétitions)","variationIndex":3},{"answers":["5!"],"expected":{"status":"correct"},"variables":{"n":"5"},"description":"v2 : 5! (notation acceptée)","variationIndex":2},{"answers":["\\binom{10}{2}"],"expected":{"status":"bad_form","constraintViolations":["form"]},"variables":{"n":"10"},"description":"v0 : \\binom{10}{2} sans l’option (consigne « Calcule ») : calcul non effectué","variationIndex":0}]}$plsc$::jsonb,
