\infty|-\\infty}}, pas de forme indéterminée.","Par somme, $\\displaystyle\\lim_{x\\to+\\infty}f(x)=\\textcolor{{{color:primary.0}}}{{{if:a>0|+\\infty|-\\infty}}}$."]}},{"blanks":[{"expectedAnswer":"{{if:b>0|+\\infty|-\\infty}}"}],"statement":"Soit $f$ la fonction définie sur $\\left]0\\,;+\\infty\\right[$ par $f(x)={{a}}{{if:b>0|+|-}}\\dfrac{ {{eval:abs(b)}} }{x}$.\n\nDétermine la limite de $f$ en $0$ (on a $x>0$).\n\n$\\displaystyle\\lim_{x\\to0}f(x)=?$","variables":[{"name":"a","expression":"1..9;±"},{"name":"b","expression":"1..9;±"}],"correction":{"steps":["Quand $x$ tend vers $0$ avec $x>0$, $\\dfrac{1}{x}$ tend vers $+\\infty$ (inverse d'un nombre positif de plus en plus petit).","Donc ${{if:b>0|\\dfrac{ {{b}} }{x}|-\\dfrac{ {{eval:abs(b)}} }{x}}}$ tend vers {{if:b>0|$+\\infty$|$-\\infty$ (coefficient négatif)}}, et ${{a}}$ ne change rien : $\\displaystyle\\lim_{x\\to0}f(x)=\\textcolor{{{color:primary.0}}}{{{if:b>0|+\\infty|-\\infty}}}$."]}}],"shared":{"blankDefaults":{"acceptDecimal":true},"cleanCoefficients":true},"test_specs":[{"answers":["3"],"expected":{"status":"correct"},"variables":{"a":"3","b":"5"},"description":"v0 : 3 + 5/x² → 3","variationIndex":0},{"answers":["8"],"expected":{"status":"incorrect"},"variables":{"a":"3","b":"5"},"description":"v0 : a + b","variationIndex":0},{"answers":["+\\infty"],"expected":{"status":"incorrect"},"variables":{"a":"3","b":"5"},"description":"v0 : +∞","variationIndex":0},{"answers":["4"],"expected":{"status":"correct"},"variables":{"a":"-2","b":"4"},"description":"v1 : −2eˣ + 4 → 4","variationIndex":1},{"answers":["2"],"expected":{"status":"incorrect"},"variables":{"a":"-2","b":"4"},"description":"v1 : limite de eˣ prise égale à 1 (a + b)","variationIndex":1},{"answers":["-\\infty"],"expected":{"status":"incorrect"},"variables":{"a":"-2","b":"4"},"description":"v1 : −∞","variationIndex":1},{"answers":["+\\infty"],"expected":{"status":"correct"},"variables":{"a":"2","bb":"3"},"description":"v2 : 2x³ + 3√x → +∞","var