insert into _plsc_modeles values ('89e16891-1301-4b1c-af75-a8f03ba0dcdb', $plsc$Probabilités$plsc$, $plsc$Autres lois$plsc$, $plsc$loi uniforme continue$plsc$, array['T_COMP'],
  $plsc${"title":"Loi uniforme sur [a ; b] : probabilités et espérance","description":"X uniforme sur [a ; b] : P(c ⩽ X ⩽ d) = (d − c)/(b − a), P(X ⩾ c) = (b − c)/(b − a), E(X) = (a + b)/2, P(X = c) = 0 (pièges : (b − a)/2, longueur non divisée, 1/(b − a) pour P(X = c))","variations":[{"blanks":[{"expectedAnswer":"{{eval:(d-c)/(b-a)}}"}],"statement":"$X$ suit la loi uniforme sur $\\left[{{a}}\\,;{{b}}\\right]$.\n\nCalcule $P({{c}}\\leqslant X\\leqslant {{d}})$.\n\n$P({{c}}\\leqslant X\\leqslant {{d}})=?$","variables":[{"name":"a","expression":"0..5"},{"name":"L","expression":"5..20"},{"name":"b","expression":"{{eval:a+L}}"},{"name":"c","expression":"{{eval:a+1}}..{{eval:b-2}}"},{"name":"d","expression":"{{eval:c+1}}..{{eval:b-1}}"}],"correction":{"steps":["Pour la loi uniforme sur $[a\\,;b]$, la probabilité d'un intervalle $[c\\,;d]$ inclus dans $[a\\,;b]$ est $\\dfrac{d-c}{b-a}$ (longueur de l'intervalle sur longueur totale).","$P({{c}}\\leqslant X\\leqslant {{d}})=\\dfrac{ {{d}}-{{c}} }{ {{b}}-{{a}} }=\\textcolor{{{color:primary.0}}}{{{eval:(d-c)/(b-a)}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:(b-c)/(b-a)}}"}],"statement":"$X$ suit la loi uniforme sur $\\left[{{a}}\\,;{{b}}\\right]$.\n\nCalcule $P(X\\geqslant {{c}})$.\n\n$P(X\\geqslant {{c}})=?$","variables":[{"name":"a","expression":"0..5"},{"name":"L","expression":"5..20"},{"name":"b","expression":"{{eval:a+L}}"},{"name":"c","expression":"{{eval:a+1}}..{{eval:b-1}}"}],"conditions":["2*c != a + b"],"correction":{"steps":["$X\\geqslant {{c}}$ correspond à l'intervalle $\\left[{{c}}\\,;{{b}}\\right]$, de longueur ${{eval:b-c}}$.","$P(X\\geqslant {{c}})=\\dfrac{ {{b}}-{{c}} }{ {{b}}-{{a}} }=\\textcolor{{{color:primary.0}}}{{{eval:(b-c)/(b-a)}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:(a+b)/2}}"}],"statement":"Le temps d'attente $X$ d'un bus, en minutes, suit la loi uniforme sur $\\left[{{a}}\\,;{{b}}\\right]$.\n\nQuel est le temps d'attente moyen ?\n\n$E(X)=?$","variables":[{"name":"a","expression":"0..10"},{