insert into _plsc_modeles values ('91db0034-86d4-49bf-b190-0884db19e9b7', $plsc$Probabilités$plsc$, $plsc$Sommes et concentration$plsc$, $plsc$inégalité de concentration$plsc$, array['T_SPE'],
  $plsc${"title":"Inégalité de concentration : majorant et taille d'échantillon","description":"P(|Mₙ − μ| ⩾ δ) ⩽ V/(nδ²) : majorant pour n donné, plus petit n pour un risque α donné (pièges : V/(nδ), oubli de n, arrondi par défaut)","variations":[{"blanks":[{"expectedAnswer":"{{eval:v*d^2/n}}"}],"statement":"$M$ est la moyenne d'un échantillon de taille $n={{n}}$ d'une loi d'espérance $\\mu$ et de variance $V={{v}}$.\n\nDonne le majorant de $P\\left(\\left|M-\\mu\\right|\\geqslant {{eval:1/d;d}}\\right)$ fourni par l'inégalité de concentration (nombre décimal).\n\n$P\\left(\\left|M-\\mu\\right|\\geqslant {{eval:1/d;d}}\\right)\\leqslant ?$","variables":[{"name":"n","expression":"100|200|400|500|1000"},{"name":"v","expression":"1..10"},{"name":"d","expression":"2|4|5|10"}],"conditions":["v*d^2 < n"],"correction":{"steps":["Inégalité de concentration : $P\\left(\\left|M_n-\\mu\\right|\\geqslant\\delta\\right)\\leqslant\\dfrac{V}{n\\delta^{2}}$.","$\\dfrac{ {{v}} }{ {{n}}\\times{{eval:1/d;d}}^{2} }=\\dfrac{ {{v}} }{ {{eval:n/d^2;d}} }=\\textcolor{{{color:primary.0}}}{{{eval:v*d^2/n;d}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:-floor(-x)}}"}],"statement":"$M_n$ est la moyenne d'un échantillon de taille $n$ d'une loi d'espérance $\\mu$ et de variance $V={{v}}$.\n\nÀ l'aide de l'inégalité de concentration, détermine le plus petit entier $n$ qui garantit $P\\left(\\left|M_n-\\mu\\right|\\geqslant {{eval:1/d;d}}\\right)\\leqslant {{eval:a/100;d}}$.\n\n$n=?$","variables":[{"name":"v","expression":"1..9"},{"name":"d","expression":"2|4|5|10"},{"name":"a","expression":"3|4|5|10"},{"name":"x","expression":"{{eval:v*d^2*100/a}}"}],"correction":{"steps":["Il suffit que $\\dfrac{V}{n\\delta^{2}}\\leqslant\\alpha$, soit $n\\geqslant\\dfrac{V}{\\alpha\\delta^{2}}$.","$\\dfrac{ {{v}} }{ {{eval:a/100;d}}\\times{{eval:1/d;d}}^{2} }\\approx {{eval:round(100*x)/100;d}}$, donc le plus petit entier est $n=\\textcolor{{{color:primary.0}}}{{{eval:-floor(-x)}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:-floor(-x)}}"}],"statement":"On lance $n$ fois une pièce qui tombe sur pile avec la probabilité ${{eval:t/10;d}}$, et on note $F_n$ la fréquence de pile : c'est la moyenne d'un échantillon de la loi de Bernoulli de paramètre $p={{eval:t/10;d}}$.\n\nÀ l'aide de l'inégalité de concentration, détermine le plus petit entier $n$ qui garantit $P\\left(\\left|F_n-{{eval:t/10;d}}\\right|\\geqslant 0.1\\right)\\leqslant 0.05$.\n\n$n=?$","variables":[{"name":"t","expression":"1..9"},{"name":"x","expression":"{{eval:t*(10-t)*20}}"}],"correction":{"steps":["La variance de la loi de Bernoulli est $V=p(1-p)={{eval:t/10;d}}\\times{{eval:1-t/10;d}}={{eval:t*(10-t)/100;d}}$.","Il faut $\\dfrac{V}{n\\times 0.1^{2}}\\leqslant 0.05$, soit $n\\geqslant\\dfrac{ {{eval:t*(10-t)/100;d}} }{0.05\\times 0.01}={{eval:x}}$ : $n=\\textcolor{{{color:primary.0}}}{{{eval:x}}}$."]}}],"shared":{"blankDefaults":{"acceptDecimal":true}},"test_specs":[{"answers":["0,5"],"expected":{"status":"correct"},"variables":{"d":"10","n":"1000","v":"5"},"description":"v0 : V = 5, n = 1000, δ = 0,1 → 0,5","variationIndex":0},{"answers":["0,05"],"expected":{"status":"incorrect"},"variables":{"d":"10","n":"1000","v":"5"},"description":"v0 : V/(nδ) = 0,05","variationIndex":0},{"answers":["500"],"expected":{"status":"incorrect"},"variables":{"d":"10","n":"1000","v":"5"},"description":"v0 : n oublié : 500","variationIndex":0},{"answers":["240"],"expected":{"status":"correct"},"variables":{"a":"5","d":"2","v":"3"},"description":"v1 : V = 3, δ = 0,5, α = 0,05 → 240","variationIndex":1},{"answers":["480"],"expected":{"status":"correct"},"variables":{"a":"10","d":"4","v":"3"},"description":"v1 : V = 3, δ = 0,25, α = 0,1 → 480","variationIndex":1},{"answers":["134"],"expected":{"status":"correct"},"variables":{"a":"3","d":"2","v":"1"},"description":"v1 : V = 1, δ = 0,5, α = 0,03 → 133,3… → 134","variationIndex":1},{"answers":["133"],"expected":{"status":"incorrect"},"variables":{"a":"3","d":"2","v":"1"},"description":"v1 : arrondi par défaut 133","variationIndex":1},{"answers":["120"],"expected":{"status":"incorrect"},"variables":{"a":"5","d":"2","v":"3"},"description":"v1 : δ au lieu de δ² : 120","variationIndex":1},{"answers":["420"],"expected":{"status":"correct"},"variables":{"t":"3"},"description":"v2 : p = 0,3 → 420","variationIndex":2},{"answers":["500"],"expected":{"status":"correct"},"variables":{"t":"5"},"description":"v2 : p = 0,5 → 500","variationIndex":2},{"answers":["600"],"expected":{"status":"incorrect"},"variables":{"t":"3"},"description":"v2 : V = p au lieu de p(1 − p) : 600","variationIndex":2}]}$plsc$::jsonb,
  $plsc${"title":"Inégalité de concentration : taille d'échantillon","description":"P(|Mₙ − μ| ⩾ δ) ⩽ V/(nδ²) : plus petit n pour un risque donné (pièges : V/(nδ), arrondi par défaut)","variations":[{"blanks":[{"expectedAnswer":"{{eval:-floor(-x)}}"}],"statement":"$M_n$ est la moyenne d'un échantillon de taille $n$ d'une loi d'espérance $\\mu$ et de variance $V={{v}}$.\n\nÀ l'aide de l'inégalité de concentration, détermine le plus petit entier $n$ qui garantit $P\\left(\\left|M_n-\\mu\\right|\\geqslant {{eval:1/d;d}}\\right)\\leqslant {{eval:a/100;d}}$.\n\n$n=?$","variables":[{"name":"v","expression":"1..9"},{"name":"d","expression":"2|4|5|10"},{"name":"a","expression":"3|4|5|10"},{"name":"x","expression":"{{eval:v*d^2*100/a}}"}],"correction":{"steps":["Il suffit que $\\dfrac{V}{n\\delta^{2}}\\leqslant\\alpha$, soit $n\\geqslant\\dfrac{V}{\\alpha\\delta^{2}}$.","$\\dfrac{ {{v}} }{ {{eval:a/100;d}}\\times{{eval:1/d;d}}^{2} }\\approx {{eval:round(100*x)/100;d}}$, donc le plus petit entier est $n=\\textcolor{{{color:primary.0}}}{{{eval:-floor(-x)}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:-floor(-x)}}"}],"statement":"On lance $n$ fois une pièce qui tombe sur pile avec la probabilité ${{eval:t/10;d}}$, et on note $F_n$ la fréquence de pile : c'est la moyenne d'un échantillon de la loi de Bernoulli de paramètre $p={{eval:t/10;d}}$.\n\nÀ l'aide de l'inégalité de concentration, détermine le plus petit entier $n$ qui garantit $P\\left(\\left|F_n-{{eval:t/10;d}}\\right|\\geqslant 0.1\\right)\\leqslant 0.05$.\n\n$n=?$","variables":[{"name":"t","expression":"1..9"},{"name":"x","expression":"{{eval:t*(10-t)*20}}"}],"correction":{"steps":["La variance de la loi de Bernoulli est $V=p(1-p)={{eval:t/10;d}}\\times{{eval:1-t/10;d}}={{eval:t*(10-t)/100;d}}$.","Il faut $\\dfrac{V}{n\\times 0.1^{2}}\\leqslant 0.05$, soit $n\\geqslant\\dfrac{ {{eval:t*(10-t)/100;d}} }{0.05\\times 0.01}={{eval:x}}$ : $n=\\textcolor{{{color:primary.0}}}{{{eval:x}}}$."]}}],"shared":{"blankDefaults":{"acceptDecimal":true}},"test_specs":[{"answers":["240"],"expected":{"status":"correct"},"variables":{"a":"5","d":"2","v":"3"},"description":"v0 : V = 3, δ = 0,5, α = 0,05 → 240","variationIndex":0},{"answers":["480"],"expected":{"status":"correct"},"variables":{"a":"10","d":"4","v":"3"},"description":"v0 : V = 3, δ = 0,25, α = 0,1 → 480","variationIndex":0},{"answers":["134"],"expected":{"status":"correct"},"variables":{"a":"3","d":"2","v":"1"},"description":"v0 : V = 1, δ = 0,5, α = 0,03 → 133,3… → 134","variationIndex":0},{"answers":["133"],"expected":{"status":"incorrect"},"variables":{"a":"3","d":"2","v":"1"},"description":"v0 : arrondi par défaut 133","variationIndex":0},{"answers":["120"],"expected":{"status":"incorrect"},"variables":{"a":"5","d":"2","v":"3"},"description":"v0 : δ au lieu de δ² : 120","variationIndex":0},{"answers":["420"],"expected":{"status":"correct"},"variables":{"t":"3"},"description":"v1 : p = 0,3 → 420","variationIndex":1},{"answers":["500"],"expected":{"status":"correct"},"variables":{"t":"5"},"description":"v1 : p = 0,5 → 500","variationIndex":1},{"answers":["600"],"expected":{"status":"incorrect"},"variables":{"t":"3"},"description":"v1 : V = p au lieu de p(1 − p) : 600","variationIndex":1}]}$plsc$::jsonb,
  null, null, null);
insert into _plsc_modeles values ('95ee8348-8d34-4cf4-a798-544ee0622aa7', $plsc$Intégration$plsc$, $plsc$Fonction intégrale$plsc$, $plsc$dérivée d'une fonction intégrale$plsc$, array['T_SPE', 'T_COMP'],
  $plsc${"title":"Dérivée de x ↦ ∫ₐˣ f(t) dt","description":"F(x) = ∫ₐˣ g(t) dt est la primitive de g qui s'annule en a : F′ = g, F′(2) = g(2), sens de variation par le signe de g, F(a) = 0 (pièges : F′ = g′, F′(x) = g(x) − g(a), F(a) ≠ 0)","variations":[{"blanks":[{"expectedAnswer":"{{k}}e^{-x^{2}}"}],"statement":"Soit $F$ la fonction définie sur $\\mathbb{R}$ par\n\n$$F(x)=\\displaystyle\\int_{ {{a}} }^{x}{{k}}e^{-t^{2}}\\,\\mathrm{d}t.$$\n\nDétermine $F'(x)$ (on ne cherche pas à calculer l'intégrale).\n\n$F'(x)=?$","variables":[{"name":"a","expression":"-1..2"},{"name":"k","expression":"2..5"}],"correction":{"steps":["La fonction $t\\mapsto {{k}}e^{-t^{2}}$ est continue sur $\\mathbb{R}$. D'après le théorème fondamental, $F:x\\mapsto\\displaystyle\\int_{ {{a}} }^{x}{{k}}e^{-t^{2}}\\,\\mathrm{d}t$ est **la primitive** de cette fonction qui s'annule en ${{a}}$.","Sa dérivée est donc la fonction intégrée, écrite en $x$ : $F'(x)=\\textcolor{{{color:primary.0}}}{ {{k}}e^{-x^{2}} }$.","Attention : on ne dérive pas la fonction intégrée (ce serait $F''$), et on ne retranche pas sa valeur en ${{a}}$ : la borne ${{a}}$ fixe seulement la constante, $F({{a}})=0$."]}},{"blanks":[{"expectedAnswer":"{{eval:sqrt(4+c)}}"}],"statement":"Soit $F$ la fonction définie sur $\\mathbb{R}$ par\n\n$$F(x)=\\displaystyle\\int_{1}^{x}\\sqrt{t^{2}+{{c}}}\\,\\mathrm{d}t.$$\n\nCalcule $F'(2)$.\n\n$F'(2)=?$","variables":[{"name":"c","expression":"5|12|21|32"}],"correction":{"steps":["La fonction $g:t\\mapsto\\sqrt{t^{2}+{{c}}}$ est continue sur $\\mathbb{R}$, donc $F$ est dérivable et $F'(x)=g(x)=\\sqrt{x^{2}+{{c}}}$.","$F'(2)=\\sqrt{2^{2}+{{c}}}=\\sqrt{ {{eval:4+c}} }=\\textcolor{{{color:primary.0}}}{ {{eval:sqrt(4+c)}} }$.","Inutile (et ici impossible avec les fonctions du programme) de calculer l'intégrale : on ne calcule pas $F(2)$, ni $g(2)-g(1)$."]}},{"blanks":[{"answerKind":"intervalles","expectedAnswer":"{{if:s>0|[{{a}};+\\infty[|]-\\infty;{{a}}]}}","openableBounds":true}],"statement":"Soit $F$ la fonction définie sur $\\mathbb{R}$ par\n\n$$F(x)=\\displaystyle\\int_{0}^{x}{{if:s>0|(t{{eval:-a;+}})|({{a}}-t)}}e^{-t^{2}}\\,\\mathrm{d}t.$$\n\nDétermine le plus grand intervalle sur lequel $F$ est **croissante**.\n\n$I=?$","variables":[{"name":"s","expression":"-1|1"},{"name":"a","expression":"-3..3"}],"conditions":["a != 0"],"correction":{"steps":["$F$ est la primitive de $g:t\\mapsto {{if:s>0|(t{{eval:-a;+}})|({{a}}-t)}}e^{-t^{2}}$ qui s'annule en $0$ : $F'(x)=g(x)={{if:s>0|(x{{eval:-a;+}})|({{a}}-x)}}e^{-x^{2}}$.","Comme $e^{-x^{2}}>0$, $F'(x)$ a le signe de ${{if:s>0|x{{eval:-a;+}}|{{a}}-x}}$ : positif pour $x{{if:s>0|\\geqslant|\\leqslant}}{{a}}$.","$F$ est croissante sur $\\textcolor{{{color:primary.0}}}{ {{if:s>0|\\left[{{a}}\\,;+\\infty\\right[|\\left]-\\infty\\,;{{a}}\\right]}} }$. On lit le signe de la **fonction intégrée**, pas celui de $F$, et la borne $0$ de l'intégrale ne joue aucun rôle."]}},{"blanks":[{"expectedAnswer":"0"}],"statement":"Soit $F$ la fonction définie sur $\\mathbb{R}$ par\n\n$$F(x)=\\displaystyle\\int_{ {{a}} }^{x}\\left(t^{2}{{c;+}}\\right)\\mathrm{d}t.$$\n\nCalcule $F({{a}})$.\n\n$F({{a}})=?$","variables":[{"name":"a","expression":"-3..3"},{"name":"c","expression":"1..5;±"}],"conditions":["a != 0"],"correction":{"steps":["$F({{a}})=\\displaystyle\\int_{ {{a}} }^{ {{a}} }\\left(t^{2}{{c;+}}\\right)\\mathrm{d}t$ : les deux bornes sont égales, l'intégrale est nulle.","$F({{a}})=\\textcolor{{{color:primary.0}}}{0}$ : $F$ est la primitive de $t\\mapsto t^{2}{{c;+}}$ qui **s'annule** en ${{a}}$. (La valeur ${{eval:a^2+c}}$ est celle de la fonction intégrée en ${{a}}$, pas celle de $F$.)"]}}],"shared":{"cleanCoefficients":true},"test_specs":[{"answers":["3e^{-x^{2}}"],"expected":{"status":"correct"},"variables":{"a":"1","k":"3"},"description":"v0 : k=3 → 3e^{−x²}","variationIndex":0},{"answers":["-6xe^{-x^{2}}"],"expected":{"status":"incorrect"},"variables":{"a":"1","k":"3"},"description":"v0 : F′ = g′ (fonction intégrée dérivée)","variationIndex":0},{"answers":["3e^{-x^{2}}-3e^{-1}"],"expected":{"status":"incorrect"},"variables":{"a":"1","k":"3"},"description":"v0 : F′(x) = g(x) − g(a)","variationIndex":0},{"answers":["3e^{-t^{2}}"],"expected":{"status":"incorrect"},"variables":{"a":"1","k":"3"},"description":"v0 : réponse écrite en t","variationIndex":0},{"answers":["2e^{-x^2}"],"expected":{"status":"correct"},"variables":{"a":"0","k":"2"},"description":"v0 : a=0, k=2","variationIndex":0},{"answers":["3"],"expected":{"status":"correct"},"variables":{"c":"5"},"description":"v1 : c=5 → 3","variationIndex":1},{"answers":["\\sqrt{9}"],"expected":{"status":"unoptimal_form","constraintViolations":["reducedRadicals"]},"variables":{"c":"5"},"description":"v1 : √9 non simplifié","variationIndex":1},{"answers":["3-\\sqrt{6}"],"expected":{"status":"incorrect"},"variables":{"c":"5"},"description":"v1 : g(2) − g(1)","variationIndex":1},{"answers":["\\frac{2}{3}"],"expected":{"status":"incorrect"},"variables":{"c":"5"},"description":"v1 : F′ = g′ : g′(2) = 2/3","variationIndex":1},{"answers":["6"],"expected":{"status":"correct"},"variables":{"c":"32"},"description":"v1 : c=32 → 6","variationIndex":1},{"answers":["[2;+\\infty["],"expected":{"status":"correct"},"variables":{"a":"2","s":"1"},"description":"v2 : s=1, a=2 → [2;+∞[","variationIndex":2},{"answers":["]2;+\\infty["],"expected":{"status":"correct"},"variables":{"a":"2","s":"1"},"description":"v2 : borne ouverte acceptée","variationIndex":2},{"answers":["]-\\infty;2]"],"expected":{"status":"incorrect"},"variables":{"a":"2","s":"1"},"description":"v2 : intervalle de décroissance","variationIndex":2},{"answers":["[0;+\\infty["],"expected":{"status":"incorrect"},"variables":{"a":"2","s":"1"},"description":"v2 : part de la borne 0 de l'intégrale","variationIndex":2},{"answers":["]-\\infty;-1]"],"expected":{"status":"correct"},"variables":{"a":"-1","s":"-1"},"description":"v2 : s=−1, a=−1 → ]−∞;−1]","variationIndex":2},{"answers":["[-1;+\\infty["],"expected":{"status":"incorrect"},"variables":{"a":"-1","s":"-1"},"description":"v2 : s=−1, signe de t − a pris au lieu de a − t","variationIndex":2},{"answers":["0"],"expected":{"status":"correct"},"variables":{"a":"2","c":"3"},"description":"v3 : F(a) = 0","variationIndex":3},{"answers":["7"],"expected":{"status":"incorrect"},"variables":{"a":"2","c":"3"},"description":"v3 : F(a) ≠ 0 : g(a) donné","variationIndex":3},{"answers":["\\frac{26}{3}"],"expected":{"status":"incorrect"},"variables":{"a":"2","c":"3"},"description":"v3 : primitive en a (a³/3 + ca)","variationIndex":3},{"answers":["2"],"expected":{"status":"incorrect"},"variables":{"a":"2","c":"3"},"description":"v3 : borne donnée","variationIndex":3}]}$plsc$::jsonb,
  $plsc${"title":"Dérivée de x ↦ ∫ₐˣ f(t) dt","description":"F(x) = ∫ₐˣ g(t) dt est la primitive de g qui s'annule en a : F′ = g, F′(2) = g(2) (pièges : F′ = g′, F′(x) = g(x) − g(a))","variations":[{"blanks":[{"expectedAnswer":"{{k}}e^{-x^{2}}"}],"statement":"Soit $F$ la fonction définie sur $\\mathbb{R}$ par\n\n$$F(x)=\\displaystyle\\int_{ {{a}} }^{x}{{k}}e^{-t^{2}}\\,\\mathrm{d}t.$$\n\nDétermine $F'(x)$ (on ne cherche pas à calculer l'intégrale).\n\n$F'(x)=?$","variables":[{"name":"a","expression":"-1..2"},{"name":"k","expression":"2..5"}],"correction":{"steps":["La fonction $t\\mapsto {{k}}e^{-t^{2}}$ est continue sur $\\mathbb{R}$. D'après le théorème fondamental, $F:x\\mapsto\\displaystyle\\int_{ {{a}} }^{x}{{k}}e^{-t^{2}}\\,\\mathrm{d}t$ est **la primitive** de cette fonction qui s'annule en ${{a}}$.","Sa dérivée est donc la fonction intégrée, écrite en $x$ : $F'(x)=\\textcolor{{{color:primary.0}}}{ {{k}}e^{-x^{2}} }$.","Attention : on ne dérive pas la fonction intégrée (ce serait $F''$), et on ne retranche pas sa valeur en ${{a}}$ : la borne ${{a}}$ fixe seulement la constante, $F({{a}})=0$."]}},{"blanks":[{"expectedAnswer":"\\frac{1}{ {{eval:4+c}} }"}],"statement":"Soit $F$ la fonction définie sur $\\mathbb{R}$ par\n\n$$F(x)=\\displaystyle\\int_{1}^{x}\\dfrac{1}{t^{2}+{{c}}}\\,\\mathrm{d}t.$$\n\nCalcule $F'(2)$.\n\n$F'(2)=?$","variables":[{"name":"c","expression":"5|12|21|32"}],"correction":{"steps":["La fonction $g:t\\mapsto\\dfrac{1}{t^{2}+{{c}}}$ est continue sur $\\mathbb{R}$ (son dénominateur ne s'annule pas), donc $F$ est dérivable et $F'(x)=g(x)=\\dfrac{1}{x^{2}+{{c}}}$.","$F'(2)=\\dfrac{1}{2^{2}+{{c}}}=\\textcolor{{{color:primary.0}}}{\\dfrac{1}{ {{eval:4+c}} }}$.","Inutile (et ici impossible avec les fonctions du programme) de calculer l'intégrale : on ne calcule pas $F(2)$, ni $g(2)-g(1)$."]}}],"shared":{"cleanCoefficients":true},"test_specs":[{"answers":["3e^{-x^{2}}"],"expected":{"status":"correct"},"variables":{"a":"1","k":"3"},"description":"v0 : k=3 → 3e^{−x²}","variationIndex":0},{"answers":["-6xe^{-x^{2}}"],"expected":{"status":"incorrect"},"variables":{"a":"1","k":"3"},"description":"v0 : F′ = g′ (fonction intégrée dérivée)","variationIndex":0},{"answers":["3e^{-x^{2}}-3e^{-1}"],"expected":{"status":"incorrect"},"variables":{"a":"1","k":"3"},"description":"v0 : F′(x) = g(x) − g(a)","variationIndex":0},{"answers":["3e^{-t^{2}}"],"expected":{"status":"incorrect"},"variables":{"a":"1","k":"3"},"description":"v0 : réponse écrite en t","variationIndex":0},{"answers":["2e^{-x^2}"],"expected":{"status":"correct"},"variables":{"a":"0","k":"2"},"description":"v0 : a=0, k=2","variationIndex":0},{"answers":["\\frac{1}{9}"],"expected":{"status":"correct"},"variables":{"c":"5"},"description":"v1 : c=5 → 1/9","variationIndex":1},{"answers":["\\frac{2}{18}"],"expected":{"status":"unoptimal_form","constraintViolations":["reducedFractions"]},"variables":{"c":"5"},"description":"v1 : 2/18 non simplifié","variationIndex":1},{"answers":["-\\frac{1}{18}"],"expected":{"status":"incorrect"},"variables":{"c":"5"},"description":"v1 : g(2) − g(1)","variationIndex":1},{"answers":["-\\frac{4}{81}"],"expected":{"status":"incorrect"},"variables":{"c":"5"},"description":"v1 : F′ = g′ : g′(2) = −4/81","variationIndex":1},{"answers":["\\frac{1}{36}"],"expected":{"status":"correct"},"variables":{"c":"32"},"description":"v1 : c=32 → 1/36","variationIndex":1}]}$plsc$::jsonb,
  null, null, null);
insert into _plsc_modeles values ('95f04c3e-03e1-4db4-a16e-36b713a2273f', $plsc$Géométrie$plsc$, $plsc$Orthogonalité et distances dans l'espace$plsc$, $plsc$projeté orthogonal$plsc$, array['T_SPE'],
  $plsc${"title":"Espace : projeté orthogonal sur un plan, distance à un plan","description":"Coordonnées du projeté orthogonal H d'un point sur un plan d'équation donnée, et distance MH (pièges : M recopié, symétrique, MH², racine non simplifiée)","variations":[{"blanks":[{"expectedAnswer":"{{hx}}"},{"expectedAnswer":"{{hy}}"},{"expectedAnswer":"{{hz}}"}],"statement":"Dans l'espace muni d'un repère orthonormé, on considère le plan $\\mathcal{P}$ d'équation ${{a}}x+({{b}})y+({{c}})z+({{d}})=0$ et le point $M({{mx}}\\,;\\,{{my}}\\,;\\,{{mz}})$.\n\nDétermine les coordonnées du projeté orthogonal $H$ de $M$ sur $\\mathcal{P}$.\n\n$H(?\\,;\\,?\\,;\\,?)$","variables":[{"name":"a","expression":"1..3;±"},{"name":"b","expression":"-3..3"},{"name":"c","expression":"1..3;±"},{"name":"hx","expression":"-4..4"},{"name":"hy","expression":"-4..4"},{"name":"hz","expression":"-4..4"},{"name":"k","expression":"1..2;±"},{"name":"d","expression":"{{eval:-(a*hx+b*hy+c*hz)}}"},{"name":"mx","expression":"{{eval:hx+k*a}}"},{"name":"my","expression":"{{eval:hy+k*b}}"},{"name":"mz","expression":"{{eval:hz+k*c}}"},{"name":"mk","expression":"{{eval:-k}}"}],"correction":{"steps":["Le projeté $H$ est le point d'intersection de $\\mathcal{P}$ et de la droite passant par $M$ de vecteur directeur $\\vec{n}\\begin{pmatrix}{{a}}\\\\{{b}}\\\\{{c}}\\end{pmatrix}$ : $H({{if:mx!=0|{{mx}}}}{{if:a==1|{{if:mx!=0|+}}t}}{{if:a==-1|-t}}{{if:a>1|{{if:mx!=0|+}}{{a}}t}}{{if:a< -1|{{a}}t}}{{if:a==0|{{if:mx==0|0}}}}\\,;\\,{{if:my!=0|{{my}}}}{{if:b==1|{{if:my!=0|+}}t}}{{if:b==-1|-t}}{{if:b>1|{{if:my!=0|+}}{{b}}t}}{{if:b< -1|{{b}}t}}{{if:b==0|{{if:my==0|0}}}}\\,;\\,{{if:mz!=0|{{mz}}}}{{if:c==1|{{if:mz!=0|+}}t}}{{if:c==-1|-t}}{{if:c>1|{{if:mz!=0|+}}{{c}}t}}{{if:c< -1|{{c}}t}}{{if:c==0|{{if:mz==0|0}}}})$ pour un réel $t$.","En reportant dans l'équation de $\\mathcal{P}$ : ${{eval:a^2+b^2+c^2}}t{{eval:a*mx+b*my+c*mz+d;+}}=0$, donc $t={{mk}}$.","Donc $\\textcolor{{{color:primary.0}}}{ H({{hx}}\\,;\\,{{hy}}\\,;\\,{{hz}}) }$."]}},{"blanks":[{"expectedAnswer":"{{eval:abs(k)*sqrt(a^2+b^2+c^2)}}"}],"statement":"Dans l'espace muni d'un repère orthonormé, on considère le plan $\\mathcal{P}$ d'équation ${{a}}x+({{b}})y+({{c}})z+({{d}})=0$ et le point $M({{mx}}\\,;\\,{{my}}\\,;\\,{{mz}})$.\n\nCalcule la distance du point $M$ au plan $\\mathcal{P}$ (valeur exacte), c'est-à-dire la distance $MH$ où $H$ est le projeté orthogonal de $M$ sur $\\mathcal{P}$.\n\n$MH=?$","variables":[{"name":"a","expression":"1..3;±"},{"name":"b","expression":"-3..3"},{"name":"c","expression":"1..3;±"},{"name":"hx","expression":"-4..4"},{"name":"hy","expression":"-4..4"},{"name":"hz","expression":"-4..4"},{"name":"k","expression":"1..2;±"},{"name":"d","expression":"{{eval:-(a*hx+b*hy+c*hz)}}"},{"name":"mx","expression":"{{eval:hx+k*a}}"},{"name":"my","expression":"{{eval:hy+k*b}}"},{"name":"mz","expression":"{{eval:hz+k*c}}"},{"name":"mk","expression":"{{eval:-k}}"}],"correction":{"steps":["Le projeté $H$ est le point d'intersection de $\\mathcal{P}$ et de la droite passant par $M$ de vecteur directeur $\\vec{n}\\begin{pmatrix}{{a}}\\\\{{b}}\\\\{{c}}\\end{pmatrix}$ : $H({{if:mx!=0|{{mx}}}}{{if:a==1|{{if:mx!=0|+}}t}}{{if:a==-1|-t}}{{if:a>1|{{if:mx!=0|+}}{{a}}t}}{{if:a< -1|{{a}}t}}{{if:a==0|{{if:mx==0|0}}}}\\,;\\,{{if:my!=0|{{my}}}}{{if:b==1|{{if:my!=0|+}}t}}{{if:b==-1|-t}}{{if:b>1|{{if:my!=0|+}}{{b}}t}}{{if:b< -1|{{b}}t}}{{if:b==0|{{if:my==0|0}}}}\\,;\\,{{if:mz!=0|{{mz}}}}{{if:c==1|{{if:mz!=0|+}}t}}{{if:c==-1|-t}}{{if:c>1|{{if:mz!=0|+}}{{c}}t}}{{if:c< -1|{{c}}t}}{{if:c==0|{{if:mz==0|0}}}})$ pour un réel $t$.","En reportant dans l'équation de $\\mathcal{P}$ : ${{eval:a^2+b^2+c^2}}t{{eval:a*mx+b*my+c*mz+d;+}}=0$, donc $t={{mk}}$.","$H({{hx}}\\,;\\,{{hy}}\\,;\\,{{hz}})$ et $\\overrightarrow{MH}=t\\,\\vec{n}$ avec $t={{mk}}$, donc $MH=|t|\\times\\|\\vec{n}\\|={{eval:abs(k)}}\\times\\sqrt{{{eval:a^2+b^2+c^2}}}=\\textcolor{{{color:primary.0}}}{ {{eval:abs(k)*sqrt(a^2+b^2+c^2)}} }$."]}},{"blanks":[{"expectedAnswer":"{{mx}}"},{"expectedAnswer":"{{my}}"},{"expectedAnswer":"{{h}}"}],"statement":"Dans l'espace muni d'un repère orthonormé, on considère le point $M({{mx}}\\,;\\,{{my}}\\,;\\,{{mz}})$ et le plan $\\mathcal{P}$ d'équation $z={{h}}$.\n\nDétermine les coordonnées du projeté orthogonal $H$ de $M$ sur $\\mathcal{P}$.\n\n$H(?\\,;\\,?\\,;\\,?)$","variables":[{"name":"mx","expression":"-5..5"},{"name":"my","expression":"-5..5"},{"name":"mz","expression":"-5..5"},{"name":"h","expression":"-4..4"}],"conditions":["mz != h"],"correction":{"steps":["$\\vec{k}\\begin{pmatrix}0\\\\0\\\\1\\end{pmatrix}$ est normal au plan d'équation $z={{h}}$ : $H$ a les mêmes abscisse et ordonnée que $M$, et sa cote vaut ${{h}}$.","$\\textcolor{{{color:primary.0}}}{ H({{mx}}\\,;\\,{{my}}\\,;\\,{{h}}) }$"]}}],"shared":{"cleanCoefficients":true},"test_specs":[{"answers":["1","0","2"],"expected":{"status":"correct"},"variables":{"a":"1","b":"2","c":"-1","k":"1","hx":"1","hy":"0","hz":"2"},"description":"v0 : H(1 ; 0 ; 2)","variationIndex":0},{"answers":["2","2","1"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"2","c":"-1","k":"1","hx":"1","hy":"0","hz":"2"},"description":"v0 : M recopié","variationIndex":0},{"answers":["0","-2","3"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"2","c":"-1","k":"1","hx":"1","hy":"0","hz":"2"},"description":"v0 : symétrique de M (t doublé)","variationIndex":0},{"answers":["2\\sqrt{6}"],"expected":{"status":"correct"},"variables":{"a":"1","b":"2","c":"-1","k":"-2","hx":"1","hy":"0","hz":"2"},"description":"v1 : 2√6","variationIndex":1},{"answers":["\\sqrt{24}"],"expected":{"status":"unoptimal_form","constraintViolations":["reducedRadicals"]},"variables":{"a":"1","b":"2","c":"-1","k":"-2","hx":"1","hy":"0","hz":"2"},"description":"v1 : √24 non simplifiée","variationIndex":1},{"answers":["24"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"2","c":"-1","k":"-2","hx":"1","hy":"0","hz":"2"},"description":"v1 : MH² (24)","variationIndex":1},{"answers":["2"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"2","c":"-1","k":"-2","hx":"1","hy":"0","hz":"2"},"description":"v1 : |t| seul (2)","variationIndex":1},{"answers":["2","-3","1"],"expected":{"status":"correct"},"variables":{"h":"1","mx":"2","my":"-3","mz":"4"},"description":"v2 : H(2 ; -3 ; 1)","variationIndex":2},{"answers":["2","-3","0"],"expected":{"status":"incorrect"},"variables":{"h":"1","mx":"2","my":"-3","mz":"4"},"description":"v2 : projeté sur (Oxy) (cote 0)","variationIndex":2}]}$plsc$::jsonb,
