insert into _plsc_modeles values ('9ad36217-5f60-45c7-83ce-a1a870adc5da', $plsc$Fonctions$plsc$, $plsc$Logarithmes$plsc$, $plsc$courbe$plsc$, array['T_SPE', 'T_COMP'],
  $plsc${"title":"Courbes de ln et exp : reconnaître, symétrie par rapport à y = x","description":"Reconnaître la courbe de ln parmi quatre, symétrie des courbes de exp et ln par rapport à y = x, point symétrique (pièges : courbe de exp, −ln x, ln(x+1), mauvaise symétrie)","variations":[{"choices":[{"content":"```courbe\nx: -2 ; 5\ny: -3 ; 4\ngrille: 1 ; 1\nf(x) = ln(x)   bleu\ntaille: petite\ndescription: Courbe croissante définie pour x > 0, qui passe par (1 ; 0) et plonge vers le bas près de l'axe des ordonnées.\n```"},{"content":"```courbe\nx: -2 ; 5\ny: -3 ; 4\ngrille: 1 ; 1\nf(x) = exp(x)   bleu\ntaille: petite\ndescription: Courbe croissante définie sur tout l'axe, qui passe par (0 ; 1) et reste au-dessus de l'axe des abscisses.\n```"},{"content":"```courbe\nx: -2 ; 5\ny: -3 ; 4\ngrille: 1 ; 1\nf(x) = -ln(x)   bleu\ntaille: petite\ndescription: Courbe décroissante définie pour x > 0, qui passe par (1 ; 0) et monte près de l'axe des ordonnées.\n```"},{"content":"```courbe\nx: -2 ; 5\ny: -3 ; 4\ngrille: 1 ; 1\nf(x) = ln(x+1)   bleu\ntaille: petite\ndescription: Courbe croissante définie pour x > -1, qui passe par l'origine (0 ; 0).\n```"}],"statement":"Laquelle de ces courbes représente la fonction $\\ln$ ?","variables":[{"name":"z","expression":"1"}],"correction":{"steps":["La courbe de $\\ln$ passe par le point $(1\\,;0)$ ($\\ln 1=0$) et par $(e\\,;1)$.","Elle n'existe que pour $x>0$, monte (fonction croissante) et a l'axe des ordonnées pour asymptote : $\\displaystyle\\lim_{x\\to0}\\ln x=-\\infty$.","C'est la courbe \\textcolor{{{color:primary.0}}}{\\text{croissante passant par }(1\\,;0)}."]},"correctChoiceIndex":["0"]},{"choices":[{"content":"La symétrie par rapport à la droite d'équation $y=x$."},{"content":"La symétrie par rapport à l'axe des ordonnées."},{"content":"La symétrie par rapport à l'axe des abscisses."},{"content":"La symétrie par rapport à l'origine du repère."}],"statement":"On a tracé les courbes des fonctions $\\exp$ et $\\ln$ dans un repère orthonormé.\n\n```courbe\nx: -3 ; 5\ny: -3 ; 5\ngrille: 1 ; 1\nf(x) = exp(x)   bleu   nom=C_{exp}\ng(x) = ln(x)   rouge   nom=C_{ln}\nh(x) = x   gris pointillé\ntaille: moyenne\ndescription: Courbe de l'exponentielle (bleue) et du logarithme (rouge), symétriques par rapport à la droite y = x tracée en pointillés.\n```\n\nPar quelle transformation passe-t-on de la courbe de $\\exp$ à celle de $\\ln$ ?","variables":[{"name":"z","expression":"1"}],"correction":{"steps":["$\\ln$ est la fonction réciproque de $\\exp$ : le point $(a\\,;b)$ est sur la courbe de $\\exp$ si et seulement si $(b\\,;a)$ est sur celle de $\\ln$.","Échanger abscisse et ordonnée, c'est la \\textcolor{{{color:primary.0}}}{\\text{symétrie par rapport à la droite d'équation }y=x}."]},"correctChoiceIndex":["0"]},{"choices":[{"content":"$\\left(e^{ {{a}} }\\,;{{a}}\\right)$"},{"content":"$\\left(-{{a}}\\,;e^{ {{a}} }\\right)$"},{"content":"$\\left({{a}}\\,;-e^{ {{a}} }\\right)$"},{"content":"$\\left(e^{-{{a}}}\\,;{{a}}\\right)$"}],"statement":"Le point $A\\left({{a}}\\,;e^{ {{a}} }\\right)$ appartient à la courbe de la fonction $\\exp$.\n\nQuel point appartient à la courbe de la fonction $\\ln$ ?","variables":[{"name":"a","expression":"2..4"}],"correction":{"steps":["$\\ln\\left(e^{ {{a}} }\\right)={{a}}$ : le point d'abscisse $e^{ {{a}} }$ de la courbe de $\\ln$ a pour ordonnée ${{a}}$.","C'est le symétrique de $A$ par rapport à la droite $y=x$ : $\\textcolor{{{color:primary.0}}}{\\left(e^{ {{a}} }\\,;{{a}}\\right)}$."]},"correctChoiceIndex":["0"]}],"shared":null,"test_specs":[{"expected":{"status":"correct"},"variables":{"z":"1"},"description":"v0 : courbe de ln","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"z":"1"},"description":"v0 : courbe de exp","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"z":"1"},"description":"v0 : −ln x","variationIndex":0,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{"z":"1"},"description":"v0 : ln(x+1)","variationIndex":0,"selectedChoices":[3]},{"expected":{"status":"correct"},"variables":{"z":"1"},"description":"v1 : y = x","variationIndex":1,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"z":"1"},"description":"v1 : axe des ordonnées","variationIndex":1,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"z":"1"},"description":"v1 : axe des abscisses","variationIndex":1,"selectedChoices":[2]},{"expected":{"status":"correct"},"variables":{"a":"2"},"description":"v2 : (e^a ; a)","variationIndex":2,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"a":"2"},"description":"v2 : symétrique par rapport à l'axe des ordonnées","variationIndex":2,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"3"},"description":"v2 : e^{−a} (ln(1/x) confondu)","variationIndex":2,"selectedChoices":[3]}]}$plsc$::jsonb,
  $plsc${"title":"Courbes de ln et exp : symétrie par rapport à y = x","description":"Symétrie des courbes de exp et ln par rapport à y = x, point symétrique (piège : mauvaise symétrie)","variations":[{"choices":[{"content":"La symétrie par rapport à la droite d'équation $y=x$."},{"content":"La symétrie par rapport à l'axe des ordonnées."},{"content":"La symétrie par rapport à l'axe des abscisses."},{"content":"La symétrie par rapport à l'origine du repère."}],"statement":"On a tracé les courbes des fonctions $\\exp$ et $\\ln$ dans un repère orthonormé.\n\n```courbe\nx: -3 ; 5\ny: -3 ; 5\ngrille: 1 ; 1\nf(x) = exp(x)   bleu   nom=C_{exp}\ng(x) = ln(x)   rouge   nom=C_{ln}\nh(x) = x   gris pointillé\ntaille: moyenne\ndescription: Courbe de l'exponentielle (bleue) et du logarithme (rouge), symétriques par rapport à la droite y = x tracée en pointillés.\n```\n\nPar quelle transformation passe-t-on de la courbe de $\\exp$ à celle de $\\ln$ ?","variables":[{"name":"z","expression":"1"}],"correction":{"steps":["$\\ln$ est la fonction réciproque de $\\exp$ : le point $(a\\,;b)$ est sur la courbe de $\\exp$ si et seulement si $(b\\,;a)$ est sur celle de $\\ln$.","Échanger abscisse et ordonnée, c'est la \\textcolor{{{color:primary.0}}}{\\text{symétrie par rapport à la droite d'équation }y=x}."]},"correctChoiceIndex":["0"]},{"choices":[{"content":"$\\left(e^{ {{a}} }\\,;{{a}}\\right)$"},{"content":"$\\left(-{{a}}\\,;e^{ {{a}} }\\right)$"},{"content":"$\\left({{a}}\\,;-e^{ {{a}} }\\right)$"},{"content":"$\\left(e^{-{{a}}}\\,;{{a}}\\right)$"}],"statement":"Le point $A\\left({{a}}\\,;e^{ {{a}} }\\right)$ appartient à la courbe de la fonction $\\exp$.\n\nQuel point appartient à la courbe de la fonction $\\ln$ ?","variables":[{"name":"a","expression":"2..4"}],"correction":{"steps":["$\\ln\\left(e^{ {{a}} }\\right)={{a}}$ : le point d'abscisse $e^{ {{a}} }$ de la courbe de $\\ln$ a pour ordonnée ${{a}}$.","C'est le symétrique de $A$ par rapport à la droite $y=x$ : $\\textcolor{{{color:primary.0}}}{\\left(e^{ {{a}} }\\,;{{a}}\\right)}$."]},"correctChoiceIndex":["0"]}],"shared":null,"test_specs":[{"expected":{"status":"correct"},"variables":{"z":"1"},"description":"v0 : y = x","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"z":"1"},"description":"v0 : axe des ordonnées","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"z":"1"},"description":"v0 : axe des abscisses","variationIndex":0,"selectedChoices":[2]},{"expected":{"status":"correct"},"variables":{"a":"2"},"description":"v1 : (e^a ; a)","variationIndex":1,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"a":"2"},"description":"v1 : symétrique par rapport à l'axe des ordonnées","variationIndex":1,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"3"},"description":"v1 : e^{−a} (ln(1/x) confondu)","variationIndex":1,"selectedChoices":[3]}]}$plsc$::jsonb,
