insert into _plsc_modeles values ('aced2e6c-0f00-49ac-bcde-821d2bc91e9b', $plsc$Probabilités$plsc$, $plsc$Sommes et concentration$plsc$, $plsc$échantillons$plsc$, array['T_SPE'],
  $plsc${"title":"Échantillon de taille n : espérance et variance de Sₙ et Mₙ","description":"Pour un échantillon (X₁, …, Xₙ) d'espérance μ et de variance V : E(Sₙ) = nμ, V(Sₙ) = nV, E(Mₙ) = μ, V(Mₙ) = V/n, σ(Mₙ) = σ/√n (pièges : V/n² ou n²V, σ/n)","variations":[{"blanks":[{"expectedAnswer":"{{eval:n*m/10}}"}],"statement":"$(X_1, \\ldots, X_{ {{n}} })$ est un échantillon de taille ${{n}}$ d'une loi d'espérance $\\mu={{eval:m/10;d}}$. On pose $S=X_1+\\cdots+X_{ {{n}} }$.\n\nCalcule $E(S)$.\n\n$E(S)=?$","variables":[{"name":"n","expression":"10|20|25|50|100"},{"name":"m","expression":"5..80"}],"correction":{"steps":["Par linéarité, $E(S)=E(X_1)+\\cdots+E(X_{ {{n}} })=n\\mu$.","$E(S)={{n}}\\times{{eval:m/10;d}}=\\textcolor{{{color:primary.0}}}{{{eval:n*m/10;d}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:n*v}}"}],"statement":"$(X_1, \\ldots, X_{ {{n}} })$ est un échantillon de taille ${{n}}$ d'une loi de variance $V={{v}}$. On pose $S=X_1+\\cdots+X_{ {{n}} }$.\n\nCalcule $V(S)$.\n\n$V(S)=?$","variables":[{"name":"n","expression":"5..30"},{"name":"v","expression":"2..9"}],"correction":{"steps":["Les $X_i$ sont **indépendantes** : les variances s'ajoutent, $V(S)=nV$.","$V(S)={{n}}\\times{{v}}=\\textcolor{{{color:primary.0}}}{{{eval:n*v}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:v/n}}"}],"statement":"$(X_1, \\ldots, X_{ {{n}} })$ est un échantillon de taille ${{n}}$ d'une loi de variance $V={{v}}$. On note $M=\\dfrac{X_1+\\cdots+X_{ {{n}} }}{ {{n}} }$ la moyenne de l'échantillon.\n\nCalcule $V(M)$.\n\n$V(M)=?$","variables":[{"name":"n","expression":"10|20|25|40|50|100"},{"name":"v","expression":"2..12"}],"correction":{"steps":["$V(M)=V\\left(\\dfrac{S}{n}\\right)=\\dfrac{1}{n^{2}}V(S)=\\dfrac{nV}{n^{2}}=\\dfrac{V}{n}$.","$V(M)=\\dfrac{ {{v}} }{ {{n}} }=\\textcolor{{{color:primary.0}}}{{{eval:v/n}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:s/sqrt(n)}}"}],"statement":"$(X_1, \\ldots, X_{ {{n}} })$ est un échantillon de taille ${{n}}$ d'une loi d'écart type $\\sigma={{s}}$. On note $M$ la moyenne de l'échantillon.\n\nCalcule l'écart type $\\sigma(M)$.\n\n$\\sigma(M)=?$","variables":[{"name":"n","expression":"4|9|16|25|36|49|64|100"},{"name":"s","expression":"1..12"}],"correction":{"steps":["$V(M)=\\dfrac{\\sigma^{2}}{n}$, donc $\\sigma(M)=\\dfrac{\\sigma}{\\sqrt{n}}$.","$\\sigma(M)=\\dfrac{ {{s}} }{\\sqrt{ {{n}} }}=\\dfrac{ {{s}} }{ {{eval:sqrt(n)}} }=\\textcolor{{{color:primary.0}}}{{{eval:s/sqrt(n)}}}$."]}}],"shared":{"blankDefaults":{"acceptDecimal":true}},"test_specs":[{"answers":["70"],"expected":{"status":"correct"},"variables":{"m":"35","n":"20"},"description":"v0 : n = 20, μ = 3,5 → 70","variationIndex":0},{"answers":["3,5"],"expected":{"status":"incorrect"},"variables":{"m":"35","n":"20"},"description":"v0 : μ seul","variationIndex":0},{"answers":["40"],"expected":{"status":"correct"},"variables":{"n":"10","v":"4"},"description":"v1 : n = 10, V = 4 → 40","variationIndex":1},{"answers":["400"],"expected":{"status":"incorrect"},"variables":{"n":"10","v":"4"},"description":"v1 : n²V = 400","variationIndex":1},{"answers":["\\frac{3}{10}"],"expected":{"status":"correct"},"variables":{"n":"20","v":"6"},"description":"v2 : V = 6, n = 20 → 3/10","variationIndex":2},{"answers":["0,3"],"expected":{"status":"correct"},"variables":{"n":"20","v":"6"},"description":"v2 : 0,3 accepté","variationIndex":2},{"answers":["0,015"],"expected":{"status":"incorrect"},"variables":{"n":"20","v":"6"},"description":"v2 : V/n² = 0,015","variationIndex":2},{"answers":["\\frac{3}{2}"],"expected":{"status":"correct"},"variables":{"n":"16","s":"6"},"description":"v3 : σ = 6, n = 16 → 3/2","variationIndex":3},{"answers":["\\frac{3}{8}"],"expected":{"status":"incorrect"},"variables":{"n":"16","s":"6"},"description":"v3 : σ/n = 3/8","variationIndex":3},{"answers":["\\frac{9}{4}"],"expected":{"status":"incorrect"},"variables":{"n":"16","s":"6"},"description":"v3 : variance 9/4","variationIndex":3}]}$plsc$::jsonb,
  $plsc${"title":"Échantillon de taille n : variance et écart type de Sₙ et Mₙ","description":"V(Sₙ) = nV, V(Mₙ) = V/n, σ(Mₙ) = σ/√n (pièges : V/n² ou n²V, σ/n)","variations":[{"blanks":[{"expectedAnswer":"{{eval:n*v}}"}],"statement":"$(X_1, \\ldots, X_{ {{n}} })$ est un échantillon de taille ${{n}}$ d'une loi de variance $V={{v}}$. On pose $S=X_1+\\cdots+X_{ {{n}} }$.\n\nCalcule $V(S)$.\n\n$V(S)=?$","variables":[{"name":"n","expression":"5..30"},{"name":"v","expression":"2..9"}],"correction":{"steps":["Les $X_i$ sont **indépendantes** : les variances s'ajoutent, $V(S)=nV$.","$V(S)={{n}}\\times{{v}}=\\textcolor{{{color:primary.0}}}{{{eval:n*v}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:v/n}}"}],"statement":"$(X_1, \\ldots, X_{ {{n}} })$ est un échantillon de taille ${{n}}$ d'une loi de variance $V={{v}}$. On note $M=\\dfrac{X_1+\\cdots+X_{ {{n}} }}{ {{n}} }$ la moyenne de l'échantillon.\n\nCalcule $V(M)$.\n\n$V(M)=?$","variables":[{"name":"n","expression":"10|20|25|40|50|100"},{"name":"v","expression":"2..12"}],"correction":{"steps":["$V(M)=V\\left(\\dfrac{S}{n}\\right)=\\dfrac{1}{n^{2}}V(S)=\\dfrac{nV}{n^{2}}=\\dfrac{V}{n}$.","$V(M)=\\dfrac{ {{v}} }{ {{n}} }=\\textcolor{{{color:primary.0}}}{{{eval:v/n}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:s/sqrt(n)}}"}],"statement":"$(X_1, \\ldots, X_{ {{n}} })$ est un échantillon de taille ${{n}}$ d'une loi d'écart type $\\sigma={{s}}$. On note $M$ la moyenne de l'échantillon.\n\nCalcule l'écart type $\\sigma(M)$.\n\n$\\sigma(M)=?$","variables":[{"name":"n","expression":"4|9|16|25|36|49|64|100"},{"name":"s","expression":"1..12"}],"correction":{"steps":["$V(M)=\\dfrac{\\sigma^{2}}{n}$, donc $\\sigma(M)=\\dfrac{\\sigma}{\\sqrt{n}}$.","$\\sigma(M)=\\dfrac{ {{s}} }{\\sqrt{ {{n}} }}=\\dfrac{ {{s}} }{ {{eval:sqrt(n)}} }=\\textcolor{{{color:primary.0}}}{{{eval:s/sqrt(n)}}}$."]}}],"shared":{"blankDefaults":{"acceptDecimal":true}},"test_specs":[{"answers":["40"],"expected":{"status":"correct"},"variables":{"n":"10","v":"4"},"description":"v0 : n = 10, V = 4 → 40","variationIndex":0},{"answers":["400"],"expected":{"status":"incorrect"},"variables":{"n":"10","v":"4"},"description":"v0 : n²V = 400","variationIndex":0},{"answers":["\\frac{3}{10}"],"expected":{"status":"correct"},"variables":{"n":"20","v":"6"},"description":"v1 : V = 6, n = 20 → 3/10","variationIndex":1},{"answers":["0,3"],"expected":{"status":"correct"},"variables":{"n":"20","v":"6"},"description":"v1 : 0,3 accepté","variationIndex":1},{"answers":["0,015"],"expected":{"status":"incorrect"},"variables":{"n":"20","v":"6"},"description":"v1 : V/n² = 0,015","variationIndex":1},{"answers":["\\frac{3}{2}"],"expected":{"status":"correct"},"variables":{"n":"16","s":"6"},"description":"v2 : σ = 6, n = 16 → 3/2","variationIndex":2},{"answers":["\\frac{3}{8}"],"expected":{"status":"incorrect"},"variables":{"n":"16","s":"6"},"description":"v2 : σ/n = 3/8","variationIndex":2},{"answers":["\\frac{9}{4}"],"expected":{"status":"incorrect"},"variables":{"n":"16","s":"6"},"description":"v2 : variance 9/4","variationIndex":2}]}$plsc$::jsonb,
  null, null, null);
insert into _plsc_modeles values ('b97dabe1-0c52-483e-a738-e62386d5a638', $plsc$Fonctions$plsc$, $plsc$Limites de fonctions$plsc$, $plsc$croissances comparées$plsc$, array['T_SPE'],
  $plsc${"title":"Croissances comparées : exponentielle, puissances, logarithme","description":"Limites de eˣ − kxⁿ, xⁿe⁻ˣ, xⁿeˣ en −∞, ln x / xⁿ, xⁿ ln x en 0 (pièges : x e⁻ˣ → +∞, ∞ × 0 = 1, limite d'un seul facteur)","variations":[{"blanks":[{"expectedAnswer":"+\\infty"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)=e^{x}-{{k}}x^{ {{n}} }$.\n\nDétermine la limite de $f$ en $+\\infty$.\n\n$\\displaystyle\\lim_{x\\to+\\infty}f(x)=?$","variables":[{"name":"k","expression":"1..9"},{"name":"n","expression":"2..5"}],"correction":{"steps":["Forme indéterminée « $\\infty-\\infty$ ». On factorise : $f(x)=e^{x}\\left(1-{{k}}\\dfrac{{{if:n==1|x|x^{ {{n}} }}}}{e^{x}}\\right)$.","Par croissances comparées, $\\displaystyle\\lim_{x\\to+\\infty}\\dfrac{{{if:n==1|x|x^{ {{n}} }}}}{e^{x}}=0$ : la parenthèse tend vers $1$.","Donc $\\displaystyle\\lim_{x\\to+\\infty}f(x)=\\textcolor{{{color:primary.0}}}{+\\infty}$ : l'exponentielle l'emporte sur toute puissance."]}},{"blanks":[{"expectedAnswer":"0"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)={{k}}x^{ {{n}} }e^{-x}$.\n\nDétermine la limite de $f$ en $+\\infty$.\n\n$\\displaystyle\\lim_{x\\to+\\infty}f(x)=?$","variables":[{"name":"k","expression":"1..9"},{"name":"n","expression":"1..4"}],"correction":{"steps":["Forme indéterminée « $\\infty\\times0$ ». On écrit $f(x)={{k}}\\dfrac{{{if:n==1|x|x^{ {{n}} }}}}{e^{x}}$.","Par croissances comparées, $\\displaystyle\\lim_{x\\to+\\infty}\\dfrac{e^{x}}{{{if:n==1|x|x^{ {{n}} }}}}=+\\infty$, donc $\\displaystyle\\lim_{x\\to+\\infty}\\dfrac{{{if:n==1|x|x^{ {{n}} }}}}{e^{x}}=0$ et $\\displaystyle\\lim_{x\\to+\\infty}f(x)=\\textcolor{{{color:primary.0}}}{0}$."]}},{"blanks":[{"expectedAnswer":"0"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)={{k}}x^{ {{n}} }e^{x}$.\n\nDétermine la limite de $f$ en $-\\infty$.\n\n$\\displaystyle\\lim_{x\\to-\\infty}f(x)=?$","variables":[{"name":"k","expression":"1..9"},{"name":"n","expression":"1..4"}],"correction":{"steps":["En $-\\infty$, ${{if:n==1|x|x^{ {{n}} }}}$ tend vers l'infini et $e^{x}$ vers $0$ : forme indéterminée « $\\infty\\times0$ ».","Par croissances comparées, $\\displaystyle\\lim_{x\\to-\\infty}{{if:n==1|x|x^{ {{n}} }}}e^{x}=0$, donc $\\displaystyle\\lim_{x\\to-\\infty}f(x)=\\textcolor{{{color:primary.0}}}{0}$."]}},{"blanks":[{"expectedAnswer":"0"}],"statement":"Soit $f$ la fonction définie sur $\\left]0\\,;+\\infty\\right[$ par $f(x)=\\dfrac{ {{if:k==1||{{k}}}}\\ln x}{{{if:n==1|x|x^{ {{n}} }}}}$.\n\nDétermine la limite de $f$ en $+\\infty$.\n\n$\\displaystyle\\lim_{x\\to+\\infty}f(x)=?$","variables":[{"name":"k","expression":"1..9"},{"name":"n","expression":"1..3"}],"correction":{"steps":["Forme indéterminée « $\\dfrac{\\infty}{\\infty}$ ».","Par croissances comparées, $\\displaystyle\\lim_{x\\to+\\infty}\\dfrac{\\ln x}{{{if:n==1|x|x^{ {{n}} }}}}=0$ : la puissance l'emporte sur le logarithme.","$\\displaystyle\\lim_{x\\to+\\infty}f(x)=\\textcolor{{{color:primary.0}}}{0}$."]}},{"blanks":[{"expectedAnswer":"0"}],"statement":"Soit $f$ la fonction définie sur $\\left]0\\,;+\\infty\\right[$ par $f(x)={{if:k==1||{{k}}}}{{if:n==1|x|x^{ {{n}} }}}\\ln x$.\n\nDétermine la limite de $f$ en $0$ (on a $x>0$).\n\n$\\displaystyle\\lim_{x\\to0}f(x)=?$","variables":[{"name":"k","expression":"1..9"},{"name":"n","expression":"1..3"}],"correction":{"steps":["En $0$, ${{if:n==1|x|x^{ {{n}} }}}$ tend vers $0$ et $\\ln x$ vers $-\\infty$ : forme indéterminée « $0\\times\\infty$ ».","Par croissances comparées, $\\displaystyle\\lim_{x\\to0}{{if:n==1|x|x^{ {{n}} }}}\\ln x=0$, donc $\\displaystyle\\lim_{x\\to0}f(x)=\\textcolor{{{color:primary.0}}}{0}$."]}}],"shared":{"cleanCoefficients":true},"test_specs":[{"answers":["+\\infty"],"expected":{"status":"correct"},"variables":{"k":"3","n":"2"},"description":"v0 : eˣ − 3x² → +∞","variationIndex":0},{"answers":["-\\infty"],"expected":{"status":"incorrect"},"variables":{"k":"3","n":"2"},"description":"v0 : −∞ (la puissance l'emporterait)","variationIndex":0},{"answers":["0"],"expected":{"status":"incorrect"},"variables":{"k":"3","n":"2"},"description":"v0 : 0","variationIndex":0},{"answers":["0"],"expected":{"status":"correct"},"variables":{"k":"2","n":"3"},"description":"v1 : 2x³e⁻ˣ → 0","variationIndex":1},{"answers":["+\\infty"],"expected":{"status":"incorrect"},"variables":{"k":"2","n":"3"},"description":"v1 : +∞ (limite de x³ seule)","variationIndex":1},{"answers":["2"],"expected":{"status":"incorrect"},"variables":{"k":"2","n":"3"},"description":"v1 : k (∞ × 0 = 1)","variationIndex":1},{"answers":["0"],"expected":{"status":"correct"},"variables":{"k":"5","n":"2"},"description":"v2 : 5x²eˣ en −∞ → 0","variationIndex":2},{"answers":["+\\infty"],"expected":{"status":"incorrect"},"variables":{"k":"5","n":"2"},"description":"v2 : +∞ (limite de x² seule)","variationIndex":2},{"answers":["0"],"expected":{"status":"correct"},"variables":{"k":"4","n":"2"},"description":"v3 : 4 ln x / x² → 0","variationIndex":3},{"answers":["+\\infty"],"expected":{"status":"incorrect"},"variables":{"k":"4","n":"2"},"description":"v3 : +∞","variationIndex":3},{"answers":["0"],"expected":{"status":"correct"},"variables":{"k":"3","n":"1"},"description":"v4 : 3x ln x en 0 → 0","variationIndex":4},{"answers":["-\\infty"],"expected":{"status":"incorrect"},"variables":{"k":"3","n":"1"},"description":"v4 : −∞ (limite de ln seule)","variationIndex":4}]}$plsc$::jsonb,
  $plsc${"title":"Croissances comparées : exponentielle et puissances","description":"Limites de eˣ − kxⁿ et xⁿe⁻ˣ en +∞, de xⁿeˣ en −∞ (pièges : x e⁻ˣ → +∞, ∞ × 0 = 1, limite d'un seul facteur)","variations":[{"blanks":[{"expectedAnswer":"+\\infty"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)=e^{x}-{{k}}x^{ {{n}} }$.\n\nDétermine la limite de $f$ en $+\\infty$.\n\n$\\displaystyle\\lim_{x\\to+\\infty}f(x)=?$","variables":[{"name":"k","expression":"1..9"},{"name":"n","expression":"2..5"}],"correction":{"steps":["Forme indéterminée « $\\infty-\\infty$ ». On factorise : $f(x)=e^{x}\\left(1-{{k}}\\dfrac{{{if:n==1|x|x^{ {{n}} }}}}{e^{x}}\\right)$.","Par croissances comparées, $\\displaystyle\\lim_{x\\to+\\infty}\\dfrac{{{if:n==1|x|x^{ {{n}} }}}}{e^{x}}=0$ : la parenthèse tend vers $1$.","Donc $\\displaystyle\\lim_{x\\to+\\infty}f(x)=\\textcolor{{{color:primary.0}}}{+\\infty}$ : l'exponentielle l'emporte sur toute puissance."]}},{"blanks":[{"expectedAnswer":"0"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)={{k}}x^{ {{n}} }e^{-x}$.\n\nDétermine la limite de $f$ en $+\\infty$.\n\n$\\displaystyle\\lim_{x\\to+\\infty}f(x)=?$","variables":[{"name":"k","expression":"1..9"},{"name":"n","expression":"1..4"}],"correction":{"steps":["Forme indéterminée « $\\infty\\times0$ ». On écrit $f(x)={{k}}\\dfrac{{{if:n==1|x|x^{ {{n}} }}}}{e^{x}}$.","Par croissances comparées, $\\displaystyle\\lim_{x\\to+\\infty}\\dfrac{e^{x}}{{{if:n==1|x|x^{ {{n}} }}}}=+\\infty$, donc $\\displaystyle\\lim_{x\\to+\\infty}\\dfrac{{{if:n==1|x|x^{ {{n}} }}}}{e^{x}}=0$ et $\\displaystyle\\lim_{x\\to+\\infty}f(x)=\\textcolor{{{color:primary.0}}}{0}$."]}},{"blanks":[{"expectedAnswer":"0"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)={{k}}x^{ {{n}} }e^{x}$.\n\nDétermine la limite de $f$ en $-\\infty$.\n\n$\\displaystyle\\lim_{x\\to-\\infty}f(x)=?$","variables":[{"name":"k","expression":"1..9"},{"name":"n","expression":"1..4"}],"correction":{"steps":["En $-\\infty$, ${{if:n==1|x|x^{ {{n}} }}}$ tend vers l'infini et $e^{x}$ vers $0$ : forme indéterminée « $\\infty\\times0$ ».","Par croissances comparées, $\\displaystyle\\lim_{x\\to-\\infty}{{if:n==1|x|x^{ {{n}} }}}e^{x}=0$, donc $\\displaystyle\\lim_{x\\to-\\infty}f(x)=\\textcolor{{{color:primary.0}}}{0}$."]}}],"shared":{"cleanCoefficients":true},"test_specs":[{"answers":["+\\infty"],"expected":{"status":"correct"},"variables":{"k":"3","n":"2"},"description":"v0 : eˣ − 3x² → +∞","variationIndex":0},{"answers":["-\\infty"],"expected":{"status":"incorrect"},"variables":{"k":"3","n":"2"},"description":"v0 : −∞ (la puissance l'emporterait)","variationIndex":0},{"answers":["0"],"expected":{"status":"incorrect"},"variables":{"k":"3","n":"2"},"description":"v0 : 0","variationIndex":0},{"answers":["0"],"expected":{"status":"correct"},"variables":{"k":"2","n":"3"},"description":"v1 : 2x³e⁻ˣ → 0","variationIndex":1},{"answers":["+\\infty"],"expected":{"status":"incorrect"},"variables":{"k":"2","n":"3"},"description":"v1 : +∞ (limite de x³ seule)","variationIndex":1},{"answers":["2"],"expected":{"status":"incorrect"},"variables":{"k":"2","n":"3"},"description":"v1 : k (∞ × 0 = 1)","variationIndex":1},{"answers":["0"],"expected":{"status":"correct"},"variables":{"k":"5","n":"2"},"description":"v2 : 5x²eˣ en −∞ → 0","variationIndex":2},{"answers":["+\\infty"],"expected":{"status":"incorrect"},"variables":{"k":"5","n":"2"},"description":"v2 : +∞ (limite de x² seule)","variationIndex":2}]}$plsc$::jsonb,
