insert into _plsc_modeles values ('c0f49b76-fe50-44cf-80b6-3ee8ee5ab9f5', $plsc$Suites$plsc$, $plsc$Limites de suites$plsc$, $plsc$définition$plsc$, array['T_SPE'],
  $plsc${"title":"Définition de la limite : un rang à partir duquel tous les termes conviennent","description":"Donner UN entier N tel que tous les termes uₙ pour n ≥ N sont dans [A ; +∞[, dans ]ℓ − ε ; ℓ + ε[ ou dans ]−∞ ; −A] (toute réponse qui convient est juste ; pièges : rang trop petit, rang non entier)","variations":[{"blanks":[{"rulesSuffice":true,"expectedAnswer":"{{eval:10^t}}","validationRules":[{"max":"1000000000","min":"0","type":"range","inclusive":true},{"type":"predicate","predicate":"isInteger"},{"type":"custom","expression":"answer^2 >= {{A}}","description":"Pour ce rang, $u_N<{{A}}$ : il est trop petit."}]}],"statement":"Pour tout entier naturel $n$, $u_n=n^{2}$. La suite $(u_n)$ tend vers $+\\infty$ : tout intervalle $[A\\,;+\\infty[$ contient tous les termes à partir d'un certain rang.\n\nDonne un entier naturel $N$ tel que, pour tout $n\\geqslant N$, $u_n\\geqslant{{A}}$.\n\n$N=?$","variables":[{"name":"t","expression":"2..3"},{"name":"A","expression":"eval:10^(2*t)"}],"correction":{"steps":["$(u_n)$ est croissante sur $\\mathbb{N}$ : dès que $u_N\\geqslant{{A}}$, tous les termes suivants aussi.","$n^{2}\\geqslant{{A}}\\iff n\\geqslant{{eval:10^t}}$ (pour $n\\geqslant0$). Le plus petit rang qui convient est $N=\\textcolor{{{color:primary.0}}}{ {{eval:10^t}} }$ ; tout entier plus grand convient aussi."]}},{"blanks":[{"rulesSuffice":true,"expectedAnswer":"{{eval:P+1}}","validationRules":[{"max":"1000000000","min":"0","type":"range","inclusive":true},{"type":"predicate","predicate":"isInteger"},{"type":"custom","expression":"answer > {{P}}","description":"Pour ce rang, $u_N$ n'est pas dans l'intervalle : il est trop petit."}]}],"statement":"Pour tout entier $n\\geqslant1$, $u_n={{L}}+\\dfrac{ {{a}} }{n}$. La suite $(u_n)$ converge vers ${{L}}$ : l'intervalle $\\left]{{eval:L-10^(-t);d}}\\,;{{eval:L+10^(-t);d}}\\right[$ contient tous les termes à partir d'un certain rang.\n\nDonne un entier $N\\geqslant1$ tel que, pour tout $n\\geqslant N$, $u_n$ appartient à cet intervalle.\n\n$N=?$","variables":[{"name":"L","expression":"1..9"},{"name":"a","expression":"1..9"},{"name":"t","expression":"1..2"},{"name":"P","expression":"eval:a*10^t"}],"correction":{"steps":["Pour $n\\geqslant1$, $u_n>{{L}}$ ; il suffit que $\\dfrac{ {{a}} }{n}<{{eval:10^(-t);d}}$, soit $n>{{P}}$.","$\\dfrac{ {{a}} }{n}$ décroît : le plus petit rang qui convient est $N=\\textcolor{{{color:primary.0}}}{ {{eval:P+1}} }$ ; tout entier plus grand convient aussi."]}},{"blanks":[{"rulesSuffice":true,"expectedAnswer":"{{N0}}","validationRules":[{"max":"1000000000","min":"0","type":"range","inclusive":true},{"type":"predicate","predicate":"isInteger"},{"type":"custom","expression":"{{b}} - {{c}}*answer <= -{{A}}","description":"Pour ce rang, $u_N>-{{A}}$ : il est trop petit."}]}],"statement":"Pour tout entier naturel $n$, $u_n={{b}}-{{c}}n$. La suite $(u_n)$ tend vers $-\\infty$ : tout intervalle $]-\\infty\\,;-A]$ contient tous les termes à partir d'un certain rang.\n\nDonne un entier naturel $N$ tel que, pour tout $n\\geqslant N$, $u_n\\leqslant-{{A}}$.\n\n$N=?$","variables":[{"name":"b","expression":"1..9"},{"name":"c","expression":"2..5"},{"name":"A","expression":"100|1000"},{"name":"N0","expression":"eval:ceil((A+b)/c)"}],"correction":{"steps":["$(u_n)$ est décroissante. $u_n\\leqslant-{{A}}\\iff{{b}}-{{c}}n\\leqslant-{{A}}\\iff n\\geqslant\\dfrac{ {{eval:A+b}} }{ {{c}} }$.","Le plus petit rang qui convient est $N=\\textcolor{{{color:primary.0}}}{ {{N0}} }$ ; tout entier plus grand convient aussi."]}}],"shared":null,"test_specs":[{"answers":["100"],"expected":{"status":"correct"},"variables":{"A":"10000","t":"2"},"description":"v0 A=10⁴ : N=100","variationIndex":0},{"answers":["500"],"expected":{"status":"correct"},"variables":{"A":"10000","t":"2"},"description":"v0 : N=500 convient aussi","variationIndex":0},{"answers":["99"],"expected":{"status":"incorrect"},"variables":{"A":"10000","t":"2"},"description":"v0 : N=99 trop petit","variationIndex"