3"},"description":"v0 : 3e (produit)","variationIndex":0},{"answers":["e^{-2}"],"expected":{"status":"correct"},"variables":{"a":"-2"},"description":"v0 : ln x = −2 → e⁻²","variationIndex":0},{"answers":["\\frac{1}{e^2}"],"expected":{"status":"correct"},"variables":{"a":"-2"},"description":"v0 : 1/e² pour e⁻² : même forme (décision du 2026-10-04)","variationIndex":0},{"answers":["\\frac{e^3-1}{2}"],"expected":{"status":"correct"},"variables":{"a":"2","b":"1","c":"3"},"description":"v1 : ln(2x+1) = 3 → (e³−1)/2","variationIndex":1},{"answers":["1"],"expected":{"status":"incorrect"},"variables":{"a":"2","b":"1","c":"3"},"description":"v1 : e^c oublié → (3−1)/2","variationIndex":1},{"answers":["\\frac{\\ln 3-1}{2}"],"expected":{"status":"incorrect"},"variables":{"a":"2","b":"1","c":"3"},"description":"v1 : ln(2x+1) = 3 → ln 3 …","variationIndex":1},{"answers":["\\sqrt{5}"],"expected":{"status":"correct"},"variables":{"a":"5"},"description":"v2 : 2 ln x = ln 5 → √5","variationIndex":2},{"answers":["-\\sqrt{5}"],"expected":{"status":"incorrect"},"variables":{"a":"5"},"description":"v2 : domaine oublié −√5","variationIndex":2},{"answers":["\\frac{5}{2}"],"expected":{"status":"incorrect"},"variables":{"a":"5"},"description":"v2 : 5/2 (division par 2 sous le ln)","variationIndex":2}]}$plsc$::jsonb,
