insert into _plsc_modeles values ('dbee4649-3ab6-49f0-8a5e-5814ce15ba43', $plsc$Probabilités$plsc$, $plsc$Loi binomiale$plsc$, $plsc$espérance et variance$plsc$, array['T_SPE', 'T_COMP'],
  $plsc${"title":"Loi binomiale et loi de Bernoulli : espérance, variance, écart type","description":"E(X) = np, V(X) = np(1 − p), σ(X) = √(np(1 − p)) ; Bernoulli : V = p(1 − p) ; nombre moyen de succès (pièges : np(1 − p) contre np, variance contre écart type)","variations":[{"blanks":[{"expectedAnswer":"{{eval:n*t/100}}"}],"statement":"La variable aléatoire $X$ suit la loi binomiale $\\mathcal{B}\\left({{n}}\\,;{{eval:t/100;d}}\\right)$.\n\nCalcule son espérance (nombre entier ou décimal).\n\n$E(X)=?$","variables":[{"name":"n","expression":"20|40|50|60|80|100|150|200"},{"name":"t","expression":"1..40"}],"correction":{"steps":["Pour $X\\sim\\mathcal{B}(n\\,;p)$ : $E(X)=np$.","$E(X)={{n}}\\times{{eval:t/100;d}}=\\textcolor{{{color:primary.0}}}{{{eval:n*t/100;d}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:n*t*(10-t)/100}}"}],"statement":"La variable aléatoire $X$ suit la loi binomiale $\\mathcal{B}\\left({{n}}\\,;{{eval:t/10;d}}\\right)$.\n\nCalcule sa variance (nombre entier ou décimal).\n\n$V(X)=?$","variables":[{"name":"n","expression":"10|20|30|50|100"},{"name":"t","expression":"1..9"}],"correction":{"steps":["Pour $X\\sim\\mathcal{B}(n\\,;p)$ : $V(X)=np(1-p)$.","$V(X)={{n}}\\times{{eval:t/10;d}}\\times{{eval:1-t/10;d}}=\\textcolor{{{color:primary.0}}}{{{eval:n*t*(10-t)/100;d}}}$."]}},{"blanks":[{"expectedAnswer":"{{s}}"}],"statement":"La variable aléatoire $X$ suit la loi binomiale $\\mathcal{B}\\left({{n}}\\,;{{p}}\\right)$.\n\nCalcule son écart type $\\sigma(X)$ (valeur exacte).\n\n$\\sigma(X)=?$","variables":[{"name":"w","expression":"1..8"},{"name":"n","expression":"{{if:w==1|16|{{if:w==2|36|{{if:w==3|64|{{if:w==4|100|{{if:w==5|25|{{if:w==6|100|{{if:w==7|100|400}}}}}}}}}}}}}}"},{"name":"pp","expression":"{{if:w==1|0.5|{{if:w==2|0.5|{{if:w==3|0.5|{{if:w==4|0.5|{{if:w==5|0.2|{{if:w==6|0.2|{{if:w==7|0.1|0.1}}}}}}}}}}}}}}"},{"name":"p","expression":"{{eval:pp;d}}"},{"name":"s","expression":"{{if:w==1|2|{{if:w==2|3|{{if:w==3|4|{{if:w==4|5|{{if:w==5|2|{{if:w==6|4|{{if:w==7|3|6}}}}}}}}}}}}}}"}],"correction":{"steps":["$V(X)=np(1-p)={{n}}\\times{{p}}\\times{{eval:1-pp;d}}={{eval:s^2}}$.","$\\sigma(X)=\\sqrt{V(X)}=\\sqrt{ {{eval:s^2}} }=\\textcolor{{{color:primary.0}}}{{{s}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:c*(q-c)/q^2}}"}],"statement":"La variable aléatoire $X$ suit la loi de Bernoulli de paramètre $p=\\dfrac{ {{c}} }{ {{q}} }$.\n\nCalcule sa variance.\n\n$V(X)=?$","variables":[{"name":"q","expression":"3..8"},{"name":"c","expression":"1..{{eval:q-1}}"}],"conditions":["gcd(c, q) == 1"],"correction":{"steps":["Pour une loi de Bernoulli : $E(X)=p$ et $V(X)=p(1-p)$.","$V(X)=\\dfrac{ {{c}} }{ {{q}} }\\times\\dfrac{ {{eval:q-c}} }{ {{q}} }=\\textcolor{{{color:primary.0}}}{{{eval:c*(q-c)/q^2}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:n/q}}"}],"statement":"Un questionnaire comporte ${{n}}$ questions ; pour chacune, ${{q}}$ réponses sont proposées, dont une seule est juste. Un élève répond au hasard à chaque question, indépendamment.\n\nCombien de bonnes réponses peut-il espérer en moyenne ?\n\n$?$","variables":[{"name":"n","expression":"10|12|15|20|24|30|40"},{"name":"q","expression":"2..5"}],"correction":{"steps":["Le nombre $X$ de bonnes réponses suit la loi $\\mathcal{B}\\left({{n}}\\,;\\dfrac{1}{ {{q}} }\\right)$.","$E(X)=np={{n}}\\times\\dfrac{1}{ {{q}} }=\\textcolor{{{color:primary.0}}}{{{eval:n/q}}}$ bonnes réponses en moyenne."]}}],"shared":{"blankDefaults":{"acceptDecimal":true}},"test_specs":[{"answers":["15"],"expected":{"status":"correct"},"variables":{"n":"50","t":"30"},"description":"v0 : B(50 ; 0,3) → 15","variationIndex":0},{"answers":["10,5"],"expected":{"status":"incorrect"},"variables":{"n":"50","t":"30"},"description":"v0 : variance 10,5 au lieu de E","variationIndex":0},{"answers":["2,8"],"expected":{"status":"correct"},"variables":{"n":"40","t":"7"},"description":"v0 : B(40 ; 0,07) → 2,8","variationIndex":0},{"answers":["8"],"expected":{"status":"correct"},"variables":{"n":"50","t":"2"},"description":"v1 : B(50 ; 0,2) → 8","variationIndex":1},{"answers":["10"],"expected":{"status":"incorrect"},"variables":{"n":"50","t":"2"},"description":"v1 : np = 10 au lieu de np(1 − p)","variationIndex":1},{"answers":["\\sqrt{8}"],"expected":{"status":"incorrect"},"variables":{"n":"50","t":"2"},"description":"v1 : écart type √8","variationIndex":1},{"answers":["2,1"],"expected":{"status":"correct"},"variables":{"n":"10","t":"3"},"description":"v1 : B(10 ; 0,3) → 2,1","variationIndex":1},{"answers":["4"],"expected":{"status":"correct"},"variables":{"w":"6"},"description":"v2 : B(100 ; 0,2) → 4","variationIndex":2},{"answers":["16"],"expected":{"status":"incorrect"},"variables":{"w":"6"},"description":"v2 : variance 16","variationIndex":2},{"answers":["\\sqrt{16}"],"expected":{"status":"unoptimal_form","constraintViolations":["reducedRadicals"]},"variables":{"w":"6"},"description":"v2 : √16 non calculé","variationIndex":2},{"answers":["\\frac{3}{16}"],"expected":{"status":"correct"},"variables":{"c":"1","q":"4"},"description":"v3 : p = 1/4 → 3/16","variationIndex":3},{"answers":["\\frac{1}{4}"],"expected":{"status":"incorrect"},"variables":{"c":"1","q":"4"},"description":"v3 : E = p","variationIndex":3},{"answers":["\\frac{1}{16}"],"expected":{"status":"incorrect"},"variables":{"c":"1","q":"4"},"description":"v3 : p²","variationIndex":3},{"answers":["5"],"expected":{"status":"correct"},"variables":{"n":"20","q":"4"},"description":"v4 : 20 questions, 4 réponses → 5","variationIndex":4},{"answers":["15"],"expected":{"status":"incorrect"},"variables":{"n":"20","q":"4"},"description":"v4 : n(1 − p) = 15","variationIndex":4}]}$plsc$::jsonb,
  $plsc${"title":"Loi binomiale : espérance","description":"E(X) = np, nombre moyen de succès (piège : np(1 − p) au lieu de np)","variations":[{"blanks":[{"expectedAnswer":"{{eval:n*t/100}}"}],"statement":"La variable aléatoire $X$ suit la loi binomiale $\\mathcal{B}\\left({{n}}\\,;{{eval:t/100;d}}\\right)$.\n\nCalcule son espérance (nombre entier ou décimal).\n\n$E(X)=?$","variables":[{"name":"n","expression":"20|40|50|60|80|100|150|200"},{"name":"t","expression":"1..40"}],"correction":{"steps":["Pour $X\\sim\\mathcal{B}(n\\,;p)$ : $E(X)=np$.","$E(X)={{n}}\\times{{eval:t/100;d}}=\\textcolor{{{color:primary.0}}}{{{eval:n*t/100;d}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:n/q}}"}],"statement":"Un questionnaire comporte ${{n}}$ questions ; pour chacune, ${{q}}$ réponses sont proposées, dont une seule est juste. Un élève répond au hasard à chaque question, indépendamment.\n\nCombien de bonnes réponses peut-il espérer en moyenne ?\n\n$?$","variables":[{"name":"n","expression":"10|12|15|20|24|30|40"},{"name":"q","expression":"2..5"}],"correction":{"steps":["Le nombre $X$ de bonnes réponses suit la loi $\\mathcal{B}\\left({{n}}\\,;\\dfrac{1}{ {{q}} }\\right)$.","$E(X)=np={{n}}\\times\\dfrac{1}{ {{q}} }=\\textcolor{{{color:primary.0}}}{{{eval:n/q}}}$ bonnes réponses en moyenne."]}}],"shared":{"blankDefaults":{"acceptDecimal":true}},"test_specs":[{"answers":["15"],"expected":{"status":"correct"},"variables":{"n":"50","t":"30"},"description":"v0 : B(50 ; 0,3) → 15","variationIndex":0},{"answers":["10,5"],"expected":{"status":"incorrect"},"variables":{"n":"50","t":"30"},"description":"v0 : variance 10,5 au lieu de E","variationIndex":0},{"answers":["2,8"],"expected":{"status":"correct"},"variables":{"n":"40","t":"7"},"description":"v0 : B(40 ; 0,07) → 2,8","variationIndex":0},{"answers":["5"],"expected":{"status":"correct"},"variables":{"n":"20","q":"4"},"description":"v1 : 20 questions, 4 réponses → 5","variationIndex":1},{"answers":["15"],"expected":{"status":"incorrect"},"variables":{"n":"20","q":"4"},"description":"v1 : n(1 − p) = 15","variationIndex":1}]}$plsc$::jsonb,
  null, null, null);
insert into _plsc_modeles values ('dd0ee69a-2203-47a3-b2b8-af70a77281d3', $plsc$Intégration$plsc$, $plsc$Calcul d'intégrales$plsc$, $plsc$positivité et inégalités$plsc$, array['T_SPE', 'T_COMP'],
  $plsc${"title":"Encadrer une intégrale ou une valeur moyenne","description":"m ≤ f ≤ M sur [a ; b] donne m(b − a) ≤ ∫ₐᵇ f ≤ M(b − a) et m ≤ μ ≤ M ; lecture sur une courbe (piège : oubli de la longueur b − a)","variations":[{"blanks":[{"expectedAnswer":"{{eval:m*(b-a)}}"},{"expectedAnswer":"{{eval:M*(b-a)}}"}],"statement":"$f$ est une fonction continue sur $\\left[{{a}}\\,;{{b}}\\right]$ telle que, pour tout $x$ de cet intervalle, ${{m}}\\leqslant f(x)\\leqslant {{M}}$.\n\nComplète l'encadrement le plus précis que l'on peut en déduire :\n\n$?\\leqslant\\displaystyle\\int_{{{a}}}^{{{b}}}f(x)\\,\\mathrm{d}x\\leqslant ?$","variables":[{"name":"a","expression":"-2..1"},{"name":"b","expression":"2..5"},{"name":"m","expression":"-3..3"},{"name":"M","expression":"2..8"}],"conditions":["m < M"],"correction":{"steps":["On intègre l'encadrement sur $\\left[{{a}}\\,;{{b}}\\right]$, intervalle de longueur ${{b}}-{{a;()}}={{eval:b-a}}$ (bornes dans le bon ordre).","$\\displaystyle\\int_{{{a}}}^{{{b}}}{{m}}\\,\\mathrm{d}x\\leqslant\\displaystyle\\int_{{{a}}}^{{{b}}}f(x)\\,\\mathrm{d}x\\leqslant\\displaystyle\\int_{{{a}}}^{{{b}}}{{M}}\\,\\mathrm{d}x$, soit $\\textcolor{{{color:primary.0}}}{{{eval:m*(b-a)}}}\\leqslant\\displaystyle\\int_{{{a}}}^{{{b}}}f(x)\\,\\mathrm{d}x\\leqslant\\textcolor{{{color:primary.0}}}{{{eval:M*(b-a)}}}$."]}},{"blanks":[{"expectedAnswer":"{{p}}"},{"expectedAnswer":"{{q}}"}],"statement":"$f$ est une fonction continue et croissante sur $\\left[{{a}}\\,;{{b}}\\right]$, avec $f({{a}})={{p}}$ et $f({{b}})={{q}}$. On note $\\mu$ sa valeur moyenne sur cet intervalle.\n\nComplète l'encadrement le plus précis que l'on peut en déduire :\n\n$?\\leqslant\\mu\\leqslant ?$","variables":[{"name":"a","expression":"-2..1"},{"name":"b","expression":"3..6"},{"name":"p","expression":"-4..2"},{"name":"q","expression":"3..9"}],"correction":{"steps":["$f$ est croissante : pour tout $x$ de $\\left[{{a}}\\,;{{b}}\\right]$, ${{p}}\\leqslant f(x)\\leqslant {{q}}$.","La valeur moyenne est comprise entre les bornes de $f$ : $\\textcolor{{{color:primary.0}}}{{{p}}}\\leqslant\\mu\\leqslant\\textcolor{{{color:primary.0}}}{{{q}}}$. (C'est l'**intégrale** qui vaut entre ${{eval:p*(b-a)}}$ et ${{eval:q*(b-a)}}$.)"]}},{"blanks":[{"expectedAnswer":"{{eval:3*c/4}}"},{"expectedAnswer":"{{eval:3*c}}"}],"statement":"On a représenté ci-dessous la courbe $\\mathcal{C}_f$ de la fonction $f:x\\mapsto\\dfrac{ {{c}} }{x+1}$, décroissante sur $\\left[0\\,;3\\right]$.\n\n```courbe\nx: -0.5 ; 4\ny: -0.5 ; {{eval:c+1}}\ngrille: 1 ; 1\nf(x) = {{c}}/(x+1) sur [0 ; 3]   bleu   nom=C_f\npoints: A(0 ; {{c}}), B(3 ; {{eval:c/4}})\naire: f ; 0 ; 3\ntaille: moyenne\ndescription: Courbe décroissante d'une fonction inverse décalée sur [0 ; 3], aire sous la courbe coloriée.\n```\n\nComplète l'encadrement le plus précis que l'on peut déduire des valeurs $f(0)$ et $f(3)$ :\n\n$?\\leqslant\\displaystyle\\int_{0}^{3}f(x)\\,\\mathrm{d}x\\leqslant ?$","variables":[{"name":"c","expression":"4|8"}],"correction":{"steps":["$f$ est décroissante sur $\\left[0\\,;3\\right]$ : $f(3)={{eval:c/4}}\\leqslant f(x)\\leqslant f(0)={{c}}$.","L'aire coloriée est entre celles des rectangles de largeur $3$ et de hauteurs ${{eval:c/4}}$ et ${{c}}$ : $\\textcolor{{{color:primary.0}}}{{{eval:3*c/4}}}\\leqslant\\displaystyle\\int_{0}^{3}f(x)\\,\\mathrm{d}x\\leqslant\\textcolor{{{color:primary.0}}}{{{eval:3*c}}}$."]}}],"shared":{"blankDefaults":{"acceptDecimal":true},"cleanCoefficients":true},"test_specs":[{"answers":["3","12"],"expected":{"status":"correct"},"variables":{"M":"4","a":"0","b":"3","m":"1"},"description":"v0 : 1 ≤ f ≤ 4 sur [0;3] → 3 et 12","variationIndex":0},{"answers":["1","4"],"expected":{"status":"incorrect"},"variables":{"M":"4","a":"0","b":"3","m":"1"},"description":"v0 : longueur oubliée","variationIndex":0},{"answers":["3","12"],"expected":{"status":"incorrect"},"variables":{"M":"4","a":"-1","b":"3","m":"1"},"description":"v0 : largeur b au lieu de b−a","variationIndex":0},{"answe