athrm{d}x\\leqslant ?$","variables":[{"name":"c","expression":"4|8"}],"correction":{"steps":["$f$ est décroissante sur $\\left[0\\,;3\\right]$ : $f(3)={{eval:c/4}}\\leqslant f(x)\\leqslant f(0)={{c}}$.","L'aire coloriée est entre celles des rectangles de largeur $3$ et de hauteurs ${{eval:c/4}}$ et ${{c}}$ : $\\textcolor{{{color:primary.0}}}{{{eval:3*c/4}}}\\leqslant\\displaystyle\\int_{0}^{3}f(x)\\,\\mathrm{d}x\\leqslant\\textcolor{{{color:primary.0}}}{{{eval:3*c}}}$."]}}],"shared":{"blankDefaults":{"acceptDecimal":true},"cleanCoefficients":true},"test_specs":[{"answers":["3","12"],"expected":{"status":"correct"},"variables":{"M":"4","a":"0","b":"3","m":"1"},"description":"v0 : 1 ≤ f ≤ 4 sur [0;3] → 3 et 12","variationIndex":0},{"answers":["1","4"],"expected":{"status":"incorrect"},"variables":{"M":"4","a":"0","b":"3","m":"1"},"description":"v0 : longueur oubliée","variationIndex":0},{"answers":["3","12"],"expected":{"status":"incorrect"},"variables":{"M":"4","a":"-1","b":"3","m":"1"},"description":"v0 : largeur b au lieu de b−a","variationIndex":0},{"answers":["4","16"],"expected":{"status":"correct"},"variables":{"M":"4","a":"-1","b":"3","m":"1"},"description":"v0 : a=−1 → 4 et 16","variationIndex":0},{"answers":["-6","10"],"expected":{"status":"correct"},"variables":{"M":"5","a":"0","b":"2","m":"-3"},"description":"v0 : m<0","variationIndex":0},{"answers":["3","12"],"expected":{"status":"correct"},"variables":{"c":"4"},"description":"v1 : c=4 → 3 et 12","variationIndex":1},{"answers":["12","3"],"expected":{"status":"incorrect"},"variables":{"c":"4"},"description":"v1 : bornes inversées","variationIndex":1},{"answers":["1","4"],"expected":{"status":"incorrect"},"variables":{"c":"4"},"description":"v1 : valeurs de f sans la largeur","variationIndex":1}]}$plsc$::jsonb,
