insert into _plsc_modeles values ('ef3c495c-632b-40ec-840d-fbbf7bfc879a', $plsc$Dénombrement$plsc$, $plsc$Combinaisons$plsc$, $plsc$coefficients binomiaux$plsc$, array['T_SPE', 'T_COMP'],
  $plsc${"title":"Coefficients binomiaux : chemins, symétrie, triangle de Pascal","description":"Sans formule factorielle : nombre de chemins à k succès, C(n, 0), C(n, 1), C(n, n), symétrie C(n, n − k) = C(n, k), relation et triangle de Pascal","variations":[{"blanks":[{"expectedAnswer":"{{c}}","acceptCombinatorialNotation":true}],"statement":"On représente par un arbre un schéma de Bernoulli de ${{n}}$ épreuves (succès $S$, échec $\\overline{S}$).\n\nCombien de chemins de cet arbre comportent exactement ${{k}}$ succès ?\n\n$?$","variables":[{"name":"n","expression":"3..5"},{"name":"k","expression":"1..{{eval:n-1}}"},{"name":"c","expression":"{{eval:binom(n,k)}}"}],"correction":{"steps":["Le nombre de chemins à ${{k}}$ succès parmi ${{n}}$ épreuves est, par définition, le coefficient binomial $\\binom{ {{n}} }{ {{k}} }$.","On peut les lister (un chemin = une position des ${{k}}$ succès parmi les ${{n}}$ épreuves) : $\\binom{ {{n}} }{ {{k}} }=\\textcolor{{{color:primary.0}}}{{{c}}}$."]}},{"blanks":[{"expectedAnswer":"{{c}}"}],"statement":"On donne $\\binom{ {{n}} }{ {{k}} }={{c}}$.\n\nSans calcul, donne $\\binom{ {{n}} }{ {{eval:n-k}} }$.\n\n$\\binom{ {{n}} }{ {{eval:n-k}} }=?$","variables":[{"name":"n","expression":"8..20"},{"name":"k","expression":"2..4"},{"name":"c","expression":"{{eval:binom(n,k)}}"}],"correction":{"steps":["Symétrie : $\\binom{n}{n-k}=\\binom{n}{k}$ (choisir les ${{k}}$ succès revient à choisir les ${{eval:n-k}}$ échecs).","$\\binom{ {{n}} }{ {{eval:n-k}} }=\\binom{ {{n}} }{ {{k}} }=\\textcolor{{{color:primary.0}}}{{{c}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:A+B}}"}],"statement":"On donne $\\binom{ {{n}} }{ {{k}} }={{A}}$ et $\\binom{ {{n}} }{ {{eval:k+1}} }={{B}}$.\n\nSans autre calcul, donne $\\binom{ {{eval:n+1}} }{ {{eval:k+1}} }$.\n\n$\\binom{ {{eval:n+1}} }{ {{eval:k+1}} }=?$","variables":[{"name":"n","expression":"6..15"},{"name":"k","expression":"1..2"},{"name":"A","expression":"{{eval:binom(n,k)}}"},{"name":"B","expression":"{{eval:binom(n,k+1)}}"}],"correction":{"steps":["Relation de Pascal : $\\binom{n}{k}+\\binom{n}{k+1}=\\binom{n+1}{k+1}$.","$\\binom{ {{eval:n+1}} }{ {{eval:k+1}} }={{A}}+{{B}}=\\textcolor{{{color:primary.0}}}{{{eval:A+B}}}$."]}},{"blanks":[{"expectedAnswer":"1"},{"expectedAnswer":"{{n}}"},{"expectedAnswer":"1"}],"statement":"Donne les coefficients binomiaux suivants.\n\n$\\binom{ {{n}} }{0}=?$ ; $\\binom{ {{n}} }{1}=?$ ; $\\binom{ {{n}} }{ {{n}} }=?$","variables":[{"name":"n","expression":"5..40"}],"correction":{"steps":["$\\binom{ {{n}} }{0}=\\textcolor{{{color:primary.0}}}{1}$ : un seul chemin sans succès (que des échecs).","$\\binom{ {{n}} }{1}=\\textcolor{{{color:primary.0}}}{{{n}}}$ : le succès unique peut être à l'une des ${{n}}$ épreuves.","$\\binom{ {{n}} }{ {{n}} }=\\textcolor{{{color:primary.0}}}{1}$ : un seul chemin où tout est succès."]}},{"blanks":[{"expectedAnswer":"{{if:k==2|{{eval:(n+1)*n/2}}|{{eval:(n+1)*n*(n-1)/6}}}}"}],"statement":"La ligne $n={{n}}$ du triangle de Pascal donne, dans l'ordre, les coefficients $\\binom{ {{n}} }{0}$, $\\binom{ {{n}} }{1}$, …, $\\binom{ {{n}} }{ {{n}} }$ :\n\n$1$ ; ${{c1}}$ ; ${{c2}}$ ; ${{c3}}$ ; ${{c4}}$ ; ${{c5}}${{if:n>=6| ; ${{c6}}$|}}{{if:n>=7| ; ${{c7}}$|}}\n\nDéduis-en $\\binom{ {{eval:n+1}} }{ {{k}} }$.\n\n$\\binom{ {{eval:n+1}} }{ {{k}} }=?$","variables":[{"name":"n","expression":"5..7"},{"name":"c0","expression":"1"},{"name":"c1","expression":"{{n}}"},{"name":"c2","expression":"{{eval:n*(n-1)/2}}"},{"name":"c3","expression":"{{eval:n*(n-1)*(n-2)/6}}"},{"name":"m4","expression":"{{eval:n-4}}"},{"name":"c4","expression":"{{eval:binom(n,m4)}}"},{"name":"m5","expression":"{{eval:n-5}}"},{"name":"c5","expression":"{{eval:binom(n,m5)}}"},{"name":"m6","expression":"{{eval:n-6}}"},{"name":"c6","expression":"{{eval:binom(n,m6)}}"},{"name":"m7","expression":"{{eval:n-7}}"},{"name":"c7","expression":"{{eval:binom(n,m7)}}"},{"name":"k","expression":"2..3"}],"correction":{"steps":["Dans le triangle de Pascal, chaque coefficient est la somme des deux coefficients placés au-dessus : $\\binom{ {{eval:n+1}} }{ {{k}} }=\\binom{ {{n}} }{ {{eval:k-1}} }+\\binom{ {{n}} }{ {{k}} }$.","$\\binom{ {{eval:n+1}} }{ {{k}} }={{if:k==2|{{c1}}+{{c2}}|{{c2}}+{{c3}}}}=\\textcolor{{{color:primary.0}}}{{{if:k==2|{{eval:(n+1)*n/2}}|{{eval:(n+1)*n*(n-1)/6}}}}}$."]}}],"shared":null,"test_specs":[{"answers":["6"],"expected":{"status":"correct"},"variables":{"k":"2","n":"4"},"description":"v0 : n = 4, k = 2 → 6","variationIndex":0},{"answers":["8"],"expected":{"status":"incorrect"},"variables":{"k":"2","n":"4"},"description":"v0 : n × k = 8","variationIndex":0},{"answers":["16"],"expected":{"status":"incorrect"},"variables":{"k":"2","n":"4"},"description":"v0 : 2ⁿ = 16 (tous les chemins)","variationIndex":0},{"answers":["220"],"expected":{"status":"correct"},"variables":{"k":"3","n":"12"},"description":"v1 : C(12, 3) = 220 → C(12, 9)","variationIndex":1},{"answers":["9"],"expected":{"status":"incorrect"},"variables":{"k":"3","n":"12"},"description":"v1 : 9","variationIndex":1},{"answers":["165"],"expected":{"status":"correct"},"variables":{"k":"2","n":"10"},"description":"v2 : C(10,2) + C(10,3) = 45 + 120","variationIndex":2},{"answers":["5400"],"expected":{"status":"incorrect"},"variables":{"k":"2","n":"10"},"description":"v2 : produit","variationIndex":2},{"answers":["1","12","1"],"expected":{"status":"correct"},"variables":{"n":"12"},"description":"v3 : n = 12 → 1 ; 12 ; 1","variationIndex":3},{"answers":["0","12","1"],"expected":{"status":"incorrect"},"variables":{"n":"12"},"description":"v3 : C(n, 0) = 0","variationIndex":3},{"answers":["1","12","12"],"expected":{"status":"incorrect"},"variables":{"n":"12"},"description":"v3 : C(n, n) = n","variationIndex":3},{"answers":["15"],"expected":{"status":"correct"},"variables":{"k":"2","n":"5"},"description":"v4 : ligne 5, C(6, 2) = 15","variationIndex":4},{"answers":["35"],"expected":{"status":"correct"},"variables":{"k":"3","n":"6"},"description":"v4 : ligne 6,