insert into _plsc_modeles values ('f01270c2-3c63-45c5-bfbb-8233154fadc6', $plsc$Équations différentielles$plsc$, $plsc$y′ = f$plsc$, $plsc$forme (v′∘u)×u′$plsc$, array['T_SPE', 'T_COMP'],
  $plsc${"title":"Coefficient d'une primitive de la forme u′eᵘ, 2uu′ ou u′/u","description":"Trouver k pour que k·eᵘ, k·u² ou k·ln(u) soit une primitive de f : diviser par le facteur manquant de u′ (piège : multiplier)","variations":[{"blanks":[{"expectedAnswer":"{{eval:1/a}}"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)=e^{{{if:a==1|x}}{{if:a==-1|-x}}{{if:a!=1 && a!=-1|{{eval:a}}x}}{{if:b>0|+{{eval:b}}}}{{if:b<0|{{eval:b}}}}}$.\n\nDétermine le réel $k$ tel que la fonction $F$ définie par $F(x)=k\\,e^{{{if:a==1|x}}{{if:a==-1|-x}}{{if:a!=1 && a!=-1|{{eval:a}}x}}{{if:b>0|+{{eval:b}}}}{{if:b<0|{{eval:b}}}}}$ soit une primitive de $f$ sur $\\mathbb{R}$.\n\n$k=?$","variables":[{"name":"a","expression":"2..6;±"},{"name":"b","expression":"-5..5"}],"correction":{"steps":["Avec $u(x)={{if:a==1|x}}{{if:a==-1|-x}}{{if:a!=1 && a!=-1|{{eval:a}}x}}{{if:b>0|+{{eval:b}}}}{{if:b<0|{{eval:b}}}}$, on a $u'(x)={{eval:a}}$ et $(e^{u})'=u'e^{u}$.","$F'(x)=k\\times{{eval:a;()}}e^{{{if:a==1|x}}{{if:a==-1|-x}}{{if:a!=1 && a!=-1|{{eval:a}}x}}{{if:b>0|+{{eval:b}}}}{{if:b<0|{{eval:b}}}}}$. Pour que $F'=f$, il faut ${{eval:a}}k=1$, soit $k=\\textcolor{{{color:primary.0}}}{{{eval:1/a}}}$.","On divise par $u'$ : on ne multiplie pas."]}},{"blanks":[{"expectedAnswer":"{{eval:c/2}}"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)={{if:c==1|x}}{{if:c==-1|-x}}{{if:c!=1 && c!=-1|{{eval:c}}x}}e^{x^2}$.\n\nDétermine le réel $k$ tel que la fonction $F$ définie par $F(x)=k\\,e^{x^2}$ soit une primitive de $f$ sur $\\mathbb{R}$.\n\n$k=?$","variables":[{"name":"c","expression":"1..6;±"}],"correction":{"steps":["Avec $u(x)=x^2$, $u'(x)=2x$ et $(e^{u})'=u'e^{u}$ : $F'(x)=k\\times 2x\\,e^{x^2}=2k\\,x\\,e^{x^2}$.","Il faut $2k={{eval:c}}$, soit $k=\\textcolor{{{color:primary.0}}}{{{eval:c/2}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:c/4}}"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)={{if:c==1|x}}{{if:c==-1|-x}}{{if:c!=1 && c!=-1|{{eval:c}}x}}(x^2{{if:m>0|+{{eval:m}}}}{{if:m<0|{{eval:m}}}})$.\n\nDétermine le réel $k$ tel que la fonction $F$ définie par $F(x)=k(x^2{{if:m>0|+{{eval:m}}}}{{if:m<0|{{eval:m}}}})^2$ soit une primitive de $f$ sur $\\mathbb{R}$.\n\n$k=?$","variables":[{"name":"c","expression":"1..6;±"},{"name":"m","expression":"1..9;±"}],"correction":{"steps":["Avec $u(x)=x^2{{if:m>0|+{{eval:m}}}}{{if:m<0|{{eval:m}}}}$, $u'(x)=2x$ et $(u^2)'=2u'u$ : $F'(x)=k\\times 2\\times 2x(x^2{{if:m>0|+{{eval:m}}}}{{if:m<0|{{eval:m}}}})=4k\\,x(x^2{{if:m>0|+{{eval:m}}}}{{if:m<0|{{eval:m}}}})$.","Il faut $4k={{eval:c}}$, soit $k=\\textcolor{{{color:primary.0}}}{{{eval:c/4}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:c/2}}"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)={{if:c<0|-}}\\dfrac{{{if:abs(c)==1|x}}{{if:abs(c)==-1|-x}}{{if:abs(c)!=1 && abs(c)!=-1|{{eval:abs(c)}}x}}}{x^2+{{eval:m}}}$.\n\nDétermine le réel $k$ tel que la fonction $F$ définie par $F(x)=k\\ln(x^2+{{eval:m}})$ soit une primitive de $f$ sur $\\mathbb{R}$.\n\n$k=?$","variables":[{"name":"c","expression":"1..6;±"},{"name":"m","expression":"1..9"}],"correction":{"steps":["Avec $u(x)=x^2+{{eval:m}}$, strictement positive, $u'(x)=2x$ et $(\\ln u)'=\\dfrac{u'}{u}$ : $F'(x)=k\\times\\dfrac{2x}{x^2+{{eval:m}}}$.","Il faut $2k={{eval:c}}$, soit $k=\\textcolor{{{color:primary.0}}}{{{eval:c/2}}}$."]}}],"shared":{"blankDefaults":{"acceptDecimal":true},"cleanCoefficients":true},"test_specs":[{"answers":["\\frac{1}{3}"],"expected":{"status":"correct"},"variables":{"a":"3","b":"1"},"description":"v0 : e^{3x+1} → 1/3","variationIndex":0},{"answers":["3"],"expected":{"status":"incorrect"},"variables":{"a":"3","b":"1"},"description":"v0 : multiplié par u' au lieu de diviser","variationIndex":0},{"answers":["1"],"expected":{"status":"incorrect"},"variables":{"a":"3","b":"1"},"description":"v0 : coefficient oublié","variationIndex":0},{"answers":["-\\frac{1}{2}"],"expected":{"status":"correct"},"variables":{"a":"-2","b":"0"}