insert into _plsc_modeles values ('f26151ff-9b70-414b-9c92-b53a1839bd79', $plsc$Intégration$plsc$, $plsc$Valeur moyenne$plsc$, null, array['T_SPE', 'T_COMP'],
  $plsc${"title":"Interpréter une intégrale ou une valeur moyenne en contexte","description":"∫ v(t) dt = distance parcourue, ∫ débit = volume, (1/T)∫ v = vitesse moyenne (piège : confondre distance et vitesse moyenne)","variations":[{"blanks":[{"expectedAnswer":"{{eval:a*T^2/2+b*T}}"}],"statement":"Un mobile se déplace en ligne droite. Sa vitesse, en mètres par seconde, à l'instant $t$ (en secondes) est $v(t)={{a}}t+{{b}}$ pour $t\\in\\left[0\\,;{{T}}\\right]$.\n\nLa distance parcourue entre les instants $0$ et ${{T}}$ est $\\displaystyle\\int_{0}^{{{T}}}v(t)\\,\\mathrm{d}t$. Calcule-la, en mètres.\n\n$?$","variables":[{"name":"a","expression":"1..4"},{"name":"b","expression":"0..6"},{"name":"T","expression":"2..6"}],"correction":{"steps":["Une primitive de $v$ est $D(t)={{eval:a/2}}t^2+{{b}}t$.","Distance $=D({{T}})-D(0)=\\textcolor{{{color:primary.0}}}{{{eval:a*T^2/2+b*T}}}$ m."]}},{"blanks":[{"expectedAnswer":"{{eval:k*T^3/3}}"}],"statement":"Le débit d'un robinet, en litres par minute, à l'instant $t$ (en minutes) est $d(t)={{k}}t^2$ pour $t\\in\\left[0\\,;{{T}}\\right]$.\n\nLe volume d'eau écoulé entre les instants $0$ et ${{T}}$ est $\\displaystyle\\int_{0}^{{{T}}}d(t)\\,\\mathrm{d}t$. Calcule-le, en litres.\n\n$?$","variables":[{"name":"k","expression":"3|6"},{"name":"T","expression":"1..4"}],"correction":{"steps":["Une primitive de $d$ est $V(t)={{eval:k/3}}t^3$.","Volume $=V({{T}})-V(0)=\\textcolor{{{color:primary.0}}}{{{eval:k*T^3/3}}}$ L."]}},{"blanks":[{"expectedAnswer":"{{eval:a*T/2+b}}"}],"statement":"Un mobile se déplace en ligne droite. Sa vitesse, en mètres par seconde, à l'instant $t$ (en secondes) est $v(t)={{a}}t+{{b}}$ pour $t\\in\\left[0\\,;{{T}}\\right]$.\n\nCalcule sa **vitesse moyenne** entre les instants $0$ et ${{T}}$, en mètres par seconde.\n\n$?$","variables":[{"name":"a","expression":"1..4"},{"name":"b","expression":"0..6"},{"name":"T","expression":"2..6"}],"correction":{"steps":["La vitesse moyenne est la valeur moyenne de $v$ : $\\dfrac{1}{ {{T}}-0}\\displaystyle\\int_{0}^{{{T}}}v(t)\\,\\mathrm{d}t$.","$\\displaystyle\\int_{0}^{{{T}}}v(t)\\,\\mathrm{d}t={{eval:a*T^2/2+b*T}}$ (distance parcourue, en m), donc vitesse moyenne $=\\dfrac{ {{eval:a*T^2/2+b*T}} }{ {{T}} }=\\textcolor{{{color:primary.0}}}{{{eval:a*T/2+b}}}$ m/s."]}}],"shared":{"blankDefaults":{"acceptDecimal":true},"cleanCoefficients":true},"test_specs":[{"answers":["20"],"expected":{"status":"correct"},"variables":{"T":"4","a":"2","b":"1"},"description":"v0 : 2t+1 sur [0;4] → 20","variationIndex":0},{"answers":["9"],"expected":{"status":"incorrect"},"variables":{"T":"4","a":"2","b":"1"},"description":"v0 : vitesse finale v(T)","variationIndex":0},{"answers":["5"],"expected":{"status":"incorrect"},"variables":{"T":"4","a":"2","b":"1"},"description":"v0 : vitesse moyenne au lieu de distance","variationIndex":0},{"answers":["8"],"expected":{"status":"correct"},"variables":{"T":"2","k":"3"},"description":"v1 : 3t² sur [0;2] → 8","variationIndex":1},{"answers":["12"],"expected":{"status":"incorrect"},"variables":{"T":"2","k":"3"},"description":"v1 : débit final","variationIndex":1},{"answers":["5"],"expected":{"status":"correct"},"variables":{"T":"4","a":"2","b":"1"},"description":"v2 : 2t+1 sur [0;4] → 5","variationIndex":2},{"answers":["20"],"expected":{"status":"incorrect"},"variables":{"T":"4","a":"2","b":"1"},"description":"v2 : distance au lieu de vitesse moyenne","variationIndex":2},{"answers":["\\frac{3}{2}"],"expected":{"status":"correct"},"variables":{"T":"3","a":"1","b":"0"},"description":"v2 : moyenne de v(0) et v(T) ≠ ? (ici égale : affine)","variationIndex":2}]}$plsc$::jsonb,
  $plsc${"title":"Interpréter une intégrale en contexte","description":"∫ v(t) dt = distance parcourue, ∫ débit = volume écoulé","variations":[{"blanks":[{"expectedAnswer":"{{eval:a*T^2/2+b*T}}"}],"statement":"Un mobile se déplace en ligne droite. Sa vitesse, en mètres par seconde, à l'instant $t$ (en secondes) est $v(t)={{a}}t+{{b}}$ pour $t\\in\\left[0\\,;{{T}}\\right]$.\n\nLa distance parcourue entre les instants $0$ et ${{T}}$ est $\\displaystyle\\int_{0}^{{{T}}}v(t)\\,\\mathrm{d}t$. Calcule-la, en mètres.\n\n$?$","variables":[{"name":"a","expression":"1..4"},{"name":"b","expression":"0..6"},{"name":"T","expression":"2..6"}],"correction":{"steps":["Une primitive de $v$ est $D(t)={{eval:a/2}}t^2+{{b}}t$.","Distance $=D({{T}})-D(0)=\\textcolor{{{color:primary.0}}}{{{eval:a*T^2/2+b*T}}}$ m."]}},{"blanks":[{"expectedAnswer":"{{eval:k*T^3/3}}"}],"statement":"Le débit d'un robinet, en litres par minute, à l'instant $t$ (en minutes) est $d(t)={{k}}t^2$ pour $t\\in\\left[0\\,;{{T}}\\right]$.\n\nLe volume d'eau écoulé entre les instants $0$ et ${{T}}$ est $\\displaystyle\\int_{0}^{{{T}}}d(t)\\,\\mathrm{d}t$. Calcule-le, en litres.\n\n$?$","variables":[{"name":"k","expression":"3|6"},{"name":"T","expression":"1..4"}],"correction":{"steps":["Une primitive de $d$ est $V(t)={{eval:k/3}}t^3$.","Volume $=V({{T}})-V(0)=\\textcolor{{{color:primary.0}}}{{{eval:k*T^3/3}}}$ L."]}}],"shared":{"blankDefaults":{"acceptDecimal":true},"cleanCoefficients":true},"test_specs":[{"answers":["20"],"expected":{"status":"correct"},"variables":{"T":"4","a":"2","b":"1"},"description":"v0 : 2t+1 sur [0;4] → 20","variationIndex":0},{"answers":["9"],"expected":{"status":"incorrect"},"variables":{"T":"4","a":"2","b":"1"},"description":"v0 : vitesse finale v(T)","variationIndex":0},{"answers":["5"],"expected":{"status":"incorrect"},"variables":{"T":"4","a":"2","b":"1"},"description":"v0 : vitesse moyenne au lieu de distance","variationIndex":0},{"answers":["8"],"expected":{"status":"correct"},"variables":{"T":"2","k":"3"},"description":"v1 : 3t² sur [0;2] → 8","variationIndex":1},{"answers":["12"],"expected":{"status":"incorrect"},"variables":{"T":"2","k":"3"},"description":"v1 : débit final","variationIndex":1}]}$plsc$::jsonb,
  $plsc$Intégration$plsc$, $plsc$Intégrale et aire$plsc$, null);

-- Tags des origines : ceux qu'elles portent déjà (relevé, exigés à l'identique et laissés) et ceux
