-- Modèles neufs : chacun copie les autres colonnes de son origine, sauf le niveau (et le nœud
-- quand l'un de ses points vit sur une sous-notion voisine).
drop table if exists pg_temp._plsc_neufs;
create temporary table _plsc_neufs (
	id uuid primary key,
	origine uuid not null references _plsc_modeles (id),
	niveau integer not null,
	contenu jsonb not null,
	-- Nœud propre (celui de son premier point) ; null : celui de l'origine.
	branche text, notion text, sous_notion text
);
insert into _plsc_neufs values ('74604a26-fd67-45ae-bff7-1d095bea3e0c', '0bde6091-c122-46c0-94d5-a97cdde28d9d', 4,
  $plsc${"title":"Mots à deux lettres : combinaisons","description":"Mots formés de k lettres A et n − k lettres B, comptés par C(n, k) (pièges : 2ⁿ, n!)","variations":[{"blanks":[{"expectedAnswer":"{{eval:binom(n,k)}}","acceptCombinatorialNotation":true}],"statement":"Combien de mots de ${{n}}$ lettres peut-on écrire avec exactement ${{k}}$ lettres $\\mathrm{A}$ et ${{eval:n-k}}$ lettres $\\mathrm{B}$ ?\n\n$?$","variables":[{"name":"n","expression":"6..12"},{"name":"k","expression":"2..{{eval:n-2}}"}],"correction":{"steps":["Un tel mot est déterminé par les positions des ${{k}}$ lettres $\\mathrm{A}$ parmi les ${{n}}$ places : une partie à ${{k}}$ éléments.","$\\binom{ {{n}} }{ {{k}} }=\\textcolor{{{color:primary.0}}}{{{eval:binom(n,k)}}}$."]}}],"shared":null,"test_specs":[{"answers":["56"],"expected":{"status":"correct"},"variables":{"k":"3","n":"8"},"description":"v0 : 8 lettres, 3 A → 56","variationIndex":0},{"answers":["256"],"expected":{"status":"incorrect"},"variables":{"k":"3","n":"8"},"description":"v0 : 2⁸ = 256","variationIndex":0},{"answers":["336"],"expected":{"status":"incorrect"},"variables":{"k":"3","n":"8"},"description":"v0 : 8!/(5!) = 336","variationIndex":0}]}$plsc$::jsonb,
  null, null, null);
insert into _plsc_neufs values ('62e446cb-624a-46ef-a627-c62636b7628a', '119b9148-e95b-4865-b0d4-52f0cf264de2', 2,
  $plsc${"title":"Espace : distance entre deux points","description":"Distance AB en repère orthonormé, valeur exacte (pièges : racine oubliée, z oublié, racine non simplifiée)","variations":[{"blanks":[{"expectedAnswer":"{{eval:sqrt((bx-ax)^2+(by-ay)^2+(bz-az)^2)}}"}],"statement":"Dans l'espace muni d'un repère orthonormé, on considère les points $A({{ax}}\\,;\\,{{ay}}\\,;\\,{{az}})$ et $B({{bx}}\\,;\\,{{by}}\\,;\\,{{bz}})$.\n\nCalcule la distance $AB$ (valeur exacte, racine simplifiée).\n\n$AB=?$","variables":[{"name":"ax","expression":"-5..5"},{"name":"ay","expression":"-5..5"},{"name":"az","expression":"-5..5"},{"name":"bx","expression":"-5..5"},{"name":"by","expression":"-5..5"},{"name":"bz","expression":"-5..5"}],"conditions":["bz != az","bx != ax || by != ay"],"correction":{"steps":["$AB=\\sqrt{(x_B-x_A)^2+(y_B-y_A)^2+(z_B-z_A)^2}$ dans un repère orthonormé.","$AB=\\sqrt{{{eval:bx-ax;()}}^2+{{eval:by-ay;()}}^2+{{eval:bz-az;()}}^2}=\\sqrt{{{eval:(bx-ax)^2+(by-ay)^2+(bz-az)^2}}}=\\textcolor{{{color:primary.0}}}{ {{eval:sqrt((bx-ax)^2+(by-ay)^2+(bz-az)^2)}} }$"]}}],"shared":null,"test_specs":[{"answers":["\\sqrt{14}"],"expected":{"status":"correct"},"variables":{"ax":"1","ay":"-2","az":"0","bx":"3","by":"1","bz":"-1"},"description":"v0 : √14","variationIndex":0},{"answers":["14"],"expected":{"status":"incorrect"},"variables":{"ax":"1","ay":"-2","az":"0","bx":"3","by":"1","bz":"-1"},"description":"v0 : AB² (14)","variationIndex":0},{"answers":["\\sqrt{13}"],"expected":{"status":"incorrect"},"variables":{"ax":"1","ay":"-2","az":"0","bx":"3","by":"1","bz":"-1"},"description":"v0 : z oublié (√13)","variationIndex":0},{"answers":["3\\sqrt{2}"],"expected":{"status":"incorrect"},"variables":{"ax":"1","ay":"-2","az":"0","bx":"3","by":"1","bz":"-1"},"description":"v0 : coordonnées ajoutées au lieu de soustraites","variationIndex":0}]}$plsc$::jsonb,
  null, null, null);
insert into _plsc_neufs values ('7c8bd127-d67e-47ba-a4ad-1277833ab12f', '1277a5b6-b979-4e3b-b5b6-e10aedfbedfb', 2,
  $plsc${"title":"Espace : produit scalaire par polarisation","description":"u·v à partir de ‖u‖, ‖v‖ et ‖u + v‖ (piège : division par 2 oubliée)","variations":[{"blanks":[{"expectedAnswer":"{{eval:(c^2-a^2-b^2)/2}}"}],"statement":"Dans l'espace, $\\vec{u}$ et $\\vec{v}$ sont deux vecteurs tels que $\\|\\vec{u}\\|={{a}}$, $\\|\\vec{v}\\|={{b}}$ et $\\|\\vec{u}+\\vec{v}\\|={{c}}$.\n\nCalcule $\\vec{u}\\cdot\\vec{v}$.\n\n$\\vec{u}\\cdot\\vec{v}=?$","variables":[{"name":"a","expression":"2..8"},{"name":"b","expression":"2..8"},{"name":"c","expression":"2..12"}],"conditions":["c < a+b","c > abs(a-b)","c*c != a*a+b*b"],"correction":{"steps":["$\\|\\vec{u}+\\vec{v}\\|^2=\\|\\vec{u}\\|^2+2\\,\\vec{u}\\cdot\\vec{v}+\\|\\vec{v}\\|^2$, donc $\\vec{u}\\cdot\\vec{v}=\\dfrac{1}{2}\\left(\\|\\vec{u}+\\vec{v}\\|^2-\\|\\vec{u}\\|^2-\\|\\vec{v}\\|^2\\right)$.","$\\vec{u}\\cdot\\vec{v}=\\dfrac{1}{2}\\left({{c}}^2-{{a}}^2-{{b}}^2\\right)=\\textcolor{{{color:primary.0}}}{ {{eval:(c^2-a^2-b^2)/2}} }$"]}}],"shared":{"blankDefaults":{"acceptDecimal":true}},"test_specs":[{"answers":["\\frac{11}{2}"],"expected":{"status":"correct"},"variables":{"a":"3","b":"4","c":"6"},"description":"v0 : 11/2","variationIndex":0},{"answers":["5.5"],"expected":{"status":"correct"},"variables":{"a":"3","b":"4","c":"6"},"description":"v0 : 5,5 accepté","variationIndex":0},{"answers":["11"],"expected":{"status":"incorrect"},"variables":{"a":"3","b":"4","c":"6"},"description":"v0 : division par 2 oubliée","variationIndex":0},{"answers":["-\\frac{1}{2}"],"expected":{"status":"incorrect"},"variables":{"a":"3","b":"4","c":"6"},"description":"v0 : normes non élevées au carré","variationIndex":0}]}$plsc$::jsonb,
  null, null, null);
insert into _plsc_neufs values ('76b4061b-1b1a-4513-9aeb-c991ca3d5334', '13e2d419-770b-4e97-a2f8-972d467cf2fc', 3,
  $plsc${"title":"Loi géométrique : nombre moyen de tentatives","description":"Rang moyen du premier succès : E(X) = 1/p (piège : E = p)","variations":[{"blanks":[{"expectedAnswer":"{{eval:100/t}}"}],"statement":"À chaque tentative, un joueur réussit un exercice d'adresse avec la probabilité ${{eval:t/100;d}}$, indépendamment des autres tentatives. Il recommence jusqu'à la première réussite.\n\nCombien de tentatives lui faut-il en moyenne ?\n\n$?$","variables":[{"name":"t","expression":"2|4|5|8|10|20|25|40|50"}],"correction":{"steps":["Le rang $X$ de la première réussite suit la loi géométrique de paramètre $p={{eval:t/100;d}}$, d'espérance $E(X)=\\dfrac{1}{p}$.","$E(X)=\\dfrac{1}{ {{eval:t/100;d}} }=\\textcolor{{{color:primary.0}}}{{{eval:100/t;d}}}$ tentatives en moyenne."]}}],"shared":{"blankDefaults":{"acceptDecimal":true}},"test_specs":[{"answers":["20"],"expected":{"status":"correct"},"variables":{"t":"5"},"description":"v0 : p = 0,05 → 20","variationIndex":0},{"answers":["0,05"],"expected":{"status":"incorrect"},"variables":{"t":"5"},"description":"v0 : E = p","variationIndex":0},{"answers":["12,5"],"expected":{"status":"correct"},"variables":{"t":"8"},"description":"v0 : p = 0,08 → 12,5","variationIndex":0}]}$plsc$::jsonb,
  null, null, null);
insert into _plsc_neufs values ('7d3632bb-f590-446f-8a4e-26e1e5fdcdbf', '13e2d419-770b-4e97-a2f8-972d467cf2fc', 4,
  $plsc${"title":"Loi géométrique : absence de mémoire","description":"P(X > m + n | X > m) = P(X > n) (piège : mémoire non utilisée)","variations":[{"blanks":[{"expectedAnswer":"{{eval:(1-1/q)^j}}"}],"statement":"La durée de vie $X$, en jours entiers, d'un composant suit la loi géométrique $\\mathcal{G}\\left(\\dfrac{1}{ {{q}} }\\right)$. Le composant fonctionne encore après ${{m}}$ jours.\n\nQuelle est la probabilité qu'il fonctionne encore après ${{eval:m+j}}$ jours ?\n\n$P_{(X>{{m}})}(X>{{eval:m+j}})=?$","variables":[{"name":"q","expression":"2..6"},{"name":"m","expression":"3..9"},{"name":"j","expression":"1..3"}],"correction":{"steps":["La loi géométrique est **sans mémoire** : $P_{(X>m)}(X>m+n)=P(X>n)$.","$P_{(X>{{m}})}(X>{{eval:m+j}})=P(X>{{j}})=\\left(\\dfrac{ {{eval:q-1}} }{ {{q}} }\\right)^{ {{j}} }=\\textcolor{{{color:primary.0}}}{{{eval:(1-1/q)^j}}}$."]}}],"shared":{"blankDefaults":{"acceptDecimal":true}},"test_specs":[{"answers":["\\frac{9}{16}"],"expected":{"status":"correct"},"variables":{"j":"2","m":"5","q":"4"},"description":"v0 : G(1/4), m = 5, j = 2 → 9/16","variationIndex":0},{"answers":["\\frac{2187}{16384}"],"expected":{"status":"incorrect"},"variables":{"j":"2","m":"5","q":"4"},"description":"v0 : sans mémoire oubliée (3/4)⁷","variationIndex":0},{"answers":["\\frac{7}{16}"],"expected":{"status":"incorrect"},"variables":{"j":"2","m":"5","q":"4"},"description":"v0 : 1 − (3/4)²","variationIndex":0}]}$plsc$::jsonb,
  $plsc$Probabilités$plsc$, $plsc$Autres lois$plsc$, $plsc$absence de mémoire$plsc$);
