  $plsc${"title":"Résoudre une inéquation avec exp","description":"eˣ > b, e⁻ˣ ⩾ k ; ensemble de solutions en intervalle (pièges : sens de l'inégalité, crochets)","variations":[{"blanks":[{"expectedAnswer":"]\\ln {{b}};+\\infty["}],"statement":"Résous dans $\\mathbb{R}$ l'inéquation $e^{x}>{{b}}$.\n\n$S=?$","variables":[{"name":"b","expression":"2|3|5|6|7|10"}],"correction":{"steps":["$\\ln$ est strictement croissante sur $\\left]0\\,;+\\infty\\right[$ et ${{b}}>0$ : $e^{x}>{{b}}\\iff x>\\ln {{b}}$.","$S=\\textcolor{{{color:primary.0}}}{\\left]\\ln {{b}}\\,;+\\infty\\right[}$."]}},{"blanks":[{"expectedAnswer":"]-\\infty;-\\ln {{k}}]"}],"statement":"Résous dans $\\mathbb{R}$ l'inéquation $e^{-x}\\geqslant{{k}}$.\n\n$S=?$","variables":[{"name":"k","expression":"2|3|5|6|7"}],"correction":{"steps":["$e^{-x}\\geqslant{{k}}\\iff -x\\geqslant\\ln {{k}}$ ($\\ln$ est croissante).","On multiplie par $-1$ : le sens change, $x\\leqslant-\\ln {{k}}$.","$S=\\textcolor{{{color:primary.0}}}{\\left]-\\infty\\,;-\\ln {{k}}\\right]}$."]}}],"shared":{"blankDefaults":{"answerKind":"intervalles"}},"test_specs":[{"answers":["]\\ln 3;+\\infty["],"expected":{"status":"correct"},"variables":{"b":"3"},"description":"v0 : eˣ > 3 → ]ln 3;+∞[","variationIndex":0},{"answers":["]e^3;+\\infty["],"expected":{"status":"incorrect"},"variables":{"b":"3"},"description":"v0 : ]e³;+∞[ (ln et exp confondus)","variationIndex":0},{"answers":["]-\\infty;-\\ln 2]"],"expected":{"status":"correct"},"variables":{"k":"2"},"description":"v1 : e⁻ˣ ≥ 2 → ]−∞;−ln 2]","variationIndex":1},{"answers":["[-\\ln 2;+\\infty["],"expected":{"status":"incorrect"},"variables":{"k":"2"},"description":"v1 : sens non changé","variationIndex":1},{"answers":["]-\\infty;\\ln\\frac{1}{2}]"],"expected":{"status":"correct"},"variables":{"k":"2"},"description":"v1 : ln(1/2) accepté","variationIndex":1}]}$plsc$::jsonb,
  $plsc$Fonctions$plsc$, $plsc$Fonction exponentielle$plsc$, $plsc$équations et inéquations$plsc$);
insert into _plsc_neufs values ('264b9c11-e171-4a2c-9b6e-d5151b309e99', '23402520-cbc3-4d49-b6dc-999e1ff17e3c', 3,
  $plsc${"title":"Primitive de cos(ωx) et sin(ωx)","description":"Primitives de cos(ωx) et sin(ωx), quelconques ou nulles en 0 (pièges : facteur 1/ω oublié ou multiplié, signe)","variations":[{"blanks":[{"expectedAnswer":"\\frac{1}{{{eval:w}}}\\sin({{eval:w}}x)"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)=\\cos({{eval:w}}x)$.\n\nDétermine la primitive $F$ de $f$ sur $\\mathbb{R}$ telle que $F(0)=0$.\n\n$F(x)=?$","variables":[{"name":"w","expression":"2..6"}],"correction":{"steps":["La dérivée de $x\\mapsto\\sin({{eval:w}}x)$ est $x\\mapsto {{eval:w}}\\cos({{eval:w}}x)$ : il faut donc diviser par ${{eval:w}}$.","$F(x)=\\dfrac{1}{{{eval:w}}}\\sin({{eval:w}}x)+k$ et $F(0)=k=0$.","$F(x)=\\textcolor{{{color:primary.0}}}{\\dfrac{1}{{{eval:w}}}\\sin({{eval:w}}x)}$."]}},{"blanks":[{"expectedAnswer":"-\\frac{1}{{{eval:w}}}\\cos({{eval:w}}x)+\\frac{1}{{{eval:w}}}"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)=\\sin({{eval:w}}x)$.\n\nDétermine la primitive $F$ de $f$ sur $\\mathbb{R}$ telle que $F(0)=0$.\n\n$F(x)=?$","variables":[{"name":"w","expression":"2..6"}],"correction":{"steps":["La dérivée de $x\\mapsto\\cos({{eval:w}}x)$ est $x\\mapsto -{{eval:w}}\\sin({{eval:w}}x)$ : une primitive de $f$ est $x\\mapsto -\\dfrac{1}{{{eval:w}}}\\cos({{eval:w}}x)$.","$F(x)=-\\dfrac{1}{{{eval:w}}}\\cos({{eval:w}}x)+k$ et $F(0)=-\\dfrac{1}{{{eval:w}}}+k=0$, donc $k=\\dfrac{1}{{{eval:w}}}$.","$F(x)=\\textcolor{{{color:primary.0}}}{-\\dfrac{1}{{{eval:w}}}\\cos({{eval:w}}x)+\\dfrac{1}{{{eval:w}}}}$."]}},{"blanks":[{"integrand":"\\cos({{eval:w}}x)","answerKind":"primitive","expectedAnswer":"\\frac{1}{{{eval:w}}}\\sin({{eval:w}}x)"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)=\\cos({{eval:w}}x)$.\n\nDonne une primitive $F$ de $f$ sur $\\mathbb{R}$.\n\n$F(x)=?$","variables":[{"name":"w","expression":"2..6"}],"correction":{"steps":["La dérivée de $\\sin({{eval:w}}x)$ est ${{eval:w}}\\cos({{eval:w}}x)$ : on divise par ${{eval:w}}$.","Une primitive de $f$ est $F(x)=\\textcolor{{{color:primary.0}}}{\\dfrac{1}{{{eval:w}}}\\sin({{eval:w}}x)}$ (à une constante près)."]}}],"shared":{"cleanCoefficients":true},"test_specs":[{"answers":["\\frac{1}{3}\\sin(3x)"],"expected":{"status":"correct"},"variables":{"w":"3"},"description":"v0 : cos(3x) → sin(3x)/3","variationIndex":0},{"answers":["\\frac{\\sin(3x)}{3}"],"expected":{"status":"correct"},"variables":{"w":"3"},"description":"v0 : écrit en fraction","variationIndex":0},{"answers":["3\\sin(3x)"],"expected":{"status":"incorrect"},"variables":{"w":"3"},"description":"v0 : multiplié par 3","variationIndex":0},{"answers":["\\sin(3x)"],"expected":{"status":"incorrect"},"variables":{"w":"3"},"description":"v0 : sans le facteur","variationIndex":0},{"answers":["-\\frac{1}{2}\\cos(2x)+\\frac{1}{2}"],"expected":{"status":"correct"},"variables":{"w":"2"},"description":"v1 : sin(2x) → −cos(2x)/2 + 1/2","variationIndex":1},{"answers":["\\frac{1-\\cos(2x)}{2}"],"expected":{"status":"correct"},"variables":{"w":"2"},"description":"v1 : forme factorisée","variationIndex":1},{"answers":["-\\frac{1}{2}\\cos(2x)"],"expected":{"status":"incorrect"},"variables":{"w":"2"},"description":"v1 : condition oubliée","variationIndex":1},{"answers":["\\frac{1}{2}\\cos(2x)-\\frac{1}{2}"],"expected":{"status":"incorrect"},"variables":{"w":"2"},"description":"v1 : signe oublié","variationIndex":1},{"answers":["\\frac{1}{3}\\sin(3x)"],"expected":{"status":"correct"},"variables":{"w":"3"},"description":"v2 (ouverte) f=cos(3x) : primitive modèle","variationIndex":2},{"answers":["\\frac{\\sin(3x)}{3}+1"],"expected":{"status":"correct"},"variables":{"w":"3"},"description":"v2 (ouverte) f=cos(3x) : autre constante","variationIndex":2},{"answers":["\\frac{1}{3}\\sin(3x)+C"],"expected":{"status":"correct"},"variables":{"w":"3"},"description":"v2 (ouverte) f=cos(3x) : avec +C","variationIndex":2},{"answers":["-3\\sin(3x)"],"expected":{"status":"incorrect"},"variables":{"w":"3"},"description":"v2 (ouverte) f=cos(3x) : dérivée au lieu de primitive (message)","variationIndex":2},{"answers":["\\sin(3x)"],"expected":{"status":"incorrect"},"variables":{"w":"3"},"description":"v2 (ouverte) f=cos(3x) : division oubliée","variationIndex":2},{"answers":["3\\sin(3x)"],"expected":{"status":"incorrect"},"variables":{"w":"3"},"description":"v2 (ouverte) f=cos(3x) : multiplié au lieu de divisé","variationIndex":2}]}$plsc$::jsonb,
