","k":"20","n":"5","t":"3"},"description":"une année de moins : 2 240","variationIndex":0},{"answers":["2\\,000+5\\times60"],"expected":{"status":"bad_form","constraintViolations":["form"]},"variables":{"C":"2000","k":"20","n":"5","t":"3"},"description":"calcul non effectué : 2 000 + 5 × 60","variationIndex":0}]}$plsc$::jsonb,
