insert into _plsc_neufs values ('98f9d4b2-ebdd-4ed9-81a4-deb2e5b58c07', '37ce7759-c2fa-4353-a726-f0c942284053', 5,
  $plsc${"title":"Point d'inflexion : lecture graphique","description":"Lire sur la courbe de f l'abscisse de son point d'inflexion (changement de convexité)","variations":[{"choices":[{"content":"${{h}}$"},{"content":"${{eval:h+1}}$"},{"content":"${{eval:h-1}}$"},{"content":"${{k}}$"}],"statement":"On a représenté ci-dessous la courbe $\\mathcal{C}_f$ d'une fonction $f$ deux fois dérivable sur $\\mathbb{R}$.\n\n```courbe\nx: {{eval:h-3.5}} ; {{eval:h+3.5}}\ny: {{eval:k-4}} ; {{eval:k+4}}\ngrille: 1 ; 1\nf(x) = {{s}}*0.5*((x-{{h}})^3-3*(x-{{h}}))+{{k}}   bleu   nom=C_f\ntaille: moyenne\ndescription: Courbe d'une fonction polynôme de degré 3 avec un maximum et un minimum locaux.\n```\n\nQuelle est l'abscisse du point d'inflexion de $\\mathcal{C}_f$ ?","variables":[{"name":"s","expression":"-1|1"},{"name":"h","expression":"-2..2"},{"name":"k","expression":"-2..2"}],"conditions":["k != h","k != h+1","k != h-1"],"correction":{"steps":["Au point d'inflexion, la courbe **traverse sa tangente** : elle passe de « tournée vers le {{if:s>0|bas|haut}} » à « tournée vers le {{if:s>0|haut|bas}} ».","C'est le point de coordonnées $({{h}}\\,;{{k}})$ : son abscisse est $\\textcolor{{{color:primary.0}}}{{{h}}}$. Les abscisses ${{eval:h-1}}$ et ${{eval:h+1}}$ sont celles des extremums locaux, pas de l'inflexion."]},"correctChoiceIndex":["0"]}],"shared":{"cleanCoefficients":true},"test_specs":[{"expected":{"status":"correct"},"variables":{"h":"0","k":"2","s":"1"},"description":"v0 : inflexion","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"h":"0","k":"2","s":"1"},"description":"v0 : extremum","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"h":"0","k":"2","s":"1"},"description":"v0 : ordonnée","variationIndex":0,"selectedChoices":[3]}]}$plsc$::jsonb,
