insert into _plsc_neufs values ('b71b4874-4a12-4655-b306-e56b502414e1', '3cb90b97-2ec4-4050-973e-4b194aa65fb3', 2,
  $plsc${"title":"Loi uniforme sur {1, …, n} : espérance","description":"E(X) = (n + 1)/2, gain moyen d'un dé à n faces (piège : n/2)","variations":[{"blanks":[{"expectedAnswer":"{{eval:(n+1)/2}}"}],"statement":"La variable aléatoire $X$ suit la loi uniforme sur $\\{1, 2, \\ldots, {{n}}\\}$.\n\nCalcule son espérance.\n\n$E(X)=?$","variables":[{"name":"n","expression":"5..30"}],"correction":{"steps":["Pour la loi uniforme sur $\\{1, \\ldots, n\\}$ : $E(X)=\\dfrac{n+1}{2}$.","$E(X)=\\dfrac{ {{n}}+1}{2}=\\textcolor{{{color:primary.0}}}{{{eval:(n+1)/2}}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:n+1}}"}],"statement":"On lance un dé équilibré à ${{n}}$ faces numérotées de $1$ à ${{n}}$ et on gagne, en euros, le double du numéro obtenu.\n\nQuel est le gain moyen, en euros ?\n\n$?$","variables":[{"name":"n","expression":"4|6|8|10|12|20"}],"correction":{"steps":["Le numéro $X$ suit la loi uniforme sur $\\{1, \\ldots, {{n}}\\}$ : $E(X)=\\dfrac{ {{n}}+1}{2}={{eval:(n+1)/2;d}}$.","Le gain est $2X$, donc $E(2X)=2E(X)=\\textcolor{{{color:primary.0}}}{{{eval:n+1}}}$ euros."]}}],"shared":{"blankDefaults":{"acceptDecimal":true}},"test_specs":[{"answers":["\\frac{11}{2}"],"expected":{"status":"correct"},"variables":{"n":"10"},"description":"v0 : n = 10 → 11/2","variationIndex":0},{"answers":["5,5"],"expected":{"status":"correct"},"variables":{"n":"10"},"description":"v0 : 5,5 accepté","variationIndex":0},{"answers":["5"],"expected":{"status":"incorrect"},"variables":{"n":"10"},"description":"v0 : n/2 = 5","variationIndex":0},{"answers":["7"],"expected":{"status":"correct"},"variables":{"n":"6"},"description":"v1 : dé à 6 faces → 7","variationIndex":1},{"answers":["3,5"],"expected":{"status":"incorrect"},"variables":{"n":"6"},"description":"v1 : E(X) seulement 3,5","variationIndex":1}]}$plsc$::jsonb,
  null, null, null);
insert into _plsc_neufs values ('6b26aba3-ed27-43e3-97b9-3c6716b09975', '3cfcc718-445a-42f5-8d5e-fe4d8339f4bf', 3,
  $plsc${"title":"Loi à densité : probabilité = aire sous la courbe","description":"Lire une probabilité comme une aire sous la densité (figure) (piège : t/a au lieu de t²/a²)","variations":[{"blanks":[{"expectedAnswer":"{{eval:t^2/a^2}}"}],"statement":"La variable aléatoire $X$ a pour densité la fonction $f$ définie sur $\\left[0\\,;{{a}}\\right]$ par $f(x)={{eval:2/a^2}}x$, représentée ci-dessous.\n\n```courbe\nx: -0.5 ; {{eval:a+1}}\ny: -0.1 ; {{eval:2/a+0.2;d}}\ngrille: 1 ; {{eval:1/(2*a);d}}\nf(x) = 2*x/{{eval:a^2}} sur [0 ; {{a}}]   bleu   nom=C_f\naire: f ; 0 ; {{t}}\ntaille: moyenne\ndescription: Densité triangulaire croissante sur [0 ; {{a}}], aire coloriée entre 0 et {{t}}.\n```\n\nCalcule $P(X\\leqslant {{t}})$, aire du domaine colorié.\n\n$P(X\\leqslant {{t}})=?$","variables":[{"name":"a","expression":"2..6"},{"name":"t","expression":"1..{{eval:a-1}}"}],"correction":{"steps":["$P(X\\leqslant {{t}})$ est l'aire du triangle de base ${{t}}$ et de hauteur $f({{t}})={{eval:2*t/a^2}}$.","$P(X\\leqslant {{t}})=\\dfrac{1}{2}\\times {{t}}\\times{{eval:2*t/a^2}}=\\textcolor{{{color:primary.0}}}{{{eval:t^2/a^2}}}$."]}}],"shared":{"blankDefaults":{"acceptDecimal":true}},"test_specs":[{"answers":["\\frac{1}{4}"],"expected":{"status":"correct"},"variables":{"a":"4","t":"2"},"description":"v0 : a = 4, t = 2 → 1/4","variationIndex":0},{"answers":["\\frac{1}{2}"],"expected":{"status":"incorrect"},"variables":{"a":"4","t":"2"},"description":"v0 : t/a = 1/2","variationIndex":0},{"answers":["\\frac{4}{25}"],"expected":{"status":"correct"},"variables":{"a":"5","t":"2"},"description":"v0 : a = 5, t = 2 → 4/25","variationIndex":0},{"answers":["\\frac{2}{5}"],"expected":{"status":"incorrect"},"variables":{"a":"5","t":"2"},"description":"v0 : a = 5, t = 2, t/a = 2/5","variationIndex":0}]}$plsc$::jsonb,
  null, null, null);
insert into _plsc_neufs values ('d9ac0141-321b-47a0-abf4-8be4f710b0e1', '3cfcc718-445a-42f5-8d5e-fe4d8339f4bf', 4,
  $plsc${"title":"Loi uniforme sur [0 ; b] : fonction de répartition","description":"F(x) = P(X ⩽ x) = x/b pour la loi uniforme sur [0 ; b] (figure)","variations":[{"blanks":[{"expectedAnswer":"{{eval:c/b}}"}],"statement":"La variable aléatoire $X$ suit la loi uniforme sur $\\left[0\\,;{{b}}\\right]$, de densité représentée ci-dessous. On note $F$ sa fonction de répartition : $F(x)=P(X\\leqslant x)$.\n\n```courbe\nx: -0.5 ; {{eval:b+1}}\ny: -0.05 ; {{eval:1/b+0.1;d}}\ngrille: 1 ; {{eval:1/b;d}}\nf(x) = 1/{{b}} sur [0 ; {{b}}]   bleu   nom=C_f\naire: f ; 0 ; {{c}}\ntaille: moyenne\ndescription: Densité constante sur [0 ; {{b}}], rectangle colorié entre 0 et {{c}}.\n```\n\nCalcule $F({{c}})$.\n\n$F({{c}})=?$","variables":[{"name":"b","expression":"4..10"},{"name":"c","expression":"1..{{eval:b-1}}"}],"correction":{"steps":["$F({{c}})=P(X\\leqslant {{c}})$ est l'aire du rectangle colorié, de largeur ${{c}}$ et de hauteur $\\dfrac{1}{ {{b}} }$.","$F({{c}})=\\dfrac{ {{c}} }{ {{b}} }=\\textcolor{{{color:primary.0}}}{{{eval:c/b}}}$."]}}],"shared":{"blankDefaults":{"acceptDecimal":true}},"test_specs":[{"answers":["\\frac{3}{8}"],"expected":{"status":"correct"},"variables":{"b":"8","c":"3"},"description":"v0 : b = 8, c = 3 → 3/8","variationIndex":0},{"answers":["\\frac{1}{8}"],"expected":{"status":"incorrect"},"variables":{"b":"8","c":"3"},"description":"v0 : hauteur 1/8","variationIndex":0}]}$plsc$::jsonb,
  $plsc$Probabilités$plsc$, $plsc$Autres lois$plsc$, $plsc$loi uniforme continue$plsc$);
