  $plsc${"title":"Théorème de Bézout : premiers entre eux ?","description":"sa − tb = 1 entraîne que a et b sont premiers entre eux (théorème de Bézout)","variations":[{"choices":[{"content":"$a$ et $b$ sont premiers entre eux"},{"content":"$\\mathrm{PGCD}(a \\,;\\, b) = {{s}}$"},{"content":"$a$ divise $b$"},{"content":"$a = {{t}}$ et $b = {{s}}$"}],"statement":"$a$ et $b$ sont des entiers tels que ${{s}}a - {{t}}b = 1$.\n\nQue peut-on en déduire ?","variables":[{"name":"s","expression":"2..9"},{"name":"t","expression":"2..9"}],"conditions":["s != t"],"correction":{"steps":["$au + bv = 1$ avec $u = {{s}}$ et $v = {{eval:-t}}$ entiers.","D'après le théorème de Bézout, $\\textcolor{{{color:primary.0}}}{a \\text{ et } b \\text{ sont premiers entre eux}}$."]},"correctChoiceIndex":["0"]}],"shared":null,"test_specs":[{"expected":{"status":"correct"},"variables":{"s":"3","t":"2"},"description":"v0 : premiers entre eux","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"s":"3","t":"2"},"description":"v0 : PGCD = s","variationIndex":0,"selectedChoices":[1]}]}$plsc$::jsonb,
