  $plsc${"title":"Distance entre deux points par le module","description":"AB = |z_B − z_A| (piège : |z_B| − |z_A|)","variations":[{"blanks":[{"expectedAnswer":"{{eval:sqrt((c-a)^2+(d-b)^2)}}"}],"statement":"Dans le plan complexe, $A$ et $B$ ont pour affixes $z_A={{a}}+({{b}})i$ et $z_B={{c}}+({{d}})i$. Calcule la distance $AB$.\n\n$AB=?$","variables":[{"name":"a","expression":"1..6;±"},{"name":"b","expression":"1..6;±"},{"name":"c","expression":"1..6;±"},{"name":"d","expression":"1..6;±"}],"conditions":["a != c","b != d"],"correction":{"steps":["$AB=|z_B-z_A|$ et $z_B-z_A={{eval:c-a}}+({{eval:d-b}})i$.","$AB=\\sqrt{ {{eval:(c-a)^2}}+{{eval:(d-b)^2}} }=\\textcolor{{{color:primary.0}}}{{{eval:sqrt((c-a)^2+(d-b)^2)}}}$."]}}],"shared":{"cleanCoefficients":true},"test_specs":[{"answers":["3\\sqrt{2}"],"expected":{"status":"correct"},"variables":{"a":"1","b":"2","c":"4","d":"-1"},"description":"v0 AB = 3√2","variationIndex":0},{"answers":["18"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"2","c":"4","d":"-1"},"description":"v0 AB² → 18","variationIndex":0},{"answers":["\\sqrt{17}-\\sqrt{5}"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"2","c":"4","d":"-1"},"description":"v0 |z_B| − |z_A| → √17 − √5","variationIndex":0}]}$plsc$::jsonb,
