insert into _plsc_neufs values ('31b49cdf-3d54-44e2-a01d-c4597f335758', '95f04c3e-03e1-4db4-a16e-36b713a2273f', 4,
  $plsc${"title":"Espace : distance d'un point à un plan","description":"Distance du point au plan, par son projeté orthogonal (pièges : MH², racine non simplifiée)","variations":[{"blanks":[{"expectedAnswer":"{{eval:abs(k)*sqrt(a^2+b^2+c^2)}}"}],"statement":"Dans l'espace muni d'un repère orthonormé, on considère le plan $\\mathcal{P}$ d'équation ${{a}}x+({{b}})y+({{c}})z+({{d}})=0$ et le point $M({{mx}}\\,;\\,{{my}}\\,;\\,{{mz}})$.\n\nCalcule la distance du point $M$ au plan $\\mathcal{P}$ (valeur exacte), c'est-à-dire la distance $MH$ où $H$ est le projeté orthogonal de $M$ sur $\\mathcal{P}$.\n\n$MH=?$","variables":[{"name":"a","expression":"1..3;±"},{"name":"b","expression":"-3..3"},{"name":"c","expression":"1..3;±"},{"name":"hx","expression":"-4..4"},{"name":"hy","expression":"-4..4"},{"name":"hz","expression":"-4..4"},{"name":"k","expression":"1..2;±"},{"name":"d","expression":"{{eval:-(a*hx+b*hy+c*hz)}}"},{"name":"mx","expression":"{{eval:hx+k*a}}"},{"name":"my","expression":"{{eval:hy+k*b}}"},{"name":"mz","expression":"{{eval:hz+k*c}}"},{"name":"mk","expression":"{{eval:-k}}"}],"correction":{"steps":["Le projeté $H$ est le point d'intersection de $\\mathcal{P}$ et de la droite passant par $M$ de vecteur directeur $\\vec{n}\\begin{pmatrix}{{a}}\\\\{{b}}\\\\{{c}}\\end{pmatrix}$ : $H({{if:mx!=0|{{mx}}}}{{if:a==1|{{if:mx!=0|+}}t}}{{if:a==-1|-t}}{{if:a>1|{{if:mx!=0|+}}{{a}}t}}{{if:a< -1|{{a}}t}}{{if:a==0|{{if:mx==0|0}}}}\\,;\\,{{if:my!=0|{{my}}}}{{if:b==1|{{if:my!=0|+}}t}}{{if:b==-1|-t}}{{if:b>1|{{if:my!=0|+}}{{b}}t}}{{if:b< -1|{{b}}t}}{{if:b==0|{{if:my==0|0}}}}\\,;\\,{{if:mz!=0|{{mz}}}}{{if:c==1|{{if:mz!=0|+}}t}}{{if:c==-1|-t}}{{if:c>1|{{if:mz!=0|+}}{{c}}t}}{{if:c< -1|{{c}}t}}{{if:c==0|{{if:mz==0|0}}}})$ pour un réel $t$.","En reportant dans l'équation de $\\mathcal{P}$ : ${{eval:a^2+b^2+c^2}}t{{eval:a*mx+b*my+c*mz+d;+}}=0$, donc $t={{mk}}$.","$H({{hx}}\\,;\\,{{hy}}\\,;\\,{{hz}})$ et $\\overrightarrow{MH}=t\\,\\vec{n}$ avec $t={{mk}}$, donc $MH=|t|\\times\\|\\vec{n}\\|={{eval:abs(k)}}\\times\\sqrt{{{eval:a^2+b^2+c^2}}}=\\textcolor{{{color:primary.0}}}{ {{eval:abs(k)*sqrt(a^2+b^2+c^2)}} }$."]}}],"shared":{"cleanCoefficients":true},"test_specs":[{"answers":["2\\sqrt{6}"],"expected":{"status":"correct"},"variables":{"a":"1","b":"2","c":"-1","k":"-2","hx":"1","hy":"0","hz":"2"},"description":"v0 : 2√6","variationIndex":0},{"answers":["\\sqrt{24}"],"expected":{"status":"unoptimal_form","constraintViolations":["reducedRadicals"]},"variables":{"a":"1","b":"2","c":"-1","k":"-2","hx":"1","hy":"0","hz":"2"},"description":"v0 : √24 non simplifiée","variationIndex":0},{"answers":["24"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"2","c":"-1","k":"-2","hx":"1","hy":"0","hz":"2"},"description":"v0 : MH² (24)","variationIndex":0},{"answers":["2"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"2","c":"-1","k":"-2","hx":"1","hy":"0","hz":"2"},"description":"v0 : |t| seul (2)","variationIndex":0}]}$plsc$::jsonb,
  null, null, null);
