cted":{"status":"incorrect"},"variables":{"n":"50","t":"2"},"description":"v0 : écart type √8","variationIndex":0},{"answers":["2,1"],"expected":{"status":"correct"},"variables":{"n":"10","t":"3"},"description":"v0 : B(10 ; 0,3) → 2,1","variationIndex":0},{"answers":["4"],"expected":{"status":"correct"},"variables":{"w":"6"},"description":"v1 : B(100 ; 0,2) → 4","variationIndex":1},{"answers":["16"],"expected":{"status":"incorrect"},"variables":{"w":"6"},"description":"v1 : variance 16","variationIndex":1},{"answers":["\\sqrt{16}"],"expected":{"status":"unoptimal_form","constraintViolations":["reducedRadicals"]},"variables":{"w":"6"},"description":"v1 : √16 non calculé","variationIndex":1}]}$plsc$::jsonb,
  null, null, null);
