  $plsc${"title":"Coefficient d'une primitive de la forme 2uu′","description":"Trouver k pour que k·u² soit une primitive de f : diviser par le facteur manquant de u′ (piège : multiplier)","variations":[{"blanks":[{"expectedAnswer":"{{eval:c/4}}"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)={{if:c==1|x}}{{if:c==-1|-x}}{{if:c!=1 && c!=-1|{{eval:c}}x}}(x^2{{if:m>0|+{{eval:m}}}}{{if:m<0|{{eval:m}}}})$.\n\nDétermine le réel $k$ tel que la fonction $F$ définie par $F(x)=k(x^2{{if:m>0|+{{eval:m}}}}{{if:m<0|{{eval:m}}}})^2$ soit une primitive de $f$ sur $\\mathbb{R}$.\n\n$k=?$","variables":[{"name":"c","expression":"1..6;±"},{"name":"m","expression":"1..9;±"}],"correction":{"steps":["Avec $u(x)=x^2{{if:m>0|+{{eval:m}}}}{{if:m<0|{{eval:m}}}}$, $u'(x)=2x$ et $(u^2)'=2u'u$ : $F'(x)=k\\times 2\\times 2x(x^2{{if:m>0|+{{eval:m}}}}{{if:m<0|{{eval:m}}}})=4k\\,x(x^2{{if:m>0|+{{eval:m}}}}{{if:m<0|{{eval:m}}}})$.","Il faut $4k={{eval:c}}$, soit $k=\\textcolor{{{color:primary.0}}}{{{eval:c/4}}}$."]}}],"shared":{"blankDefaults":{"acceptDecimal":true},"cleanCoefficients":true},"test_specs":[{"answers":["\\frac{1}{2}"],"expected":{"status":"correct"},"variables":{"c":"2","m":"1"},"description":"v0 : 2x(x²+1) → 1/2","variationIndex":0},{"answers":["1"],"expected":{"status":"incorrect"},"variables":{"c":"2","m":"1"},"description":"v0 : oubli du 2 de (u²)′","variationIndex":0},{"answers":["\\frac{2}{4}"],"expected":{"status":"unoptimal_form","constraintViolations":["reducedFractions"]},"variables":{"c":"2","m":"1"},"description":"v0 : fraction non simplifiée (½)","variationIndex":0}]}$plsc$::jsonb,
  null, null, null);
insert into _plsc_neufs values ('11eac96b-ee1d-4a42-ac8f-1dfc48e0e7a6', 'f01270c2-3c63-45c5-bfbb-8233154fadc6', 7,
  $plsc${"title":"Coefficient d'une primitive de la forme u′/u","description":"Trouver k pour que k·ln(u) soit une primitive de f : diviser par le facteur manquant de u′ (piège : multiplier)","variations":[{"blanks":[{"expectedAnswer":"{{eval:c/2}}"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)={{if:c<0|-}}\\dfrac{{{if:abs(c)==1|x}}{{if:abs(c)==-1|-x}}{{if:abs(c)!=1 && abs(c)!=-1|{{eval:abs(c)}}x}}}{x^2+{{eval:m}}}$.\n\nDétermine le réel $k$ tel que la fonction $F$ définie par $F(x)=k\\ln(x^2+{{eval:m}})$ soit une primitive de $f$ sur $\\mathbb{R}$.\n\n$k=?$","variables":[{"name":"c","expression":"1..6;±"},{"name":"m","expression":"1..9"}],"correction":{"steps":["Avec $u(x)=x^2+{{eval:m}}$, strictement positive, $u'(x)=2x$ et $(\\ln u)'=\\dfrac{u'}{u}$ : $F'(x)=k\\times\\dfrac{2x}{x^2+{{eval:m}}}$.","Il faut $2k={{eval:c}}$, soit $k=\\textcolor{{{color:primary.0}}}{{{eval:c/2}}}$."]}}],"shared":{"blankDefaults":{"acceptDecimal":true},"cleanCoefficients":true},"test_specs":[{"answers":["\\frac{3}{2}"],"expected":{"status":"correct"},"variables":{"c":"3","m":"4"},"description":"v0 : 3x/(x²+4) → 3/2","variationIndex":0},{"answers":["6"],"expected":{"status":"incorrect"},"variables":{"c":"3","m":"4"},"description":"v0 : u′ multiplié","variationIndex":0},{"answers":["3"],"expected":{"status":"incorrect"},"variables":{"c":"3","m":"4"},"description":"v0 : c recopié","variationIndex":0}]}$plsc$::jsonb,
